import Router = require('router');
import WebSocket = require("ws-without-native");
import GlobalListen from './GlobalListen';
import DialogListener from './DialogListener';
import findRoot = require("find-root");
import path = require('path');
import uuid = require('uuid');
import {
    ServiceOptions, HTTPWSService, JiboServerRequest, JiboServerResponse,
    RegistrationRecord, RegistryClient, WSClient
} from 'jibo-service-framework';
import {ListenResults, PronunciationOptions, NLU_STATUS} from "jibo-common-types";
import ASRService from "../../clients/asr/ASRService";
import { SpeakerIdStatusResult } from "../../clients/asr/Enroller";
import AudioAction from '../../clients/asr/AudioAction';
import {createLog} from "../../utils/Log";
import PerformanceService from "../performance-service/PerformanceService";
import {RuleManager} from "./RuleManager";

export interface WSResponse {
    status: string;
    message: string;
    id: string;
    result: any;
    moreinfo: string;
}

let log = createLog("ssm-listen-service");

class SingletonEnforcer {}

/**
 * @description
 * Listen Service. Manages Global Listening and ASR Requests
 * This class is primarily responsible for accepting and dispatching WS messages
 * and requests from `GLService` in the jibo module.
 * Additionally, it manages some overarching state from skills side, such as
 * global handling state (whether a skill can handle a global command) and
 * enrollment state.
 * It instantiates a `GlobalListen` instance.
 * @module skills-service-manager/services/listen-service
 */
class ListenService extends HTTPWSService {

    public static AudioAction = AudioAction;

    private static _instance:ListenService;

    private _listeners = new Map<string, DialogListener>();
    private _globalRuleUri:string = "";
    private listenSocket: WebSocket;
    private enroller: any;
    private nameListener: any;
    private nluSocket: WSClient;
    /**
     * Flag to see whether enrollment is taking place
     * If service crashes while enrolling, need to know to restart enroller.
     * @type {boolean}
     */
    private _isEnrolling: boolean = false;
    public static createInstance(options:ServiceOptions, rootDir:string):ListenService {
        return new ListenService(new SingletonEnforcer(), options, rootDir);
    }

    public static get instance():ListenService {
        return ListenService._instance;
    }

    constructor(enforcer: SingletonEnforcer, options:ServiceOptions, rootDir:string) {
        super('gl', options, rootDir);

        if(ListenService._instance) {
            throw new Error('ListenService is a singleton');
        }
        ListenService._instance = this;
        this.clearAllListeners = this.clearAllListeners.bind(this);
        log.info("Initialized");
    }

    public init(callback: (err?:Error)=>void):void {
        super.init((err:Error) => {
            if(err) {
                return callback(err);
            }

            this.initASRSocket();
            RegistryClient.instance.getRecords((err, records: Array<RegistrationRecord>) => {
                 if(err) {
                     return callback(err);
                 }
                 // loop through records to find NLU and that will have host and port.
                 records.forEach((record: RegistrationRecord) => {
                     if(record.name === 'nlu') {
                         this.initNLUSocket(record);
                     }
                 });
            });
            this.initializeService(callback);
        });
    }

    /**
     * Reset memory of the NLU Service and optionally reinitialize the global and launch rules.
     * @param callback {Callback} Callback for when memory is reset and launch rules reinitialized.
     * @param [shouldReload ]{Boolean} After clearing memory, we should attempt to reload the global and launch rules.
     * @public
     */
    public resetMemory(callback: (err?:Error|string)=>void, shouldReload=true):void {
        RuleManager.instance.resetMemory((err:Error) => {
            this.emit('reload-rules');
            if(shouldReload) {
                this.once('loop-uploaded', () => {
                    GlobalListen.getInstance().reloadRules((err) => {
                        if(err) {
                            console.error("Error reuploading rules ", err);
                        }
                        callback(err);
                    });
                });
            }
            else {
                callback(err);
            }
        });
    }

    protected onMessage(command:any, client:WebSocket):void {
        return;
    }

    protected onClose(client:WebSocket):void {
        // Happens on skill crash!
        this.listenSocket = undefined;
        this.clearAllListeners();
        this.resetInstance();
    }

    protected initASRSocket() {
        ASRService.instance.on('close', () => {
            const body: any = this.returnType('OK', 'socket-close', '', {});
            this.sendWsJson(this.listenSocket, body);
            GlobalListen.getInstance().resetListenersLocally();
        });
        ASRService.instance.on('reopen', () => {
            const body: any = this.returnType('OK', 'socket-reopen', '', {});
            this.sendWsJson(this.listenSocket, body);
            console.error('SERVICE CRASH; ASR SERVICE DISCONNECTED.');
            this.resetInstance(false);
        });
    }

    /**
     * initialize the NLU Socket to monitor NLU Service connection
     * @param service {RegistrationRecord} NLU Service information.
     * @protected
     */
    protected initNLUSocket(service:RegistrationRecord) {
        const nluSocketUrl:string = "ws:" + service.host + ":" + service.port + "/reset_memory";
        this.nluSocket = new WSClient(nluSocketUrl);

        this.nluSocket.on('open', (err, data) => {
            // nluSocket is open!
            GlobalListen.getInstance().setNluStatus(NLU_STATUS.CONNECTED);
        });

        this.nluSocket.on('error', (err, data) => {
            // nluSocket error, probably okay.
            console.error(err, data);
        });

        // NLU Service was down, but has now come back up.
        this.nluSocket.on('reopen', () => {
            // Recompile our stored rules from GL.
            GlobalListen.getInstance().setNluStatus(NLU_STATUS.CONNECTED);
            this.once('loop-uploaded', () => {
                GlobalListen.getInstance().reloadRules((err, result) => {
                    if(err) {
                        console.error("Error reuploading rules ", err);
                    }
                    const body:any = this.returnType('OK', 'nlu-reopen', '', {});
                    this.sendWsJson(this.listenSocket, body);
                });
            });
        });

        // NLU Service is down.
        this.nluSocket.on('close', () => {
            // NLU Service is down -- notify WS listeners.
            this.emit('nlu-close');
            GlobalListen.getInstance().setNluStatus(NLU_STATUS.DISCONNECTED);
            const body:any = this.returnType('OK', 'nlu-close', '', {});
            this.sendWsJson(this.listenSocket, body);

        });

        // NLU Service has WS message notification, not specifically
        // a response to a request.
        this.nluSocket.on('message', (data) => {
            // Once NLU Memory has been reset, we recompile our
            // stored rules from GL.
            const body:any = this.returnType('OK', 'nlu-message', '', data);
            this.sendWsJson(this.listenSocket, body);
            this.emit('nlu-message', data);
        });
    }

    public onConnection(client:WebSocket):void {
        super.onConnection(client);
        if(client.upgradeReq.url === '/listeners') {
            this.listenSocket = client;
        }
    }

    public routes(url:Router) {
        super.routes(url);

        url.post('/subscribe', (req:JiboServerRequest, res:JiboServerResponse) => {
            this.onSubscribe(req, res);
        });

        url.post('/unsubscribe', (req:JiboServerRequest, res:JiboServerResponse) => {
            this.onUnsubscribe(req, res);
        });

        url.post('/enroll', (req:JiboServerRequest, res:JiboServerResponse) => {
            this.onEnroll(req, res);
        });

        url.post('/metadata', (req:JiboServerRequest, res:JiboServerResponse) => {
            this.onMetadata(req, res);
        });

        url.post('/pronounce', (req:JiboServerRequest, res:JiboServerResponse) => {
            this.onPronunciation(req, res);
        });

        url.post('/spoof', (req:JiboServerRequest, res:JiboServerResponse) => {
            this.onSpoof(req, res);
        });

        url.post('/pause', (req:JiboServerRequest, res:JiboServerResponse) => {
            this.onPause(req, res);
        });

        url.post('/resume', (req:JiboServerRequest, res:JiboServerResponse) => {
            this.onResume(req, res);
        });

        url.post('/language', (req:JiboServerRequest, res:JiboServerResponse) => {
            this.onLanguage(req, res);
        });

        // would need this if we init'd from Be/another skill
        url.post('/update_global_rule', (req:JiboServerRequest, res:JiboServerResponse) => {
            this.updateGlobalRule(req, res);
        });
    }

    public resetInstance(resetNluMemory=true): void {
        const uri = GlobalListen.getInstance().getGlobalRule();

        // we remove listeners from the last instance, need to resubscribe to
        // new instance.
        GlobalListen.getInstance().events.listen.removeAllListeners();
        GlobalListen.getInstance().events.skillManager.removeAllListeners();
        if(resetNluMemory) {
            this.resetMemory(() => {
                this._resetInstance(uri);
            });
        }
        else {
            this._resetInstance(uri);
        }
    }

    /**
     * Wrapper to create a return type -- deprecated by interface.
     * @param status {string} status of response
     * @param message {string} accompanying message of response
     * @param id {string} listener id if applicable
     * @public
     */
    public returnType(status:string, message:string, id:string, data:any): WSResponse{
        let body: WSResponse = {
            status: status,
            message: message,
            id: id,
            result: data || {},
            moreinfo: ''
        };
        return body;
    }

    public sendWsJson(client:WebSocket, json: Object | string): void {
        if(client) {
            super.sendWsJson(client, json);
        }
    }

    /**
     * Reset the Global Listening instance
     * @param globalRuleUri {string} global rule URI for resetting GL instance.
     * @private
     */
    private _resetInstance(globalRuleUri) {
        GlobalListen._resetInstance({}, (err, instance) => {
            this.initGlobalListen(globalRuleUri, (err: Error):void => {
                if(err) {
                    console.error(err);
                }
                // When ASR Service crashes, jibo is expecting responses
                // with certain IDs.
                // Re-make those listeners with previous IDs so GL distributes
                // incoming ASR messages to orphaned skill listeners.
                this._listeners.forEach((listener) => {
                    // at this point, instance should be the same as GlobalListen.getInstance()
                    GlobalListen.getInstance().addDialogListener(listener);
                });

            });

            if(this.enroller && this._isEnrolling) {
                this._suspendIfNeeded(() => {
                    this.enroller.collectAndEnroll();
                });
            }
        });
    }


    private initializeService(callback?:(err?:Error)=>void):void {
        // get global settings rulepaths first
        let rulePaths:Array<string> = this.getRulePaths();
        this.emit('gotRulePaths', rulePaths);
        GlobalListen.createInstance(this.options);
        // If we are initializing the service, we've lost all handles to NLU rules,
        // So we should first clear out the memory.
        this.resetMemory(() => {
            GlobalListen.getInstance().getCombinedUri(rulePaths, (err:Error, uri:string) => {
                if (err)  {
                      return callback(err);
                }
                this._globalRuleUri = uri;
                this.emit('gotGlobalRule', uri);
                this.initGlobalListen(this._globalRuleUri, (err: Error, response: string) => {
                    callback(err);
                });
            });
        }, false);
    }


    /**
     * Subscribes a DialogListener
     * @param req {JiboServerRequest} the request data to be processed.
     * @param res {JiboServerResponse} the response to send through WS.
     * @private
     */
    private onSubscribe(req:JiboServerRequest, res:JiboServerResponse) {
        let data:any;
        let listenerId: string;
        req.on('data', (chunk) => {
            data = JSON.parse(chunk);
            this.emit('onSubscribe', data.rule);
            let body = this.returnType('subscribed', '', '', data);
            if(data.id) {
                listenerId = data.id;
                body.id = data.id;
                if (this._listeners.has(data.id)) {
                    body.status = 'subscribe-failed';
                    body.moreinfo = `Listener '${data.id}' already subscirbed`;
                }
            }
            else {
                listenerId = uuid.v4();
                body.id = listenerId;
            }
            // convert rule path to rule text
            let getRule:Function;
            switch(data.ruleType) {
                case 'text':
                    getRule = GlobalListen.getInstance().getUriFromText.bind(GlobalListen.getInstance());
                    break;
                case 'fst':
                    getRule = GlobalListen.getInstance().getUriFromFst.bind(GlobalListen.getInstance());
                    break;
                case 'handle':
                    getRule = (rule:string, cb:(err, ruleUri:string)=>void) => {
                        cb(null, rule);
                    };
            }
            getRule(data.rule, (err, ruleUri:string) => {
                this.emit("onRuleUri", ruleUri);
                if(err) {
                    console.error("ERROR: Could not subscribe listener", err);
                    return;
                }

                let listener: DialogListener = new DialogListener(ruleUri, data.options, listenerId);
                this._listeners.set(listenerId, listener);
                listener.events.cloudReceived.on((data) => {
                    if(!data) {
                        data = new ListenResults();
                    }
                    PerformanceService.instance.log(Date.now(), 'JiboCloudReturnSSM');
                    let body: any = this.returnType('OK', 'cloud', listenerId, data);
                    this.sendWsJson(this.listenSocket, body);
                    // we know when we receive this from GL, it has removed the listener.
                    listener.events.unsubscribed.emit();
                });
                listener.events.eos.on((data) => {
                    PerformanceService.instance.log(Date.now(), 'JiboEOSDetectSSM');
                    let body: any = this.returnType('OK', 'eos', listenerId, data);
                    this.sendWsJson(this.listenSocket, body);
                });
                listener.events.sos.on((data) => {
                    let body: any = this.returnType('OK', 'sos', listenerId, data);
                    this.sendWsJson(this.listenSocket, body);
                });
                listener.events.incremental.on((data) => {
                    let body: any = this.returnType('OK', 'incremental', listenerId, data);
                    this.sendWsJson(this.listenSocket, body);
                });
                listener.events.interrupted.on((data) => {
                    let body: any = this.returnType('OK', 'interrupt', listenerId, data);
                    this.sendWsJson(this.listenSocket, body);
                    // we know when we receive this from GL, it has removed the listener.
                    listener.events.unsubscribed.emit();
                });
                listener.events.unsubscribed.on((data) => {
                    // delete it from our map
                    this._listeners.delete(listenerId);
                    let body: any = this.returnType('OK', 'unsubscribed', listenerId, data);
                    this.sendWsJson(this.listenSocket, body);
                });
                listener.events.hjHeard.on((data) => {
                    PerformanceService.instance.log(Date.now(), 'JiboHJRecSSM');
                    let body: any = this.returnType('OK', 'hj-heard', listenerId, data);
                    this.sendWsJson(this.listenSocket, body);
                });
                listener.events.hjOnly.on((data) => {
                    PerformanceService.instance.log(Date.now(), 'JiboHJRecSSM');
                    let body: any = this.returnType('OK', 'hj-only', listenerId, data);
                    this.sendWsJson(this.listenSocket, body);
                    // we know when we receive this from GL, it has removed the listener.
                    listener.events.unsubscribed.emit();
                });
                listener.events.speakerId.on((data) => {
                    PerformanceService.instance.log(Date.now(), 'SpkrIdRecSSM');
                    let body: any = this.returnType('OK', 'speaker-id', listenerId, data);
                    this.sendWsJson(this.listenSocket, body);
                });

                GlobalListen.getInstance().addDialogListener(listener);
                this.sendJson(res, body, 200);

                // inform the SDK end that the rule has been compiled, so that MIMs can piggyback
                // off the rule instead of also compiling it themselves
                let rcBody: any = this.returnType('OK', 'rule-compiled', listenerId, ruleUri);
                this.sendWsJson(this.listenSocket, rcBody);
            });
        });
    }


    /**
     * Unsubscribes listener by request data Id.
     * @param req {JiboServerRequest} the request data to be processed.
     * @param res {JiboServerResponse} the response to send through WS.
     * @private
     */
    private onUnsubscribe( req:JiboServerRequest,  res:JiboServerResponse) {
        let data:any;
        let listenerId: string;
        req.on('data', (chunk) => {
            data = JSON.parse(chunk);
            let body = this.returnType('unsubscribed', '', '', data);
            if(data.id) {
                body.id = data.id;
                listenerId = body.id;
                if (!this._listeners.has(data.id)) {
                    body.status = 'FAILED';
                    body.message = `Listener '${data.id}' not found`;
                    this.sendJson(res, body, 200);
                    return;
                }
            }
            else {
                body.status = 'FAILED';
                body.message = 'no listener id to unsubscribe';
                this.sendJson(res, body, 200);
                return;
            }

            let listener = this._getListener(listenerId);
            // Notify listener so it can send unsubscribed through WS.
            listener.events.unsubscribed.emit();
            // remove it from the GL map
            GlobalListen.getInstance().removeDialogListener(listener);

            this.sendJson(res, body, 200);
        });
    }


    /**
     * Stops global listening and begins enroller
     * @param req {JiboServerRequest} the request data to be processed.
     * @param res {JiboServerResponse} the response to send through WS.
     * @private
     */
    private onEnroll( req:JiboServerRequest,  res:JiboServerResponse) {
        let data:any;
        req.on('data', (chunk) => {
            data = JSON.parse(chunk);
            let listenerId = data.id;
            let body = this.returnType('OK', 'enrollment-msg-received', '', data);
            this.sendJson(res, body, 200);
            console.log("LS ENROLLER COMMAND", data.action);
            if((!this.enroller || data.action  === 'start') && data.action !== 'stop') {
                this.enroller = ASRService.instance.createEnroller({speakerName: data.speakerId, enrollmentType: data.enrollmentType});

                this.enroller.on('saving-audio', (result:SpeakerIdStatusResult) => {
                    console.log("enroller emitting saving audio");
                    let body: any = this.returnType('OK', 'saving-audio', listenerId, result);
                    this.sendWsJson(this.listenSocket, body);
                });

                this.enroller.on('need-more-data', (result: SpeakerIdStatusResult) => {
                    console.log("enroller emitting nmd");
                    let body: any = this.returnType('OK', 'need-more-data', listenerId, result);
                    this.sendWsJson(this.listenSocket, body);
                });

                this.enroller.on('enrollment-started', () => {
                    let body: any = this.returnType('OK', 'started-enrollment', listenerId, {});
                    this.sendWsJson(this.listenSocket, body);
                });

                this.enroller.on('enrollment-done', (result:any, hjResult:any) => {
                    let returnResult = {
                        result: result,
                        hjResult: hjResult
                    };
                    let body: any = this.returnType('OK', 'finished-enrollment', listenerId, returnResult);
                    this.sendWsJson(this.listenSocket, body);
                    this.enroller = null;
                });

                this.enroller.on('enrollment-error', (err:any, data: any) => {
                    this._isEnrolling = false;
                    let body: any = this.returnType('OK', 'failed-enrollment', listenerId, data);
                    body.moreInfo = err;
                    this.sendWsJson(this.listenSocket, body);
                });

                this.enroller.on('error', (error) => {
                    throw new Error(error);
                });

                this.enroller.on('enrollment-event', () => {
                    this._isEnrolling = false;
                    this._unsuspendIfNeeded();
                });

                if(data.action === "collectSample" || data.action === "start") {
                    this._isEnrolling = true;
                    this._suspendIfNeeded(() => {
                        this.enroller.collectSample();
                    });
                }

                else if(data.action === "clearAndEnroll") {
                    this._isEnrolling = true;
                    this._suspendIfNeeded(() => {
                        this.enroller.clearAndEnroll();
                    });
                }

                else if(data.action === "collectAndEnroll") {
                    this._isEnrolling = true;
                    this._suspendIfNeeded(() => {
                        this.enroller.collectAndEnroll();
                    });
                }
            }

            else if(data.action === "collectSample") {
                this._isEnrolling = true;
                this._suspendIfNeeded(() => {
                    this.enroller.collectSample();
                });
            }

            else if(data.action === "collectAndEnroll") {
                this._isEnrolling = true;
                this._suspendIfNeeded(() => {
                    this.enroller.collectAndEnroll();
                });
            }

            else if(data.action === "clearAndEnroll") {
                this._isEnrolling = true;
                this._suspendIfNeeded(() => {
                    this.enroller.clearAndEnroll();
                });
            }

            else if(data.action === "clearData") {
                this._isEnrolling = true;
                this.enroller.clearPreviousData();
            }

            else if(data.action === "stop") {
                this._isEnrolling = false;
                if(this.enroller) {
                    this.enroller.stop();
                    this.enroller.removeAllListeners();
                    this.enroller = null;
                }
                this._unsuspendIfNeeded();
                body = this.returnType('OK', 'stopped-enrollment', '', data);
                this.sendJson(res, body, 200);
            }

            else {
                body = this.returnType('FAILED', 'failed-enrollment', 'invalid action request to enrollment. valid actions are "start" and "stop"', data);
                this.sendJson(res, body, 200);
            }

        });

     }

    /**
     * Pauses GL and starts pronunciation listener for data options
     * @param req {JiboServerRequest} the request data to be processed.
     * @param res {JiboServerResponse} the response to send through WS.
     * @private
     */
    private onPronunciation(req:JiboServerRequest, res:JiboServerResponse) {
        let data: any;
        req.on('data', (chunk) => {
            data = JSON.parse(chunk);
            let body = this.returnType('OK', 'pronunciation-started', '', data);
            let options:PronunciationOptions = data.options;
            this.sendJson(res, body, 200);
            if(options.action === "generateG2P") {
                this.nameListener = ASRService.instance.createNameListener(options);
                this.nameListener.on('generated-pronun', (pronunciations:any) => {
                    let body: any = this.returnType('OK', 'generated-pronun', options.listenerId, pronunciations);
                    this.sendWsJson(this.listenSocket, body);
                });
                this.nameListener.on('heard-pronun', (pronunciations:any) => {
                    let body: any = this.returnType('OK', 'heard-pronun', options.listenerId, pronunciations);
                    this.sendWsJson(this.listenSocket, body);
                });
                this.nameListener.on('pronun-error', (pronunciations:any) => {
                    let body: any = this.returnType('OK', 'pronun-error', options.listenerId, pronunciations);
                    this.sendWsJson(this.listenSocket, body);
                });
                this.nameListener.on('error', (error) => {
                    console.error('error: ', error);
                    throw new Error(error);
                });
                this.nameListener.on('finished', () => {
                    this._unsuspendIfNeeded(() => {
                        let resumed = this.returnType('OK', 'gl-started', '', {});
                        this.sendWsJson(this.listenSocket, resumed);
                    });
                });
                this.nameListener.start();
            }

            else if(options.action === "collectExample") {
                if(!this.nameListener) {
                    let err: any = this.returnType('FAILED', 'pronun-error', '', {});
                    err.message = "Error: cannot collect acoustic example without g2p model. Must start pronunciation listener before collecting example.";
                    this.sendWsJson(this.listenSocket, err);
                    return;
                }
                this._suspendIfNeeded(() => {
                    let paused: any = this.returnType('OK', 'gl-stopped', '', {});
                    this.sendWsJson(this.listenSocket, paused);
                    this.nameListener.collectExample();
                });
            }

            else if(options.action === "stop" && this.nameListener) {
                // don't need to resume, emits 'finished' and resumes from there.
                this.nameListener.stop();
            }

            else {
                let body = this.returnType('FAILED', 'invalid action request to pronunciation interface', '', {});
                this.sendWsJson(this.listenSocket, body);
            }
        });
    }

    /**
     * Sends options from request data to ASR service to spoof utterance
     * @param req {JiboServerRequest} the request data to be processed.
     * @param res {JiboServerResponse} the response to send through WS.
     * @private
     */
    private onSpoof(req: JiboServerRequest, res: JiboServerResponse):void {
        req.on('data', (chunk) => {
            let data = JSON.parse(chunk);
            let utterance = data.utterance;
            let speaker = data.speaker;
            ASRService.instance.spoofUtterance(utterance, speaker);

            let body = this.returnType('OK', 'spoofed-utterance', '', {});
            this.sendJson(res, body, 200);
        });
    }

    /**
     * Pauses global listening
     * @param req {JiboServerRequest} the request data to be processed.
     * @param res {JiboServerResponse} the response to send through WS.
     * @private
     */
    private onPause(req: JiboServerRequest, res: JiboServerResponse):void {
        // don't care if already paused, swallow error
        GlobalListen.getInstance().suspendHJListening().then(() => {
            let paused: any = this.returnType('OK', 'gl-stopped', '', {});
            this.sendJson(res, paused, 200);
            this.sendWsJson(this.listenSocket, paused);
        });
    }

    /**
     * Resumes global listening
     * @param req {JiboServerRequest} the request data to be processed.
     * @param res {JiboServerResponse} the response to send through WS.
     * @private
     */
    private onResume(req: JiboServerRequest, res: JiboServerResponse):void {
        // don't care if already listening, swallow error
        GlobalListen.getInstance().resumeHJListening().then(() => {
            let resumed: any = this.returnType('OK', 'gl-started', '', {});
            this.sendJson(res, resumed, 200);
            this.sendWsJson(this.listenSocket, resumed);
        });
    }

    /**
     * Initializes the global listening service.
     * Sets default ASR language
     * @param req {JiboServerRequest} the request data to be processed.
     * @param res {JiboServerResponse} the response to send through WS.
     * @private
     */
    private onLanguage(req: JiboServerRequest, res: JiboServerResponse):void {
        req.on('data', (chunk) => {
            let language = JSON.parse(chunk);
            let setLang = GlobalListen.getInstance().setLanguage(language);
            let body = this.returnType('OK', 'language:' + language, '', {});
            if(!setLang) {
                body.status = 'FAILED';
                body.message = 'unaccepted language option. Options include en-US, ja-JP, zh-CN';
            }
            this.sendJson(res, body, 200);
        });
    }


    /**
     * Sets metadata for all upcoming listeners
     * @param req {JiboServerRequest} the request data to be processed.
     * @param res {JiboServerResponse} the response to send through WS.
     * @private
     */
    private onMetadata(req: JiboServerRequest, res: JiboServerResponse):void {
        req.on('data', (chunk) => {
            let data = JSON.parse(chunk);
            let meta = data.metadata;
            GlobalListen.getInstance().setMetadata(meta);
            let body = this.returnType('OK', 'metadata:' + JSON.stringify(meta), '', {});
            this.sendJson(res, body, 200);
        });
    }


    /**
     * Initializes the global listening service.
     * @param ruleUri {string} Uri of the global rule to parse against.
     * can be overridden by gl.setGlobalRule
     * @param callback {Function} callback for when GL is done initializing.
     * @private
     */
    private initGlobalListen(ruleUri:string, callback):void {
        GlobalListen.getInstance().init(ruleUri, (err:string) => {
            if(err) {
                console.error("Error initializing GL ", err);
            }
            let glListenEvents = GlobalListen.getInstance().events.listen;
            let glGlobalEvents = GlobalListen.getInstance().events.skillManager;

            //  Register outgoing events and handling them in the client
            glListenEvents.cloudReceived.on((data) => {
                this.emit('cloud-received');
                PerformanceService.instance.log(Date.now(), 'JiboCloudReturnSSM');
                let body:any = this.returnType('OK', 'cloud', '', data);
                this.sendWsJson(this.listenSocket, body);
            });
            glListenEvents.hjOnly.on((data) => {
                this.emit('hj-only');
                PerformanceService.instance.log(Date.now(), 'JiboHJOnlySSM');
                let body:any = this.returnType('OK', 'hj-only', '', data);
                this.sendWsJson(this.listenSocket, body);
            });
            glListenEvents.eos.on((data) => {
                PerformanceService.instance.log(Date.now(), 'JiboEOSDetectSSM');
                let body:any = this.returnType('OK', 'eos', '', data);
                this.sendWsJson(this.listenSocket, body);
            });
            glListenEvents.listenFinished.on((data) => {
                let body:any = this.returnType('OK', 'finished', '', data);
                this.sendWsJson(this.listenSocket, body);
            });
            glListenEvents.hjHeard.on((data) => {
                PerformanceService.instance.log(Date.now(), 'JiboHJRecSSM');
                this.emit('hj-heard');
                let body:any = this.returnType('OK', 'hj-heard', '', data);
                this.sendWsJson(this.listenSocket, body);
            });
            glListenEvents.speakerId.on((data) => {
                PerformanceService.instance.log(Date.now(), 'JiboSpkrIdRecSSM');
                this.emit('speaker-id');
                let body:any = this.returnType('OK', 'speaker-id', '', data);
                this.sendWsJson(this.listenSocket, body);
            });
            glListenEvents.incremental.on((data) => {
                this.emit('incremental');
                let body:any = this.returnType('OK', 'incremental', '', data);
                this.sendWsJson(this.listenSocket, body);
            });
            glListenEvents.noGlobalMatch.on((data) => {
                let body:any = this.returnType('OK', 'no-global', '', data);
                this.sendWsJson(this.listenSocket, body);
            });
            glListenEvents.startNonHjListen.on((data) => {
                let body:any = this.returnType('OK', 'start-non-hj', '', data);
                this.sendWsJson(this.listenSocket, body);
            });
            glGlobalEvents.globalCommand.on((results: ListenResults) => {
                let body:any = this.returnType('OK', 'global', '', results);
                this.sendWsJson(this.listenSocket, body);
                this.emit('global-command', results);
            });
            glGlobalEvents.nonInterruptingGlobal.on(() => {
                let body:any = this.returnType('OK', 'non-interrupting-global', '', '');
                this.sendWsJson(this.listenSocket, body);
            });
            callback();
        });
    }


    // not currently doing the right thing!! NEeds to take URIs!!
    private updateGlobalRule(req: JiboServerRequest, res: JiboServerResponse):void {
        let rulePath: string;
        req.on('data', (chunk) => {
            let data:any = JSON.parse(chunk);
            rulePath = data.rulePath;
            let body:any = this.returnType('OK', '', '', data);
            this.sendJson(res, body, 200);
        });
        GlobalListen.getInstance().getNluUri(rulePath, (error:Error, ruleUri:string):void => {
            if(error) {
                log.error(error);
                return;
            }
            GlobalListen.getInstance().getCombinedUri([ruleUri, this._globalRuleUri], (error:Error, combinedPath:string) => {
                if(error) {
                    log.error(error);
                    return;
                }
                GlobalListen.getInstance().setGlobalRule(combinedPath);
            });
        });
    }



    private _getListener(listenerId: string) {
        let listener = this._listeners.get(listenerId);
        if (!listener) {
          throw new Error(`No listener of id '${listenerId}' subscribed`);
        }
        return listener;
    }

   /**
    * Gets the rule paths for global settings, such as volume,
    * stop, cancel, help, repeat.
    * @method module:ListenService~getRulePaths
    * @private
    */
    private getRulePaths():Array<string> {
        let rulePaths: Array<string> = [];
        let root:string = findRoot(__dirname);
        rulePaths.push(path.join(root, 'resources/rules/GlobalCommandsLaunch.rule'));
        // rulePaths.push(path.join(root, 'rules/mimGlobal.rule'));
        return rulePaths;
    }

    private clearAllListeners():void {
        // Removing Dialog Listeners from GL happens in GL reset
        // But GL will know whether it has removed already or not.
        this._listeners.forEach((listener) => {
            GlobalListen.getInstance().removeDialogListener(listener);
        });
        // TODO: test if this is an ok way to delete/free old things.
        this._listeners = new Map<string, DialogListener>();
    }

   /**
    * Suspends GL if not already suspended
    * @method module:ListenService~_suspendIfNeeded
    * @private
    */
    private _suspendIfNeeded(cb?) {
        let isSuspended = (GlobalListen.getInstance()._sm.current === GlobalListen.getInstance()._sm.suspended);
        if(isSuspended) {
            this._callIfExists(cb);
            return;
        }
        GlobalListen.getInstance().suspendHJListening().then(() => {
            console.log("suspended GL");
            let paused: any = this.returnType('OK', 'gl-stopped', '', {});
            this.sendWsJson(this.listenSocket, paused);
            this._callIfExists(cb);
        });
    }

   /**
    * Unuspends GL if not already suspended
    * @method module:ListenService~_unsuspendIfNeeded
    * @private
    */
    private _unsuspendIfNeeded(cb?) {
        let isSuspended = (GlobalListen.getInstance()._sm.current === GlobalListen.getInstance()._sm.suspended);
        if(!isSuspended) {
            this._callIfExists(cb);
            return;
        }
        GlobalListen.getInstance().resumeHJListening().then(() => {
            console.log("resumed GL");
            let resumed: any = this.returnType('OK', 'gl-started', '', {});
            this.sendWsJson(this.listenSocket, resumed);
            this._callIfExists(cb);
        });
    }

    private _callIfExists(cb) {
        if(cb) {
            cb();
        }
    }
}


export default ListenService;
