import {EventEmitter} from 'events';
import ASRService from "./ASRService";
import { UrlInterface } from "./ASRService";

export type UTTStatus =
    "SAVING_AUDIO" |
    "ENROLLMENT-DONE" | 
    "ENROLLMENT-STARTED" |
    "NEED-4-MORE-UTTS" |
    "NEED-3-MORE-UTTS" |
    "NEED-2-MORE-UTTS" |
    "NEED-1-MORE-UTT";

export interface SpeakerIdStatusResult {
    status: UTTStatus;
    noisy: boolean;
    loudness: string;
    badAudio: boolean;
    snrValue: number;
    numRequired?: number;
};

enum EnrollMode {
    "CLEAR_SPEAKERS" = 0,
    "SAVE_AUDIO" = 1,
    "SAVE_AND_ENROLL" = 2
}


/**
 * This constructs an enroller.
 *
 * An enroller will continue to listen until it emits 'enrollment-succeeded'.
 * At this point it will unsubscribe all listeners and destroy itself.
 * Enrollment requires at least four "Hey Jibo"s, after which it will emit either
 * "result" or it will emit "need-more-data" with the number of utterances
 * still required.
 *
 * @param options {Object} Listen options
 * @param options.enrollmentType {enum} "text-dependent" or "text-independent"
 * @param options.speakerName {String} name of speaker to enroll
 * @returns {module:jibo.services.asr.Enroller} Enroller with given recognition options
 *
 * ```
 * this.enroller = asr.createEnroller(options, rule);
 * this.enroller.start();
 * ```
 * Listener will start emitting events. Possible events are:
 * ```
 * this.enroller.on('result', (speakerResults) => {
 *      // Use the recognition result
 *      asr.listEnrolledSpeakers(function(data){
 *          //the speaker will be listed in the data.
 *      });
 * });
 * this.enroller.on('need-more-data', (numberRequired) => {
 *      // numberRequired is the number of utterances of
 *      // "Hey, Jibo" still required for enrollment
 * })
 *
 * this.enroller.on('enrollment-started', () => {
 *      // enrollment has begun after 4 "hey jibo"s
 * })
 * ```
 * @class Enroller
 * @extends {EventEmitter}
 * @memberof module:jibo.services.asr
 */

class Enroller extends EventEmitter {

	private callback: any;
	private speakerName: string;
	private enrollmentType: string;
	private action: any;
	private nSavingAudios: number;
	private task: string;
    private sendTD: boolean;
	private heyJiboResult: any;
    private enrollMode: EnrollMode;

    constructor(options, cb?){
        super();
        this.callback = cb;
        this.speakerName = options.speakerName;
        this.enrollmentType = options.enrollmentType;
        this.nSavingAudios = 0;
        this.sendTD = (this.enrollmentType === "text-dependent");
        // previously used to start enroller
        if(!ASRService.instance.isInitialized) {
            console.warn('Running enroller without ASR service');
        }
    }

    _emitEnrollmentResult(result:SpeakerIdStatusResult) {
        console.log("emitting enrollment result", result.status);

        // add NOT USED status b/c bug in enrollment service sometimes sends it.
        if(result.status as string === "SAVING_AUDIO" ||
            result.status as string === "NOT_USED") {
            result.numRequired = ++this.nSavingAudios;
            this.emit('saving-audio', result);
        }

        else if(result.status as string === "NEED-4-MORE-UTTS" ||
                result.status as string === "NEED-3-MORE-UTTS" ||
                result.status as string === "NEED-2-MORE-UTTS" ||
                result.status as string === "NEED-1-MORE-UTTS") {
                    // need more data, need to resend with new action.
                    // can't clear old action, because it'll clear itself with the
                    // composite reco
                    result.numRequired = parseInt(result.status[5]);
                    this.emit('need-more-data', result);
                    // this.action = undefined;
                    return;
        }
        else if(result.status === "ENROLLMENT-STARTED") {
            this.emit('enrollment-started');
            return;
        }

        if(result && result.status === "ENROLLMENT-DONE") {
            this.emit('enrollment-done', result, this.heyJiboResult);
            // don't stop here -- action finishes via ASR.
            return;
        }
    }

    _addHeyJibo() {
        let heyJibo = new ASRService.instance.Recognizer(
            {
                path: 'hey_jibo',
                timeout: 0,
                bargein: true,
                nbest: 1,
                delay: 300,
                speakerName: "",
                incremental: false,
                speakerId: false
            }
        );
        heyJibo.on('result', (result) => {
            this.heyJiboResult = result;
        });
        return `${heyJibo.pack()}`;
    }

    /**
     * Organize data to start old action with HJ + Speaker Enroll.
     * @method module:skills-service-manager/clients/asr.Enroller#_startCollectionInstance
     * @public
     */
    _startCollectionInstance() {
        if(!this.speakerName) {
            this.speakerName = "NO_NAME_PROVIDED_FOR_ENROLLMENT";
        }        
        let enroller = new ASRService.instance.SpeakerRecognizer(
            {
                enrollTD: this.sendTD,
                enrollTI: !this.sendTD,
                speakerName: this.speakerName,
                timeout: 5000,
                bargein: false,
                nbest: 1,
                enroll_mode: this.enrollMode,
                incremental: false
            }
        );
        enroller.on('result', (result:SpeakerIdStatusResult) => {
            this._emitEnrollmentResult(result);
        });
        let task = `${enroller.pack()}`;
        task = `${this._addHeyJibo()} * ${task}`;

        this.action = ASRService.instance.createAudioAction(UrlInterface.OLD);
        this.action.on('finished', () => {
            this.stop(() => {
                this.emit('enrollment-event');
            });
        });
        ASRService.instance.setEnrollerId(this.action.id);        
        this.action.startOldTask(task);        
    }

    collectSample() {
        console.log("collecting sample");
        // set task enroll mode to 1
        this.enrollMode = EnrollMode.SAVE_AUDIO;
        this._startCollectionInstance();
    }

    collectAndEnroll() {
        console.log("collecting and enrolling");
        // set task enroll mode to 2
        this.enrollMode = EnrollMode.SAVE_AND_ENROLL;
        this._startCollectionInstance();
    }

    clearAndEnroll() {
        console.log("clearing and enrolling");
        // set task enroll mode to 2
        this.enrollMode = EnrollMode.CLEAR_SPEAKERS;
        this._startCollectionInstance();
    }

    clearPreviousData() {
        // TODO: this doesn't naturally clear
        let clearAction = ASRService.instance.createAudioAction(UrlInterface.OLD);
        this.enrollMode = EnrollMode.CLEAR_SPEAKERS;
        clearAction.on('finished', () => {
            clearAction.stopOldTask(() => {
                clearAction.clearOldTask(() => {
                    this.emit('enrollment-event');
                });
            });
        });
        clearAction.startOldTask(this.task);
    }

    stop(cb?) {
        if(!this.action) {
            if(cb) {
                cb();
            }
            return;
        }
        this.action.stopOldTask(() => {
            this.action.clearOldTask(() => {
                if(cb) {
                    cb();
                }
            });
        });
    }
}

export default Enroller;