// OTA updater
import jibo = require('jibo');
import JiboLog = require("jibo-log");
import WifiService from "../services/wifi-service/WifiService";
import KBService from "../services/kb-service/KBService";
import BodyClient from "../clients/BodyClient";

// Knowledge-base directory
const OTA_KB = '/ota';

// error codes we care about
// @TODO - would be good to ask KB or Error Service about these
const PLUG_ERROR = 'OTA10';
const WIFI_ERROR = 'OTA1';
const INTERNET_ERROR = 'OTA4';
const UHOH_ERROR = 'OTAX';


export interface OTARecord {
    id:string;
    subsystem:string;
    changes:string;
    length:number;
    toVersion:string;
    dependencies:any;
    downloaded:boolean;
}

interface OTADownloadStatus {
    id:string;
    length:number;
    received:number;
    status:string;
    reason?:string;
    error?:string;
}

/**
 * A class for handling OTA checking, downloading and installing.
 *
 * @class OTAUpdater
 * @private
 */
class OTAUpdater {
    private static _instance: OTAUpdater = null;
    private _log:JiboLog = null;
    private _downloadStatus:{
        updates:Array<OTARecord>,
        status?:OTADownloadStatus
    };

    public static createInstance(log:JiboLog):OTAUpdater {
        if (!OTAUpdater.instance) {
            return new OTAUpdater(log);
        }

        return OTAUpdater.instance;
    }

    public static get instance():OTAUpdater {
        return OTAUpdater._instance;
    }

    constructor(log:JiboLog) {
        if (OTAUpdater._instance) {
            throw new Error('OTAUpdater is a singleton');
        }

        this._log = log;
        OTAUpdater._instance = this;

        this._resetDLStatus();

        this._log.info("Initialized OTAUpdater");
    }

    /**
     * Checks if current environment is ready to start OTA (download or installation).
     * @param {Function} callback Function
     */
    public isReady(callback:(error:Error, kbRoot?:any /*jibo.kb Node*/) => void): void {

        const kbUrl:string = 'http://localhost:' + KBService.instance.options.port;
        let kbm = null;
        try {
            kbm = jibo.kb.createModel(OTA_KB, kbUrl);
        }
        catch(e) {
            callback(e);
            return;
        }

        // load up KB for ota-related flags
        kbm.loadRoot((error, root)=> {

            // bail out if we couldn't get access to KB
            if (error || !root || !root.data) {
                const msg = new Error("Couldn't load OTA root KB on attempt install");
                this._doLog(msg);

                return callback(msg);
            }

            // check if the robot is plugged in
            if (!BodyClient.instance.pluggedIn) {
                root.data.error = PLUG_ERROR;
                let msg = new Error(root.data.error + ": Couldn't start OTA process cause not plugged in");
                root.save((error)=> {
                    if (error) {
                        msg = new Error(root.data.error + ": Couldn't save OTA plug error status");
                        this._doLog(msg);
                    }

                    return callback(msg);
                });
            }
            else {
                // Check that we have a current network (doesn't mean on internet)
                WifiService.instance.getCurrentNetwork((error, currentNetwork)=> {

                    // bail out if no network
                    if (error || !currentNetwork || currentNetwork.ssid === undefined) {

                        root.data.error = WIFI_ERROR;
                        let msg = new Error(root.data.error + ": Couldn't start OTA process cause no WiFi: " + error);
                        this._doLog(msg);

                        root.save((error)=> {
                            if (error) {
                                msg = new Error(root.data.error + ": Couldn't save OTA wifi error status");
                                this._doLog(msg);
                            }

                            return callback(msg);
                        });
                    }
                    else {
                        // We have a network, but check that we are connected to AP, IP and internet
                        WifiService.instance.verifyConnection((error)=> {

                            // bail out if failure
                            if (error) {
                                if (error.code) {
                                    root.data.error = (error.code === 1 ? WIFI_ERROR : INTERNET_ERROR);
                                }
                                else {
                                    root.data.error = UHOH_ERROR;
                                }
                                let msg = new Error(root.data.error + ": Couldn't start OTA process cause no internet: " + error);
                                this._doLog(msg);

                                root.save((err)=> {
                                    if (err) {
                                        msg = new Error(root.data.error + ": Couldn't save OTA internet error status");
                                        this._doLog(msg);
                                    }

                                    return callback(msg);
                                });
                            }
                            else {
                                // yay! we're good
                                callback(null, root);
                            }
                        }); // verifyConnection
                    }
                }); // getCurrentNetwork
            }
        }); // loadRoot
    }


    public getDownloadStatus(callback:(error:Error, data?:any) => void):void {
        if (this._downloadStatus.updates.length === 0) {
            return callback(new Error('OTA download is not running'));
        }

        callback(null, this._downloadStatus);
    }


    /**
     * Triggers an OTA download and install if packages exist.
     * @param {Function} callback Function
     */
    public downloadAndInstall(callback:(error?:Error) => void): void {

        // reset our dl status
        this._resetDLStatus();

        this._doLog('Starting ota update!');

        this.isReady((error, kbRoot) => {
            if (error) {
                callback(error);
                return;
            }

            callback(); // yay! return now and let stuff just keep going in background

            // Start recursive downloads of all available packages
            this._startNextDownload((error:Error, ids?:Array<string>) => {

                // if problem, return and don't install
                if (error) {
                    this._resetDLStatus();
                    this._doLog(error);

                    // check connection to get error code
                    WifiService.instance.verifyConnection((error)=> {

                        // save off error code in KB if applicable
                        if (error && error.code) {
                            kbRoot.data.error = (error.code === 1 ? WIFI_ERROR : INTERNET_ERROR);
                        }
                        else {
                            kbRoot.data.error = UHOH_ERROR;
                        }

                        // save error code
                        kbRoot.save((err)=> {
                            if (err) {
                                this._doLog("Couldn't save OTA download error status");
                            }
                        });
                    });

                    return;
                }

                // clear KB OTA-related flags
                kbRoot.data.updatesAvailable = false;
                kbRoot.save((error) => {
                    // oh, not so fast...
                    if (error) {
                        const msg = new Error("Couldn't save OTA post-downloading status");
                        this._doLog(msg);
                        return;
                    }

                    // check again if we're ready
                    this.isReady((error) => {
                        if (error) {
                            return;  // bail; we've already logged a bunch of stuff
                        }

                        // start installation!
                        this._doLog('Starting ota installation! C-ya on the flip side.');

                        jibo.systemManager.installUpdates({ids}, (error?: Error) => {

                            if (error) {
                                this._doLog(error);
                                return;
                            }

                        });  // installUpdates
                    }); // isReady
                }); // root.save
            });  // startNextDownload
        }); // isReady
    }

    private _startNextDownload(callback:(error:Error, ids?:Array<string>) => void):void {
        // find next one that isn't downloaded
         jibo.systemManager.checkForUpdates((error: any, data?: Array<OTARecord>) => {
             // reset our dl status
             this._resetDLStatus();

             if (error || !data) {
                const msg = error ? error : 'Service temporarily unavailable.';
                return callback(new Error(msg));
             }

             const count = data.length;
             if (count === 0) {
                 return callback(new Error('No updates found.'));
             }

             let nextId = [];
             let doneIds = [];
             for (let i = 0; i < count; i++) {
                 if (data[i].downloaded) {
                     doneIds.push(data[i].id);
                 }
                 else if (nextId.length === 0) {
                     // only add one
                     nextId.push(data[i].id);
                 }
             }

             if (nextId.length > 0) {
                 this._doLog('Starting ota download: ' + nextId);

                 // shallow copy of current updates
                 this._downloadStatus.updates = data.slice();

                 // download updates one at a time
                 jibo.systemManager.downloadUpdates({ids: nextId}, (err: any, dlData: any) => {

                     this._downloadStatus.status = Object.assign({}, dlData);

                     if (err || dlData.status === 'failed' || dlData.error) {
                         this._resetDLStatus();
                         const msg = (err || dlData.reason || dlData.error);
                         return callback(new Error('Error downloading OTA updates: ' + msg));
                     }

                     if (dlData.status === 'finished') {
                         this._startNextDownload(callback);
                     }

                 });
             }
             else {
                 // reset our dl status
                 this._resetDLStatus();

                 // all done!
                 callback(null, doneIds);
             }
         });
     }

     private _resetDLStatus() {
         this._downloadStatus = {
             updates: [],
             status: null
         };
     }

     private _doLog(msg:(Error|string)) {
         if (this._log) {
             this._log.info(msg);
         }
     }
}

export default OTAUpdater;