import {
    StateMachine,
    State,
    TimeoutTransition
} from 'jibo-state-machine';

import GlobalListen, {_GlobalListen, ListenerType} from './GlobalListen';
import {
    ListenResults,
    ParseResults, GlobalCommand
} from 'jibo-common-types';


import InterruptListenersState from './states/InterruptNonHJListenersState';
import ParseGlobalState from './states/ParseGlobalState';
import GlobalManagerService from "../global-service/GlobalManagerService";
import {createLog} from "../../utils/Log";

const log = createLog("gl-state-machine");

export const SMEvents = {
    AddNonHJList: 'AddNonHJList',
    RemLastNonHJList: 'RemLastNonHJList',
    ListenCloud: 'ListenCloud',
    ListenFinished: 'ListenFinished',
    HJHeard: 'HJHeard',
    Suspend: 'Suspend',
    UnSuspend: 'UnSuspend',
};

export interface GLOptions {
    hjOnlyTimeout?: number; // milliseconds
    nonInterruptingState?: State;
    handleGlobalParseState?: State;
    handleLaunchParseState?: State;
}

export enum ParseLaunch {
    DO_NOT_PARSE_LAUNCH,
    HJ_HEARD,
    FORCE_GLOBAL
};

/**
 * @description
 * GLStateMachine
 * This implements the state machine for the Global Listening system in jibo.
 * It always reverts back to `hjList` as jibo should normally be listening for Hey Jibo.
 * @module skills-service-manager/services/listen-service/GLStateMachine
 */
export default class GLStateMachine extends StateMachine {

    // All the different states
    // listening for hey jibo, then we will start a cloud listen.
    public hjList = new State(this, 'HJ Listening');
    // ALL listening is suspended; no new messages from the listening service
    // will emit
    // used for enrollment, when we want to hear HJ but outside of
    // usage context.
    public suspended = new State(this, 'Suspended');
    public wait1 = new State(this, 'Wait1');
    // If we have any listeners waiting to be added while we were doing another
    // listener, we do that here.
    public processQueue = new State(this, 'Process Add Listeners Queue');
    // Start listening for cloud results without HJ -- entered via
    // skill request to start a listen (like in a turn of dialog)
    public startNHJList = new State(this, 'Start Non-HJ Listening');
    public wait2 = new State(this, 'Wait2');
    // Dispatch the parsed message to all listeners -- does not
    // compute whether we dispatch to HJ or NHJ listeners.
    public dispatchDialog = new State(this, 'Dispatch Dialog');
    // A global parse won, so dispatch based on parse.
    // Since global commands sometimes interrupt skill and require action from SSM,
    // do that here.
    public handleGlobalParse = new State(this, 'Handle Global Parse');
    // A launch parse won -- requires action from SSM so do that here.
    public handleLaunchParse = new State(this, 'Handle Launch Parse');
    // Determine if the speech we heard included HJ, since launches
    // can only be parsed with HJ.
    public HJOrNoHJ = new State(this, 'Determine HJ or No HJ');
    // After we hear HJ, see if we get any incremental results. This
    // rules out the possibility of hearing ONLY HJ.
    public waitIncr = new State(this, 'Wait Incremental');
    // After we get incremental results, we wait until we get the
    // notice from ASR Service that listen is finished (final cloud result).
    public waitListenFin = new State(this, 'Wait ListenFinished');
    // emit Hey jibo only and return to HJ listening.
    public emitHJO = new State(this, 'emit HeyJiboOnly');
    // check if we only heard Hey Jibo.
    public checkHJO = new State(this, 'Check for HJO');
    // Listeners have to be interrupted.
    public interrupt1 = new InterruptListenersState(this,
        'Interrupt NonHJ listeners1', this.hjList);
    // Listeners have to be interrupted.
    public interrupt2 = new InterruptListenersState(this,
        'Interrupt NonHJ listeners2', this.processQueue);
    // See comments in ParseGlobalState.
    public parseAgainstRules: ParseGlobalState;

    constructor(public gl: _GlobalListen, options?: GLOptions) {
        super();
        if (!options) {
            options = {};
        }

        // set native skill map based on dynamically generated from options, or default.

        // preliminary default timeout from Design.
        options.hjOnlyTimeout = (options.hjOnlyTimeout !== undefined) ? options.hjOnlyTimeout : 4500;
        options.nonInterruptingState = this.dispatchDialog;
        options.handleGlobalParseState = this.handleGlobalParse;
        options.handleLaunchParseState = this.handleLaunchParse;

        this.parseAgainstRules = new ParseGlobalState(this,
            'Parse Against All Rules (Find Winner)',
            options);

        this.handleLaunchParse.addInternalTransition('', this.interrupt2);
        this.handleLaunchParse.onEntry = (trans, result) => {
            // separate out results we'll be using
            const listenResults = result as ListenResults;
            const launchParse = listenResults.result.launchParse;
            GlobalManagerService.instance.handleSkillLaunch(launchParse);
            this.handleLaunchParse.transitionTo(this.interrupt2, launchParse);
        };

        this.handleGlobalParse.addInternalTransition('Interrupting Launch', this.handleLaunchParse);
        this.handleGlobalParse.addInternalTransition('Interrupting Unknown', this.interrupt2);
        this.handleGlobalParse.addInternalTransition('Non-Interrupting', this.dispatchDialog);
        this.handleGlobalParse.onEntry = (trans, result) => {
            let listenResults = result as ListenResults;
            let intent:string = listenResults.result.NLParse.intent;
            //special case volume because it has a few intents that all start with 'volume'
            if (intent.match(/^volume/)) {
                intent = 'volume';
            }
            // Jibo module has said it can handle global event
            if(GlobalManagerService.instance.canHandleGlobal(GlobalCommand[intent])) {
                log.info("letting skill handle global", intent);
                // don't interrupt
                GlobalManagerService.instance.emitGlobal(GlobalCommand[intent], listenResults);
                this.handleGlobalParse.transitionTo(this.dispatchDialog, listenResults);
            }
            else {
                log.info("default global behavior for ", intent);
                switch(GlobalCommand[intent]) {
                    // noone in jibo can handle stop, handle launch with @be/idle
                    case 'STOP':
                        listenResults.result.NLParse.skill = '@be/idle';
                        listenResults.result.launchParse = new ParseResults(listenResults.result.Input, listenResults.result.NLParse);
                        this.handleGlobalParse.transitionTo(this.handleLaunchParse, listenResults);
                        break;
                    case 'HELP':
                        listenResults.result.NLParse.skill = '@be/friendly-tips';
                        listenResults.result.launchParse = new ParseResults(listenResults.result.Input, listenResults.result.NLParse);
                        this.handleGlobalParse.transitionTo(this.handleLaunchParse, listenResults);
                        break;
                    case 'SLEEP':
                        listenResults.result.NLParse.skill = '@be/idle';
                        listenResults.result.launchParse = new ParseResults(listenResults.result.Input, listenResults.result.NLParse);
                        this.handleGlobalParse.transitionTo(this.handleLaunchParse, listenResults);
                        break;
                    case 'VOLUME':
                        console.warn("not yet setting volume in SSM");
                        // absolutely interrupt listens, the MIM will recover after the
                        // nonInterruptingGlobal event.
                        this.handleGlobalParse.transitionTo(this.interrupt2);
                        //this.handleGlobalParse.transitionTo(this.dispatchDialog, listenResults);
                        // inform anything listening in the skill that we aren't interrupting state
                        // and it is okay to continue
                        GlobalListen.getInstance().events.skillManager.nonInterruptingGlobal.emit();
                        break;
                    case 'PAUSE':
                        listenResults.result.NLParse.skill = '@be/idle';
                        listenResults.result.launchParse = new ParseResults(listenResults.result.Input, listenResults.result.NLParse);
                        this.handleGlobalParse.transitionTo(this.handleLaunchParse, listenResults);
                        break;
                    case 'HOLDON':
                        listenResults.result.NLParse.skill = '@be/idle';
                        listenResults.result.launchParse = new ParseResults(listenResults.result.Input, listenResults.result.NLParse);
                        this.handleGlobalParse.transitionTo(this.handleLaunchParse, listenResults);
                        break;
                    case 'WHATCANIDO':
                        listenResults.result.NLParse.skill = '@be/friendly-tips';
                        listenResults.result.launchParse = new ParseResults(listenResults.result.Input, listenResults.result.NLParse);
                        this.handleGlobalParse.transitionTo(this.handleLaunchParse, listenResults);
                        break;
                    default:
                        this.handleGlobalParse.transitionTo(this.interrupt2);
                        break;
                }
            }
        };

        // dispatch parsed dialog to appropriate listeners
        this.dispatchDialog.addInternalTransition('Finished', this.processQueue);
        this.dispatchDialog.onEntry = (trans, result) => {
            const type = result as ListenerType;
            // still want to send dialog for individual listeners
            gl.emitResults(type, () => {
                this.dispatchDialog.transitionTo(this.processQueue);
            });
        };

        // This is the HJ listening state
        this.hjList.addEventTransition(SMEvents.AddNonHJList, this.startNHJList);
        this.hjList.addEventTransition(SMEvents.Suspend, this.suspended);
        this.hjList.addEventTransition(SMEvents.HJHeard, this.waitIncr);
        this.hjList.onEntry = () => {
            gl._clearCached();
            gl._startHJListening();

            // UNCOMMENT to debug and see state trace.
            // let trString = this.getTrace().map(t => 'trans: ' + t.name+ '\tdest: ' + t.getDestinationState().name).join('\n');
            // console.log('TRACE\n-----\n'+trString);
            gl.events.listen.startHjListen.emit();
        };

        // This is the suspended state
        this.suspended.addEventTransition(SMEvents.UnSuspend, this.hjList);
        this.suspended.onEntry = () => {
            gl.events.internal.enteringSuspend.emit();
        };

        // This is the NonHJ listening state
        this.startNHJList.addEventTransition(SMEvents.ListenFinished, this.interrupt1);
        this.startNHJList.addEventTransition(SMEvents.RemLastNonHJList, this.hjList);
        this.startNHJList.addEventTransition(SMEvents.Suspend, this.suspended);
        this.startNHJList.addEventTransition(SMEvents.ListenCloud, this.wait2);
        this.startNHJList.onEntry = () => {
            gl._clearCached();
            gl._startNHJListening(() => {
                gl.events.listen.startNonHjListen.emit();
            });
        };

        this.startNHJList.onExit = (trans) => {
            if (trans.getDestinationState() === this.hjList) {
                gl.events.listen.listenFinished.emit();
            }
        };

        this.wait2.addEventTransition(SMEvents.ListenFinished, this.HJOrNoHJ);

        // Here we determine if it is a HJ or non HJ response
        this.HJOrNoHJ.addInternalTransition('HJ or NHJ', this.parseAgainstRules);
        this.HJOrNoHJ.onEntry = () => {
            let listenResults = gl._lastCloudListenResults;
            if (listenResults.result.Input.toLowerCase().search('hey jibo') !== -1) {
                // Notify all hj listeners of the event
                gl._activeHJListeners.forEach(l => l.events.hjHeard.emit());
                this.HJOrNoHJ.transitionTo(this.parseAgainstRules, ParseLaunch.HJ_HEARD);
            }
            // need to both parse the global state AND will automatically transition to parseDialog after.
            else if (this._shouldForceGlobal()) {
                this.HJOrNoHJ.transitionTo(this.parseAgainstRules, ParseLaunch.FORCE_GLOBAL);
            }
            else {
                this.HJOrNoHJ.transitionTo(this.parseAgainstRules, ParseLaunch.DO_NOT_PARSE_LAUNCH);
            }
        };

        // Create global parse states
        this.parseAgainstRules.create(gl);

        this.interrupt1.create(gl);
        this.interrupt2.create(gl);

        // This state processes the Add Listener queue
        this.processQueue.addInternalTransition('No NonHJ Listeners', this.wait1);
        this.processQueue.addInternalTransition('Some NonHJ Listeners', this.startNHJList);
        this.processQueue.onEntry = () => {
            gl._queuedNonHJListeners.forEach(listener => gl._activeNonHJListeners.add(listener));
            gl._queuedNonHJListeners.clear();
            if (gl._activeNonHJListeners.size > 0) {
                this.processQueue.transitionTo(this.startNHJList);
            }
            else {
                this.processQueue.transitionTo(this.wait1);
            }
        };

        this.wait1.addTransition(new TimeoutTransition('200ms', this.hjList, 200));
        this.wait1.addEventTransition(SMEvents.AddNonHJList, this.startNHJList);

        // "Hey Jibo" side
        // waitIncremental waits for incremental results after a HJ is heard
        this.waitIncr.addEventTransition(SMEvents.Suspend, this.suspended);
        this.waitIncr.addEventTransition(SMEvents.ListenCloud, this.waitListenFin);
        this.waitIncr.addEventTransition(SMEvents.ListenFinished, this.emitHJO);
        this.waitIncr.addTypedEventTransition(gl.events.listen.incremental, this.waitListenFin);

        this.waitIncr.addTransition(new TimeoutTransition(`${options.hjOnlyTimeout} ms`, this.emitHJO, options.hjOnlyTimeout));
        let incrementalHandler = (result: ParseResults) => {
            gl._lastIncrementalParseResults = result;
        };
        this.waitIncr.onEntry = () => {
            gl._lastCloudListenResults = undefined;
            gl.events.listen.incremental.on(incrementalHandler);
        };
        this.waitIncr.onExit = () => {
            gl.events.listen.incremental.removeListener(incrementalHandler);
        };

        this.waitListenFin.addEventTransition(SMEvents.Suspend, this.suspended);
        this.waitListenFin.addEventTransition(SMEvents.ListenFinished, this.checkHJO);

        this.checkHJO.addInternalTransition('>HJ', this.parseAgainstRules);
        this.checkHJO.addInternalTransition('HJ only', this.emitHJO);
        this.checkHJO.onEntry = () => {
            if (!this._textIsHJO(gl._lastCloudListenResults.result.Input)) {
                this.checkHJO.transitionTo(this.parseAgainstRules, ParseLaunch.HJ_HEARD);
            } else {
                this.checkHJO.transitionTo(this.emitHJO);
            }
        };

        this.emitHJO.addInternalTransition('', this.processQueue);
        this.emitHJO.onEntry = () => {
            gl.handleHJO(new ListenResults(null));
            this.emitHJO.transitionTo(this.processQueue);
        };

        // Now we print the state machine
        // this.toDotFile('/var/jibo/test.dot');
    }

    /**
     * Check whether any NonHJListeners ask to force a global parse.
     * @return {boolean}
     */
    _shouldForceGlobal() {
        let found = false;
        this.gl._activeNonHJListeners.forEach((listener) => {
            found = listener.options.forceGlobal || found;
        });
        return found;
    }

    /**
     * checkIncrementalHJO checks whether there's anything other than "Hey Jibo" in the incremental results
     * checkHJO does the same on the final results
     * @param {String} input
     * @return {boolean}
     */
    _textIsHJO(input: String) {
        let strippedInput = input.replace(/(hey)|(jibo)/ig, '').trim(); // remove "hey jibo" from input
        // see if there's anything left
        return (strippedInput.length === 0);
    }
}
