import Router = require("router");
import Parser from "./Parser";
import {JiboServerRequest, JiboServerResponse, ServiceOptions, HTTPWSService} from 'jibo-service-framework';
import {createLog} from "../../utils/Log";
import {NLUMessages} from "jibo-common-types";
let log = createLog("ssm-nlu-service");
import WebSocket = require("ws-without-native");

let handleNum:number = 0;

// TODO: Ask JR how/why this works.
class SingletonEnforcer{}

/*
 * @type ErrorMessage
 * @description Type of messages from NLU Service when Status is ERROR.
 * @member exception {String} type of exception sent by NLU Service
 * @member info {any} Object containing extra relevant information about the error.
 */
type ErrorMessage = {
    exception: string,
    info: any
};

/*
 * @type NLUWSMessage
 * @description Type of messages NLU Service sends through web sockets.
 * @member Event {NLUMessages} Event that NLU Websocket is announcing.
 */
type NLUWSMessage = {
    Event: NLUMessages
};

/*
 * @type Stats
 * @description Statistics returned for some operations of NLU Service.
 * @member COMP_TIME {Number} Time taken to compile rule.
 * @member PARSE_TIME {Number} Time taken to parse text from rule.
 * @member REMOVE_TIME {Number} Time taken to remove rule from memory.
 * @member SAVE_TIME {Number} Time taken to save rule.
 */
type Stats = {
    COMP_TIME?: number,
    PARSE_TIME?: number,
    REMOVE_TIME?: number
    SAVE_TIME?: number
}

/*
 * @type NLUResponse
 * @description Format of responses from NLU Service
 * @member exception {String} type of exception sent by NLU Service
 * @member info {any} Object containing extra relevant information about the error.
 */
type NLUResponse = {
    Status:REQ_STATUS;
    URI?:string;
    Result?:string;
    Message?:string | ErrorMessage | NLUMessages;
    Stats?:Stats;
}

/*
 * @type NLUReqContent
 * @description Content of the NLU Requests
 * @member [RULE_STRING] {String} Content of rule if request requires it.
 * @member [URI] {String} URI if request requires it.
 * @member [RULE_FSTPATH] {String} Path to compiled rule fst file if request requires it.
 * @member [TXT_STRING] {String} Text string to parse if request requires it.
 * @member [URIS] {Array<String>} URIs if request takes multiple.
 */
type NLUReqContent = {
    RULE_STRING?:string;
    URI?:string,
    RULE_FSTPATH?:string,
    TXT_STRING?:string,
    URIS?: string[]
};

/*
 * @type NLURequest
 * @description Format of requests to NLU Service
 * @member REQ_TYPE {String} type of request being sent to NLU
 * @member REQ_CONTENT {any} Object containing extra relevant information about the error.
 */
interface NLUResuest {
    REQ_TYPE:REQ_TYPES;
    REQ_CONTENT: {
        RULE_STRING:string;
        URI:string;
        RULE_FSTPATH:string;
        TXT_STRING:string;
        URIS: string[];
        RULE_BINARYFST: string;
        BINARYFST_PATH: string;
    };
}

/**
 * Enum of request statuses returned from NLU.
 * @type {Enum}
 * @property OK {String} Request status is ok.
 * @property ERROR {String}  Request has error response.
 * @readOnly
 */
export enum REQ_STATUS {
    OK = <any>'OK',
    ERROR = <any>'ERROR'
};

/*
 * The different possible requests to NLU Service
 * @enum REQ_TYPES
 * @type {Enum}
 * @property COMPILE {string} Request to compile text.
 * @property PARSE_FROM_URI {string} Request to parse text from uri.
 * @property PARSE_FROM_TEXT {string} Request to parse text from rule text.
 * @property PARSE_FROM_FILE {string} Request to parse text from fst file.
 * @property UNION {string} Request to unionize uris.
 * @property REMOVE_FROM_MEM {string} Request to remove from memory.
 * @property RESET_MEMORY {string} Request to reset nlu memory.
 * @property SAVE_FST_IN_DISK {string} Request to save fst in disk.
 */
enum REQ_TYPES {
    COMPILE = <any> 'COMPILE',
    PARSE_FROM_URI = <any> 'PARSE_FROM_URI',
    PARSE_FROM_TEXT = <any> 'PARSE_FROM_TEXT',
    PARSE_FROM_FILE = <any> 'PARSE_FROM_FILE',
    UNION = <any> 'UNION',
    REMOVE_FROM_MEM = <any> 'REMOVE_FROM_MEM',
    RESET_MEMORY = <any> 'RESET_MEMORY',
    SAVE_FST_IN_DISK = <any> 'SAVE_FST_IN_DISK'
}

/**
 * @description
 * NLU Service Simulator. Acts as NLU Service would with respect to requests,
 * responses, and error handling.
 * @extends HTTPWSService
 * @module skills-service-manager/services/nlu-service/NLUService
 */
class NLUService extends HTTPWSService {
    /**
     * NLU Service instance being used.
     * @name NLUService#_instance
     * @type {NLUService}
     * @private
     */
    private static _instance:NLUService;
    /**
     * Parser instance being used
     * @name NLUService#parser
     * @type {Parser}
     * @private
     */
    private parser:Parser;
    /**
     * Handles to rules we have compiled and cached.
     * @name NLUService#handles
     * @type {Map<string[]:any}
     * @private
     */
    private handles:{[id:string]:any} = {};
    /**
     * Websocket being used
     * @name NLUService#socket
     * @type {WebSocket}
     * @private
     */
    private socket:WebSocket;

    public static createInstance(options:ServiceOptions, rootDir:string):NLUService {
        return new NLUService(new SingletonEnforcer(), options, rootDir);
    }

    public static get instance():NLUService {
        return NLUService._instance;
    }

    constructor(enforcer:SingletonEnforcer, options:ServiceOptions, rootDir:string) {
        super('nlu', options, rootDir);
        NLUService._instance = this;
        this.parseMessage = this.parseMessage.bind(this);
        this.parser = new Parser();

        log.info("Initialized");
    }

    public init(callback: (err?:Error)=>void) {
        super.init((err:Error) => {
            callback(err);
        });
    }

    public routes(url:Router) {
        super.routes(url);
        url.post('/nlu_interface', this.parseMessage);
    }

    public onConnection(client: WebSocket): void {
        super.onConnection(client);
        if (client.upgradeReq.url === '/reset_memory') {
            this.socket = client;
        }
    }

    public onMessage(command: any, client: WebSocket): void {
        return;
    }

    public onClose(client: WebSocket): void {
        this.socket = null;
    }

    /**
     * Parse and redirect incoming messages to NLU Service.
     * @param req {JiboServerRequest} the request data to be processed.
     * @param res {JiboServerResponse} the response to send through WS.
     * @private
     */
    private parseMessage(req:JiboServerRequest, res:JiboServerResponse):void {
        let body = "";
        req.on('data', (chunk) => {
            body += chunk;
        });
        req.on('end', () => {
            let data:NLUResuest;
            try {
                data = JSON.parse(body);
            }
            catch(e) {
                this.sendJson(res, {
                    Status: REQ_STATUS.ERROR,
                    Message: 'Inavlid request. Request body is not valid JSON'
                }, 200);
                return;
            }
            if(data.REQ_TYPE === REQ_TYPES.COMPILE) {
                this.compile(
                    data.REQ_CONTENT.RULE_STRING,
                    data.REQ_CONTENT.BINARYFST_PATH,
                    data.REQ_CONTENT.URI,
                    res
                );
            }
            else if(data.REQ_TYPE === REQ_TYPES.PARSE_FROM_URI) {
                this.parseFromUri(
                    data.REQ_CONTENT.URI,
                    data.REQ_CONTENT.TXT_STRING,
                    res
                );
            }
            else if(data.REQ_TYPE === REQ_TYPES.PARSE_FROM_TEXT) {
                this.parseFromText(
                    data.REQ_CONTENT.RULE_STRING,
                    data.REQ_CONTENT.TXT_STRING,
                    res
                );
            }
            else if(data.REQ_TYPE === REQ_TYPES.PARSE_FROM_FILE) {
                this.parseFromFile(
                    data.REQ_CONTENT.URI,
                    data.REQ_CONTENT.TXT_STRING,
                    res
                );
            }
            else if(data.REQ_TYPE === REQ_TYPES.UNION) {
                this.union(
                    data.REQ_CONTENT.URIS,
                    data.REQ_CONTENT.URI,
                    res
                );
            }
            else if(data.REQ_TYPE === REQ_TYPES.REMOVE_FROM_MEM) {
                this.removeFromMemory(
                    data.REQ_CONTENT.URI,
                    res
                );
            }
            else if(data.REQ_TYPE === REQ_TYPES.RESET_MEMORY) {
                this.resetMemory(
                    res
                );
            }
            else if(data.REQ_TYPE === REQ_TYPES.SAVE_FST_IN_DISK) {
                this.saveFstOnDisk(
                    data.REQ_CONTENT.URI,
                    data.REQ_CONTENT.BINARYFST_PATH,
                    res
                );
            }
        });
    }

    /**
     * Parse text using our internal parser and send result as response.
     * @param fst {any} Compiled rule to parse against.
     * @param text {string} Text string to be parsed
     * @private
     */
    private _parseText(fst, text) {
        let parser = this.parser.nlu.build_sentence_parser(fst);
        let parsed = parser.parse_sentence(text);
        return JSON.parse(parsed);
    }

    /**
     * Parse text from a parseFromUri request.
     * @param uri {string} Compiled rule uri to parse against.
     * @param text {string} Text string to be parsed.
     * @param res {JiboServerResponse} the response to send as NLU response.
     * @private
     */
    private parseFromUri(uri:string, text:string, res:JiboServerResponse) {
        let data:NLUResponse = {
            Status: REQ_STATUS.OK,
            URI: ''
        };
        let fst = this.handles[uri];
        if(fst && this.parser.nlu) {
            data.Result = this._parseText(fst, text);
        }
        else {
            data.Status = REQ_STATUS.ERROR;
            data.Message = `No handle named '${uri}' exists`;
        }
        this.sendJson(res, data, 200);
    }

    /**
     * Parse text from a parseFromRule request.
     * @param rule {string} Text of rule string to compile and parse against.
     * @param text {string} Text string to be parsed.
     * @param res {JiboServerResponse} the response to send as NLU response.
     * @private
     */
    private parseFromText(rule:string, text:string, res:JiboServerResponse) {
        let data:NLUResponse = {
            Status: REQ_STATUS.OK
        };
        try {
            let fst = this.parser.nlu.compile_fst_from_text(rule, `handle:${handleNum++}`);
            data.Result = this._parseText(fst, text);
        }
        catch(e) {
            data.Status = REQ_STATUS.ERROR;
            data.Message = e.message;
        }

        this.sendJson(res, data, 200);

    }

    /**
     * Parse text from a parseFromFile request.
     * @param filePath {string} Path to fst file to parse against.
     * @param text {string} Text string to be parsed.
     * @param res {JiboServerResponse} the response to send as NLU response.
     * @private
     */
    private parseFromFile(filePath:string, text:string, response:JiboServerResponse) {
        let data:NLUResponse = {
            Status: REQ_STATUS.OK
        };
        try  {
            let fst = this.parser.nlu.read_fst_from_uri('file://' + filePath);
            data.Result = this._parseText(fst, text);
        }
        catch(e) {
            data.Status = REQ_STATUS.ERROR;
            data.Message = e.message;
        }

        this.sendJson(response, data, 200);
    }

    /**
     * Compile a rule and store in the parser
     * @param ruleString {string} Text of rule to compile and save.
     * @param fstPath {string} Path to fst file to compile and save.
     * @param uri {string} URI to store as handle to compiled rule.
     * @param res {JiboServerResponse} the response to send as NLU response.
     * @private
     */
    private compile(ruleString:string, fstPath:string, uri:string, res:JiboServerResponse) {
        let data:NLUResponse = {
            Status: REQ_STATUS.OK,
            URI: ''
        };
        let handle = `handle:${handleNum++}`;
        if(uri) {
            handle = uri;
            if (!handle.startsWith('handle:')) {
                handle = 'handle:' + handle;
            }
        }
        if(fstPath) {
            this.handles[handle] = this.parser.nlu.load_fst_from_fst_file(fstPath, handle);
            data.URI = handle;
        }
        else {
            try {
                this.handles[handle] = this.parser.nlu.compile_fst_from_text(ruleString, handle);
                data.URI = handle;
            }
            catch(e) {
                data.Status = REQ_STATUS.ERROR;
                data.Message = e.message;
            }
        }

        this.sendJson(res, data, 200);
    }

    /**
     * Unionize a series of rules.
     * @param rules {Array<string>} Rule uris to unionize.
     * @param uri {string} URI to store as handle to compiled rule.
     * @param res {JiboServerResponse} the response to send as NLU response.
     * @private
     */
    private union(rules:Array<string>, uri:string, res:JiboServerResponse) {
        let data: NLUResponse = {
            Status: REQ_STATUS.OK,
            URI: ''
        };
        let handle = `handle:${handleNum++}`;
        if(uri) {
            handle = uri;
            if (!handle.startsWith('handle:')) {
                handle = 'handle:' + handle;
            }
        }
        try {
            this.handles[handle] = this.parser.nlu.union_fst(rules, handle);
            data.URI = handle;
        }
        catch(e) {
            data.Status = REQ_STATUS.ERROR;
            data.Message = e.message;
        }

        this.sendJson(res, data, 200);
    }

    /**
     * Remove a rule from parser memory.
     * @param uri {string} URI to remove from compiled rules.
     * @param res {JiboServerResponse} the response to send as NLU response.
     * @private
     */
    private removeFromMemory(uri:string, res:JiboServerResponse) {
        let data:NLUResponse = {
            Status: REQ_STATUS.OK
        };
        try {
            this.handles[uri] = null;
            this.parser.nlu.remove_from_memory(uri);
        }
        catch(e) {
            data.Status = REQ_STATUS.ERROR;
            data.Message = e.message;
        }
        this.sendJson(res, data, 200);
    }

    private saveFstOnDisk(uri:string, filePath:string, res:JiboServerResponse) {
        let data:NLUResponse = {
            Status: REQ_STATUS.OK,
            Stats: {
                "SAVE_TIME": 0
            },
            Message: "OK"
        };
        if(!uri) {
            const error:ErrorMessage = {
                exception: "Bad request",
                info: {
                    "msg": "Must provide rule uri and filePath to save fst on disk."
                }
            };
            data.Message = error;
        } else {
            if (!uri.startsWith('handle:')) {
                uri = 'handle:' + uri;
            }
            let fst = this.parser.nlu.read_fst_from_uri(uri);
            fst.save_fst(filePath);
        }
        this.sendJson(res, data, 200);
    }

    private resetMemory(res:JiboServerResponse) {
        let data:NLUResponse = {
            Status: REQ_STATUS.OK,
            Stats: {
                "COMP_TIME": 0,
                "REMOVE_TIME": 0
            },
            Message: "OK"
        };
        this.sendJson(res, data, 200);

        if (this.socket) {
            const wsBody:NLUWSMessage = {
                Event: NLUMessages.RESET_MEMORY
            };
            this.sendWsJson(this.socket, wsBody);
        }
    }
}


export default NLUService;
