import { ListenOptions, ListenResults } from 'jibo-common-types';
import { DialogListenerEvents } from './TypedEvents';

export interface DialogListenerOptions {
    hotphrase: boolean;
    incremental?: boolean;
    parseIncremental?: boolean;
    forceGlobal?: boolean;
}

export default class DialogListener {
    public events = new DialogListenerEvents();
    /**
     * Listening and Parse results of the ASR input with the listener rule.
     * @name listenResults
     * @type {ListenResults}
     */
    public listenResults: ListenResults;

    /**
     * @param {String} nluRulePath NLU rule path
     * @param {Object} Options ListenOptions
     * @param {Boolean} [Options.incremental] Listen for incremental results.
     * @param {Boolean} [Options.parseIncremental] Parse incremental results.
     * @param {String} [Options.hotphrase] Listen for "hey jibo".
     * @param {Boolean} [Options.speech_to_text] Listen for cloud results.
     * @param {String} [Options.language] Language for ASR.
     * @param {Boolean} [Options.forceGlobal] Force Non-Hey Jibo listens to parse global and launch rules.
     * @param {String} [id] Specify listener ID.
     */
    constructor(public ruleUri: string, public options: ListenOptions, public id?: string) {
        this.options = Object.assign({
            hotphrase: '',
            parseIncremental: false,
            incremental: false,
            speech_to_text: true,
            language: 'en-US',
            forceGlobal: false,
            metadata: ""
        }, options);
        this.listenResults = null;
    }
}
