import async = require('async');
import RegistryService from "./services/registry-service/RegistryService";
import KBService from "./services/kb-service/KBService";
import SkillsService from "./services/skills-service/SkillsService";
import SkillsServiceSim from "./services/skills-service/SkillsServiceSim";
import PerformanceService from "./services/performance-service/PerformanceService";
import ServiceManager from "./services/service-manager/ServiceManager";
import {RegistryClient, ServiceOptions, RegistrationRecord} from "jibo-service-framework";
import TTSService from "./services/tts-service/TTSService";
import LPSService from "./services/lps-service/LPSService";
import NotificationsService from "./services/notifications-service/NotificationsService";
import ASRService from "./services/asr-service/ASRService";
import GlobalManagerService from "./services/global-service/GlobalManagerService";
import BodyService from "./services/body-service/BodyService";
import ListenService from "./services/listen-service/ListenService";
import NLUService from "./services/nlu-service/NLUService";
import SystemManagerService from "./services/system-manager/SystemManagerService";
import MediaService from "./services/media-service/MediaService";
import MediaManagerService from "./services/media-manager-service/MediaManagerService";
import ServerService from "./services/server-service/ServerService";
import SystemMonitoringServiceSim from "./services/system-monitoring-service/SystemMonitoringServiceSim";
import ErrorService from "./services/error-service/ErrorService";
import DevShell from "./services/dev-shell/DevShell";
import WifiService from "./services/wifi-service/WifiService";
import SchedulerService from "./services/scheduler-service/SchedulerService";
import ClientInitializer from "./ClientInitializer";
import Orchestrator = require('orchestrator');
import jibo = require('jibo');
import {versionCheck} from './utils/Version';
import ScreenScheduler from './background/screen/ScreenScheduler';
import BackgroundUtilsManager from './utils/BackgroundUtilsManager';
//import all background things so they are registered with BackgroundUtilsManager
import './background';


const findRoot = require('find-root');
const path = require('path');
const spawnSync = require('child_process').spawnSync;


interface Service {
    port:number;
}

interface Client {
    port:number;
    host:string;
}

export interface Configuration {
    RegistryClient?:Client;
    RegistryService?:Service;
    services:any;
    platformVersion?:string;
}

declare type Callback = (err?:Error) => void;

declare type InitFunction = (callback:Callback) => void;
/* To add a simulated service: import the class in `index.ts` and add
 * it to the export default, import it above, and add it to the
 * `services` and `simulatedServices` objects below.
 * To enable in the simulator, also add it to
 * `jibo-cli/src/simulator/client/index.tsx`.
 * To enable in `jibo-integration-tests` add it to `tests/index.js`.
 * Note: many services are disabled in `unit-test` mode.
 */
class Factory {

    private orchestrator:Orchestrator;

    private records:Array<RegistrationRecord>;

    constructor(public conf:Configuration, public rootDir:string, mode?:string) {

        //first create all the service instances, but don't init them
        let services = {
            KBService, SkillsService, SkillsServiceSim, ServiceManager, NLUService,
            TTSService, LPSService, NotificationsService, ASRService, BodyService,
            ListenService, DevShell, PerformanceService, MediaService,
            MediaManagerService, ServerService, SystemManagerService,
            WifiService, ErrorService, SchedulerService, SystemMonitoringServiceSim,
            GlobalManagerService
        };

        Object.keys(this.conf.services).forEach((serviceName:string) => {
            let options:ServiceOptions = this.conf.services[serviceName];
            services[serviceName].createInstance(options, this.rootDir);
        });

        //create initialization dependencies
        this.orchestrator = new Orchestrator();

        this.orchestrator.add('registry-service', (done:Callback) => {
            if(this.conf.RegistryService) {
                let options:ServiceOptions = this.conf.RegistryService;
                RegistryService.createInstance(options, this.rootDir);
                RegistryService.instance.init(done);
            }
            else {
                done();
            }
        });

        //init the registry client and ger
        this.orchestrator.add('registry-client', ['registry-service'], (done:Callback) => {
            //now create the registry client
            let host:string = this.registryHost;
            let port:number;
            if(this.conf.RegistryService) {
                port = RegistryService.instance.port;
            }
            else if(this.conf.RegistryClient) {
                port = this.conf.RegistryClient.port;
            }
            else {
                return done(new Error('Config must specify either RegistryClient or Registry Service'));
            }
            RegistryClient.createInstance(host, port);
            done();
        });

        let simulatedServices = {
            ASRService,
            TTSService,
            BodyService,
            LPSService,
            NLUService,
            MediaService,
            ServerService,
            SystemMonitoringServiceSim,
            SystemManagerService
        };

        Object.keys(simulatedServices).forEach((serviceName) => {
            this.orchestrator.add(serviceName, ['registry-client'], (done:Callback) => {
                if(this.conf.services[serviceName]) {
                    let options:ServiceOptions = this.conf.services[serviceName];
                    let instance = simulatedServices[serviceName].createInstance(options, this.rootDir);
                    instance.init(done);
                }
                else {
                    done();
                }
            });
        });

        //get all records
        this.orchestrator.add('get-records', Object.keys(simulatedServices), (done:Callback)=> {
            RegistryClient.instance.getRecords((err:Error, records:Array<RegistrationRecord>) => {
                if(err) {
                    return done(err);
                }
                this.records = records;
                done();
            });
        });

        // Initializes system-manager and checks that the current SSM version works with the robot version;
        // if no platform version specified, doesn't bother checking and keeps going.
        this.orchestrator.add('system-manager', ['get-records'], (done:Callback) => {
            // //if we're simulated
            // if(this.conf.services.ASRService) {
            //     return done();
            // }

            let sysMgrRec = undefined;
            let size = this.records.length;
            for(let i=0; i < size; i++) {
                if (this.records[i].name === 'system-manager') {
                    sysMgrRec = this.records[i];
                    break;
                }
            }

            if (!sysMgrRec) {
                return done(new Error('Could not find system-manager in registry records.'));
            }

            jibo.systemManager.init({
                host: RegistryClient.instance.host,
                port: sysMgrRec.port
            }, (error) => {
                if (error) {
                    done(error);
                }
                else {
                    versionCheck(this.conf.platformVersion, done);
                }
            });
        });

        this.orchestrator.add('clients', ['system-manager'], (done:Callback) => {
            let tasks:Array<(done:Callback) => void> = [];
            this.records.forEach((record:RegistrationRecord) => {
                if(ClientInitializer.mapping[record.name]) {
                    tasks.push(ClientInitializer.mapping[record.name](record));
                }
            });
            async.parallel(tasks, done);
        });

        let addService = (name:string, deps:string[], Service:any) => {
            console.log('adding', name);
            this.orchestrator.add(name, deps, (done:Callback) => {
                if(Service.instance) {
                    Service.instance.init((err?:Error) => {
                        // Will leave here in case people want to run
                        // with debug mode -- CANNOT log obj to console.
                        // Must use JSON.stringify(Service.instance)
                        // console.log(name, Service.instance);
                        done(err);
                    });
                }
                else {
                    // console.log(name, Service.instance);
                    done();
                }
            });
        };

        addService('wifi-service',              ['clients'], WifiService);
        addService('dev-shell',                 ['clients'], DevShell);
        addService('performance-service',       ['clients'], PerformanceService);
        addService('kb',                        ['clients'], KBService);
        addService('notifications-service',     ['clients'], NotificationsService);
        addService('scheduler-service',         ['clients'], SchedulerService);
        addService('global-service',            ['clients'], GlobalManagerService);
        addService('error-service',             ['clients', 'kb'], ErrorService);
        addService('listen-service',            ['clients', 'kb'], ListenService);
        addService('media-manager',             ['clients'], MediaManagerService);
        addService('skills-service',            ['listen-service'], SkillsService);
        addService('skills-service-sim',        ['listen-service'], SkillsServiceSim);

        // NOTE: orchestrator does not run tasks that don't have
        // anything depending on them so make sure you add your
        // service to this dependencies list
        this.orchestrator.add('end', ['wifi-service', 'dev-shell', 'performance-service', 'global-service', 'kb', 'notifications-service', 'scheduler-service', 'media-manager', 'error-service', 'listen-service', 'skills-service', 'skills-service-sim'], (done) => {
            //if we're in developer mode
            if(mode && mode.indexOf('developer') >= 0) {
                ScreenScheduler.start();
            }

            //now the all services exist, initialize all background utilities
            BackgroundUtilsManager.initAll(mode);

            done();
        });

    }

    private get registryHost():string {
        let host:string = '127.0.0.1';

        if( this.conf.RegistryClient ) {
            // If a registry host was provided
            if(this.conf.RegistryClient.host){
                host = this.conf.RegistryClient.host;
            }
            // Fetch the command line's default robot if no registry host was provided
            else {
                const getHostNameScriptPath = path.join(findRoot(__dirname), 'bin/utils/get-robot-host.sh');
                host = spawnSync(getHostNameScriptPath).stdout.toString().trim();
                console.log(host);
            }
        }
        return host;
    }

    public init(callback:Callback):void {
        console.log('INIT');
        this.orchestrator.start('end', callback);
    }
}

export default Factory;
