import * as uuid from "uuid";
import {SpeakerId} from 'jibo-common-types';


export enum ResponseStatus {
    NORMAL = <any> "normal",
    ERROR = <any> "error",
    RECEIVED = <any> "received"
};

export enum EventType {
    HOTPHRASE = <any> "hotphrase",
    END_OF_SPEECH = <any> "end_of_speech",
    START_OF_SPEECH = <any> "start_of_speech",
    INCREMENTAL = <any> "speech_to_text_incremental",
    SPEECH_TO_TEXT_FINAL = <any> "speech_to_text_final",
    SPEAKER_ID = <any> "speaker_id",
    RECEIVED = <any> "received",
    ACKNOWLEDGEMENT = <any> "acknowledgement",
    // Have error as event type as well for parity of asr service
    ERROR = <any> "error"
}

export interface ASRResponseOptions {
    task_id?: string;
    status?: ResponseStatus;
    message?: string;
    event_type?: EventType;
    speaker_id?: SpeakerId;
    timestamp?: number;
    utterances?: { utterance: string, score: number }[];
    message_id?: string;
    request_id?: string;
    id?:string;
}

/**
 * @description
 * ASRResponse. The structure of responses that come from the ASR Service.
 * @module skills-service-manager/services/asr-service/ASRResponse
 */
class ASRResponse implements ASRResponseOptions {

    public task_id: string;
    public status: ResponseStatus;
    public message: string;
    public event_type: EventType;
    public speaker_id: SpeakerId;
    public timestamp: number;
    public utterances: { utterance: string, score: number }[];
    public message_id: string;
    public request_id: string;

    constructor(options?: ASRResponseOptions) {
        options = Object.assign(this, {
            task_id: '',
            status: ResponseStatus.NORMAL,
            message: '',
            event_type: EventType.ERROR,
            speaker_id: new SpeakerId(),
            timestamp: 0,
            utterances: [{ utterance: "", score: 0 }],
            message_id: "simulated-" + uuid.v4(),
            request_id: ""
        }, options || {});
    }
}

export default ASRResponse;