import {
    ServiceOptions, HTTPWSService,
    JiboServerRequest, JiboServerResponse
} from 'jibo-service-framework';
import Router = require('router');
// import fs = require('fs');
// import async = require('async');
import path = require('path');
import WebSocket = require('ws-without-native');
import {ipcRenderer} from 'electron';
import {RuleManager} from "../listen-service/RuleManager";
import GlobalListen from "../listen-service/GlobalListen";
import GlobalManagerService from "../global-service/GlobalManagerService";
import PerformanceService from "../performance-service/PerformanceService";
import findRoot = require('find-root');
import async = require('async');
import {createLog} from "../../utils/Log";
import SystemManagerClient from "../../clients/SystemManagerClient";
import {SkillRecord} from "../../clients/SystemManagerClient";
import DevToolsClient from "../../clients/DevToolsClient";
import ScreenScheduler from "../../background/screen/ScreenScheduler";
let log = createLog("ssm-skills-service");

interface SkillsServiceOptions extends ServiceOptions {
    singleSkill:boolean;
    startSkill?:string;
}

class SingletonEnforcer {
}

class SkillsService extends HTTPWSService {

    private static _instance:SkillsService;

    public currentSkill:SkillRecord;

    public static createInstance(options:SkillsServiceOptions, rootDir:string):SkillsService {
        return new SkillsService(new SingletonEnforcer(), options, rootDir);
    }

    public static get instance():SkillsService {
        return SkillsService._instance;
    }

    /**
     * Only for use with the dev-shell. Clears launch rules, and sets only the dev skill's
     * launch rules and the global rules
     * @param launchPaths gotten for skills launches
     * @param callback
     */
    public static setGlobalListenRules(launchPaths:string[], callback:(error?:Error) => void) {
        PerformanceService.instance.log(Date.now(), 'JiboSetLaunchRule');
        RuleManager.instance.clearCache();
        function combineGlobalRules(done) {
            let globalCommandsPath:string = path.join(findRoot(__dirname), 'resources/rules/GlobalCommandsLaunch.rule');
            if(!globalCommandsPath) {
                return done("Initializing GLService with no global rules");
            }
            GlobalListen.getInstance().getCombinedUri([globalCommandsPath], (error: Error, uri: string) => {
                PerformanceService.instance.log(Date.now(), 'JiboCombineGlobalRules');

                if (error) {
                    return done(error);
                }
                GlobalListen.getInstance().setGlobalRule(uri);
                done();
            });
        }

        function combineLaunchRules(done) {
            // no launch paths supplied to SSM.
            if(launchPaths.length === 0) {
                return done();
            }
            GlobalListen.getInstance().getCombinedUri(launchPaths, (error: Error, uri: string) => {
                PerformanceService.instance.log(Date.now(), 'JiboCombineLaunchRules');
                if (error) {
                    return done(error);
                }
                GlobalListen.getInstance().setLaunchRule(uri);
                done();
            }, {ignoreErrors: true});
        }
        async.parallel([combineGlobalRules, combineLaunchRules], callback);
    }

    public static setSingleLaunchRule(skillRecord:SkillRecord, callback:(error?:Error) => void):void {
        //get the launch paths for this single skill
        let launchPaths:string[] = [];
        let packagePath:string = path.join(skillRecord.path, 'package.json');
        let packageJson:any = require(packagePath);
        if (packageJson.jibo && packageJson.jibo.launchRule) {
            if (Array.isArray(packageJson.jibo.launchRule)) {
                packageJson.jibo.launchRule.forEach((rule) => {
                    launchPaths.push(path.join(skillRecord.path, rule));
                });
            }
            else if (typeof packageJson.jibo.launchRule === 'string') {
                launchPaths.push(path.join(skillRecord.path, packageJson.jibo.launchRule));
            }
        }
        SkillsService.setGlobalListenRules(launchPaths, callback);
    }

    constructor(enforcer:SingletonEnforcer, public options:SkillsServiceOptions, rootDir:string) {
        super('skills-service', options, rootDir);
        if (SkillsService._instance) {
            throw new Error('SkillsService is a singleton');
        }
        SkillsService._instance = this;

        log.info("Initialized");
    }

    public init(callback:(error?:Error) => void) {
        super.init((error:Error) => {
            if (error) {
                return callback(error);
            }
            ScreenScheduler.stopTimerAndTurnOn().then(() => {
                this.setLaunchRules(callback);
            });
        });
    }

    public setLaunchRules(callback:(error?:Error) => void, shouldLaunch:boolean=true) {
        //if there is no start skill set no launch rules
        if (!this.options.startSkill) {
            SkillsService.setGlobalListenRules([], (error:Error) => {
                callback(error);
            });
            return;
        }
        //If the SSM is in single skill mode
        if (this.options.singleSkill) {
            console.warn("SSM operating in single skill mode");
            //get the single skill record
            SystemManagerClient.instance.getSkillRecordByName(this.options.startSkill, (error:Error, skillRecord:SkillRecord) => {
                //set its launch rule in global listen
                SkillsService.setSingleLaunchRule(skillRecord, (error) => {
                    if (error) {
                        return callback(error);
                    }
                    //launch it!
                    if(shouldLaunch) {
                        this.launch(this.options.startSkill, {}, callback);
                    }
                    else {
                        callback();
                    }
                });
            });
        }
        else if (!this.options.singleSkill) {
            //TODO -> loop through all the skills and add their launch rules
        }
    }

    public routes(url:Router):void {
        super.routes(url);

        url.get('/skill/list', (req:JiboServerRequest, res:JiboServerResponse) => {
            SystemManagerClient.instance.list((error:Error, skills:Array<SkillRecord>) => {
                if(error) {
                    return this.sendJson(res, {error: error.message}, 500);
                }
                this.sendJson(res, {skills: skills});
            });
        });

        url.get('/devtools', (req:JiboServerRequest, res:JiboServerResponse) => {
            DevToolsClient.createInstance('127.0.0.1', 9191).getJson((err:any, json:any) => {
                this.sendJson(res, json);
            });
        });

        url.get('/ssm-devtools', (req:JiboServerRequest, res:JiboServerResponse) => {
            DevToolsClient.createInstance('127.0.0.1', 12345).getJson((err:any, json:any) => {
                this.sendJson(res, json);
            });
        });

        url.get('/version', (req:JiboServerRequest, res:JiboServerResponse) => {
            const root:string = findRoot(__dirname);
            const packageInfo:any = require(path.join(root, 'package.json'));
            this.sendJson(res, {version: packageInfo.version});
        });

        url.post('/launch-dev', (req:JiboServerRequest, res:JiboServerResponse) => {
            let chunk = "";
            req.on('data', (data) => {
                chunk += (data);
            });

            req.on('end', () => {
                let data;
                try {
                    data = JSON.parse(chunk);
                }
                catch (e) {
                    this.sendJson(res, {
                        Status: 'ERROR',
                        Message: 'Invalid request from launch. Request body is not valid JSON'
                    }, 200);
                    return;
                }
                console.info('attempting to run skill', data.command);
                this.launch(data.command, {}, (error?:Error) => {
                    if (error) {
                        console.error('error running skill', data.command, error);
                        this.sendJson(res, {
                            Status: 'ERROR',
                            Message: 'Skill "' + name + '" does not exist or could not by launched. Make sure to run `jibo sync`'
                        }, 200);
                    }
                    else {
                        console.info('System Manager launched skill', data.command);
                        this.sendJson(res, {
                            Status: 'OK',
                            Message: 'Skill "' + name + '" started successfully'
                        }, 200);
                    }
                });

            });
        });


        url.post('/terminate', (req:JiboServerRequest, res:JiboServerResponse) => {
            let chunk = "";
            req.on('data', (data) => {
                chunk += (data);
            });

            req.on('end', () => {
                let data;
                try {
                    data = JSON.parse(chunk);
                }
                catch (e) {
                    this.sendJson(res, {
                        Status: 'ERROR',
                        Message: 'Invalid request from launch. Request body is not valid JSON'
                    }, 200);
                    return;
                }
                SystemManagerClient.instance.terminate(data.command, (error:Error) => {
                    ipcRenderer.send('show');
                    ScreenScheduler.start();
                    this.currentSkill = null;
                    this.finishNoContent(res);
                });

            });
        });
    }


    public launch(skillName:string, parse:any, callback:(error?:Error) => void):void {
        PerformanceService.instance.log(Date.now(), 'JiboLaunch');

        let launch = (skill:SkillRecord) => {
            this.currentSkill = skill;
            if (this.options.singleSkill) {
                SkillsService.setSingleLaunchRule(skill, (error:Error) => {
                    if (error) {
                        return callback(error);
                    }
                    SystemManagerClient.instance.launch(skill.name, (error:Error) => {
                        if(error) {
                            return callback(error);
                        }
                        ScreenScheduler.stopTimerAndTurnOn().then(() => {
                            callback();
                        }).catch((error) => {
                            callback(error);
                        });
                    });
                });
            }
        };

        SystemManagerClient.instance.getSkillRecordByName(skillName, (error:Error, skill:SkillRecord) => {
            PerformanceService.instance.log(Date.now(), 'JiboLaunchGetSkillRecordByName');
            if (error) {
                return callback(error);
            }
            if (this.currentSkill) {
                SystemManagerClient.instance.terminate(this.currentSkill.name, (error:Error) => {
                    PerformanceService.instance.log(Date.now(), 'JiboLaunchTerminateCurrentSkill');
                    if (error) {
                        return callback(error);
                    }
                    launch(skill);
                });
            }
            else {
                launch(skill);
            }
        });
    }

    /**
     * Reset the GL launch and global rules, but using the current skill.
     * Used when NLU Service goes down.
     * @param {Function} callback for when launch rules are reset.
     */
    public resetLaunchRules(callback:(error?:Error) => void) {
        SkillsService.setSingleLaunchRule(this.currentSkill, callback);
    }

    /**
     * Terminate currently running skill
     */
    public terminate(callback:(error?:Error) => void):string {
        if (!this.currentSkill) {
            callback();
            return;
        }
        SystemManagerClient.instance.terminate(this.currentSkill.name, (error:Error) => {
            this.currentSkill = null;
            ScreenScheduler.start();
            ipcRenderer.send('show');
            if (error) {
                return callback(error);
            }
            callback();
        });
    }

    /**
     * Called when a client sends a message over WebSocket
     * @param command
     * @param client
     */
    protected onMessage(command:any, client:WebSocket):void {
        if (command.command === 'initDone') {
            console.info(this.currentSkill.name, 'launched and initialized');
            ipcRenderer.send('hide');
            this.sendWsJson(client, {
                command: 'show'
            });
        }
        else if (command.command === 'finished') {
            if(this.currentSkill.name === '@be/be') {
                let relaunchResults:any = {};
                relaunchResults.Input = '';
                relaunchResults.NLParse = {
                    skill: '@be/idle'
                };
                relaunchResults.status = "GOT-PARSE";
                GlobalManagerService.instance.handleSkillLaunch(relaunchResults);
            }
        }
    }

}

export default SkillsService;
