import Router = require('router');
import {JiboServerRequest, JiboServerResponse, ServiceOptions, HTTPWSService} from 'jibo-service-framework';
import WebSocket = require("ws-without-native");
import {ASRResponseOptions, ResponseStatus, EventType, default as ASRResponse} from "./ASRResponse";
import {SpeakerId, Speaker} from 'jibo-common-types';
import {createLog} from "../../utils/Log";
let log = createLog("ssm-asr-service");

class SingletonEnforcer { }


/**
 * @interface ASRServiceRequest
 * @description Items to request and send for faking ASR Data.
 * @param {string} [audio_source_id] ID of audio source to "hear" through.
 * @param {string} [bargein] Type of bargein to be used.
 * @param {string} [command] Command to send to ASR Service for action "start", "stop".
 * @param {boolean} [hasBeenAcknowledged] Keep track of whether we have sent an acknowledgement to this action.
 * @param {boolean} [hasMadeFristResponse] Keep track of whether we have begun speech yet.
 * @param {boolean} [heardHotphrase] Keep track of whether we have heard "hey jibo" yet.
 * @param {string} [hotphrase] Hotphrase to listen for.
 * @param {boolean} [incremental] True to listen for incremental results.
 * @param {boolean} [isActive] Keep track of whether action is actively listening or not.
 * @param {number} [nbest] Number of results to send back.
 * @param {string} [request_id] Request ID of action.
 * @param {any} [speaker_id] Speaker ID recognized in action.
 * @param {boolean} [speech_to_text] True to listen for speech_to_text results.
 * @param {string} [task_id] Task ID of audio action.
 * @memberof module:skills-service-manager/services/asr-service
 */
interface ASRServiceRequest {
    audio_source_id?: string;
    bargein?: string;
    command: string;
    hasBeenAcknowledged?: boolean;
    hasMadeFirstResponse?: boolean;
    heardHotphrase?: boolean;
    hotphrase?: string;
    incremental?: boolean;
    isActive?: boolean;
    nbest?: number;
    request_id: string;
    speaker_id?: any;
    speech_to_text?: boolean;
    task_id: string;
}

/*
 * @type Message
 * @description message request to ASR Service
 * @member url {string} ASR Interface url to send the request.
 * @member data {any} Data to send with ASR Request.
 * @member res {JiboServerResponse} Response to call to ASR Service.
 */
type Message = {
    url: string;
    data: any;
    res: JiboServerResponse;
}

/*
 * @type Task
 * @description Task to be sent to ASR Service
 * @member task {any} Set of parameters to send to ASR Service.
 * @member id {string} ID of task
 */
type Task = {
    task: any;
    id: string;
}


/**
 * @description
 * ASR Service. Simulator. Fakes ASR Service.
 * @module skills-service-manager/services/asr-service
 */
class ASRService extends HTTPWSService {


    private static _instance: ASRService;
    public socket: WebSocket;
    private connectionHandlers: { [id: string]: (data: any, res: JiboServerResponse) => void };
    private messages: Message[] = [];
    private sources: string[] = [];
    private currentSource: string;
    /**
     * Map between Action IDs and actual audio service request
     * @name skills-service-manager/services/asr-service#actions
     * @type {Map<string, ASRServiceRequest>}
     */
    private actions = new Map<string, ASRServiceRequest>();

    public static get actions(): Map<string, ASRServiceRequest> {
        return ASRService._instance.actions;
    }

    public static createInstance(options: ServiceOptions, rootDir: string): ASRService {
        return new ASRService(new SingletonEnforcer(), options, rootDir);
    }

    public static get instance(): ASRService {
        return ASRService._instance;
    }

    constructor(enforcer: SingletonEnforcer, options: ServiceOptions, rootDir: string) {
        super('asr', options, rootDir);
        ASRService._instance = this;
        this.parseMessage = this.parseMessage.bind(this);
        this.connectionHandlers = {
            '/asr_interface': this.onAsrInterface.bind(this),
            '/asr_simple_interface': this.onAsrSimple.bind(this),
            '/audio_source': this.onAudioSource.bind(this),
            '/spkr_id_interface': this.onSpeakerIdInterface.bind(this)
        };
        log.info("Initialized");
    }

    public init(callback: (err?: Error) => void) {
        super.init((err: Error) => {
            callback(err);
        });
    }

    public onConnection(client: WebSocket): void {
        super.onConnection(client);
        // if (client.upgradeReq.url === '/port') {
        //     this.socket = client;
        //     this.processMessages();
        // }
        if (client.upgradeReq.url === '/simple_port') {
            this.socket = client;
            this.processMessages();
        }
    }

    public routes(url: Router) {
        super.routes(url);
        url.post('/asr_interface', this.parseMessage);
        url.post('/asr_simple_interface', this.parseMessage);
        url.post('/audio_source', this.parseMessage);
        url.post('/spkr_id_interface', this.parseMessage);
    }


    public onMessage(command: any, client: WebSocket): void {
        return;
    }

    public onClose(client: WebSocket): void {
        this.socket = null;
        this.messages = [];
        this.sources = [];
        this.actions.clear();
        this.currentSource = null;
    }

   /**
    * Responsible for managing action statuses as if it were ASR Service.
    * @method module:skills-service-manager/services/asr-service#onWordsReceived
    * @param {any} wordOptions for listening task, including words and ids.
    * @param {String} wordOptions.words Words for service to "hear"
    * @param {SpeakerId} wordOptions.speaker Speaker ID for service to recognize.
    * @public
    */
    public onWordsReceived(wordOptions: any) {
        if(wordOptions.message === "TEST") {
            console.log(wordOptions);
        }
        this.actions.forEach((action: ASRServiceRequest) => {
            if(!action.isActive) {
                return;
            }

            if(!action.hasBeenAcknowledged) {
                action.hasBeenAcknowledged = true;
                this._sendAcknowledgement(action, wordOptions);
            }

            if(wordOptions.message === "TEST") {
                console.log(action);
            }

            if (wordOptions.words) {
                wordOptions.words = wordOptions.words.trim();
            }

            // Words are here, send speaker ID
            if(!action.hasMadeFirstResponse) {
                action.hasMadeFirstResponse = true;
                this._sendSpeakerId(action, wordOptions);
            }

            // Listening for hey jibo
            // listening for hotphrase and we haven't already heard it.
            if (action.hotphrase && !action.heardHotphrase) {
                let i = wordOptions.words ? wordOptions.words.indexOf('hey jibo') : -1;
                // we heard it!
                if (i !== -1) {
                     action.heardHotphrase = true;
                     this._sendHotphrase(action, wordOptions);
                     // Don't send an incremental for the words that triggered hot-phrase.
                     if (!wordOptions.final) {
                         return;
                     }
                } else {
                    return; // In hot-phrase mode, ignore everything until we see the phrase.
                }
            }

            if(wordOptions.final) {
                action.isActive = false;
                this._sendEOS(action, wordOptions);
                this._sendSTTFinal(action, wordOptions);
                this._sendAcknowledgement(action, wordOptions);
            }
            else {
                this._sendIncremental(action, wordOptions);
            }
        });
    }

   /**
    * Send hotphrase recognition to socket from given action.
    * @method module:skills-service-manager/services/asr-service#_sendHotphrase
    * @param {ASRServiceRequest} action Action from ASR Service.
    * @param {Object} wordOptions for listening task, including words and ids.
    * @param {String} wordOptions.words Words for service to "hear"
    * @param {SpeakerId} wordOptions.speaker Speaker ID for service to recognize.
    * @private
    */
    private _sendHotphrase(action:ASRServiceRequest, wordOptions) {
        let hotphraseResponse = this._makeASRRequestFromAction(action, wordOptions);
        hotphraseResponse.event_type = EventType.HOTPHRASE;
        hotphraseResponse.utterances = [{ utterance: 'hey jibo', score: 1000 }];
        this.sendOptions(hotphraseResponse);
    }

    /**
     * Send speakerId recognition to socket from given action.
     * @method module:skills-service-manager/services/asr-service#_sendSpeakerId
     * @param {ASRServiceRequest} action Action from ASR Service.
     * @param {Object} wordOptions for listening task, including words and ids.
     * @param {String} wordOptions.words Words for service to "hear"
     * @param {SpeakerId} wordOptions.speaker Speaker ID for service to recognize.
     * @private
     */
    private _sendSpeakerId(action:ASRServiceRequest, wordOptions) {
        let speakerIdResponse = this._makeASRRequestFromAction(action, wordOptions);
        speakerIdResponse.event_type = EventType.SPEAKER_ID;
        speakerIdResponse.utterances = [{ utterance: '', score: 1000 }];
        this.sendOptions(speakerIdResponse);
    }

   /**
    * Send incremental recognition to socket from given action.
    * @method module:skills-service-manager/services/asr-service#_sendIncremental
    * @param {ASRServiceRequest} action Action from ASR Service.
    * @param {Object} wordOptions for listening task, including words and ids.
    * @param {String} wordOptions.words Words for service to "hear"
    * @param {SpeakerId} wordOptions.speaker Speaker ID for service to recognize.
    * @private
    */
    private _sendIncremental(action:ASRServiceRequest, wordOptions) {
       // According to the protocol, we don't emit Incremental events if they're not requested.
       if (action.incremental && action.speech_to_text) {
           let incrOptions = this._makeASRRequestFromAction(action, wordOptions);
           if (wordOptions.utterances) {
               incrOptions.utterances = wordOptions.utterances;
           } else {
               incrOptions.utterances = [{utterance: wordOptions.words, score: 1000}];
           }
           incrOptions.event_type = EventType.INCREMENTAL;
           this.sendOptions(incrOptions);
       }
    }

   /**
    * Send end_of_speech recognition to socket from given action.
    * @method module:skills-service-manager/services/asr-service#_sendEOS
    * @param {ASRServiceRequest} action Action from ASR Service.
    * @param {Object} wordOptions for listening task, including words and ids.
    * @param {String} wordOptions.words Words for service to "hear"
    * @param {SpeakerId} wordOptions.speaker Speaker ID for service to recognize.
    * @private
    */
    private _sendEOS(action:ASRServiceRequest, wordOptions) {
        let eosResponse = this._makeASRRequestFromAction(action, wordOptions);
        eosResponse.event_type = EventType.END_OF_SPEECH;
        this.sendOptions(eosResponse);
    }

   /**
    * Send speech_to_text_final recognition to socket from given action.
    * @method module:skills-service-manager/services/asr-service#_sendSTTFinal
    * @param {ASRServiceRequest} action Action from ASR Service.
    * @param {Object} wordOptions for listening task, including words and ids.
    * @param {String} wordOptions.words Words for service to "hear"
    * @param {SpeakerId} wordOptions.speaker Speaker ID for service to recognize.
    * @private
    */
    private _sendSTTFinal(action:ASRServiceRequest, wordOptions) {
       // According to the protocol, we don't emit STT events if they're not requested.
       if (action.speech_to_text) {
           let sttResponse = this._makeASRRequestFromAction(action, wordOptions);
           if (wordOptions.utterances) {
               sttResponse.utterances = wordOptions.utterances;
           } else {
               sttResponse.utterances = [{utterance: wordOptions.words, score: 1000}];
           }
           sttResponse.event_type = EventType.SPEECH_TO_TEXT_FINAL;
           this.sendOptions(sttResponse);
       }
    }

   /**
    * Send acknowledgement recognition to socket from given action.
    * @method module:skills-service-manager/services/asr-service#_sendAcknowledgement
    * @param {ASRServiceRequest} action Action from ASR Service.
    * @param {Object} wordOptions for listening task, including words and ids.
    * @param {String} wordOptions.words Words for service to "hear"
    * @param {SpeakerId} wordOptions.speaker Speaker ID for service to recognize.
    * @private
    */
    private _sendAcknowledgement(action:ASRServiceRequest, wordOptions) {
        let acknowledgementOptions = this._makeASRRequestFromAction(action, wordOptions);
        acknowledgementOptions.event_type = EventType.ACKNOWLEDGEMENT;
        this.sendOptions(acknowledgementOptions);
    }

   /**
    * Send hotphrase recognition to socket from given action.
    * @method module:skills-service-manager/services/asr-service#_sendHotphrase
    * @param {ASRServiceRequest} action Action from ASR Service.
    * @param {Object} wordOptions for listening task, including words and ids.
    * @param {String} wordOptions.words Words for service to "hear"
    * @param {SpeakerId} wordOptions.speaker Speaker ID for service to recognize.
    * @private
    */
    private sendOptions(response: ASRResponseOptions) {
        this.socket.send(JSON.stringify(response));
    }

    /**
     * Make an ASR Request given an action and word options.
     * @method module:skills-service-manager/services/asr-service#_makeASRRequestFromAction
     * @param {ASRServiceRequest} Action to send to ASR Service.
     * @param {wordOptions} wordOptions for listening task, including words and ids.
     * @private
     */
    private _makeASRRequestFromAction(action:ASRServiceRequest, wordOptions): ASRResponseOptions {
        let asrResponse = new ASRResponse();
        asrResponse.task_id = action.task_id;
        // asrResponse.id = action.task_id;
        asrResponse.request_id = action.request_id;
        asrResponse.speaker_id = new SpeakerId({
            status: "NOT-USED",
            speakers: []
        });
        if(wordOptions.speaker) {
            asrResponse.speaker_id.status = "ACCEPTED";
            asrResponse.speaker_id.speakers.push(new Speaker(wordOptions.speaker, 1000));
        }
        return asrResponse;
    }

    /**
     * Redirect and process message requests sent to ASR Service.
     * @param {JiboServerRequest} Request sent to ASR Service.
     * @param {JiboServerResponse} Response to ASR Service Request.
     * @method module:skills-service-manager/services/asr-service#parseMessage
     * @private
     */
    private parseMessage(req: JiboServerRequest, res: JiboServerResponse): void {
        req.on('data', (chunk) => {
            let data: any;
            try {
                data = JSON.parse(chunk);
                this.messages.push({
                    url: req.url,
                    data,
                    res
                });
            }
            catch (e) {
                if (this.socket) {
                    this.sendWsJson(this.socket, {
                        status: 'error',
                        message: 'ERROR Invalid request. Request body is not valid JSON'
                    });
                }
                this.sendJson(res, {
                    Status: 'ERROR',
                    Message: 'Inavlid request. Request body is not valid JSON'
                }, 200);
            }
            if (this.socket) {
                this.processMessages();
            }
        });
    }

    /**
     * Process message request queue to ASR Service
     * @method module:skills-service-manager/services/asr-service#processMessages
     * @private
     */
    private processMessages(): void {
        while (this.messages.length) {
            let message = this.messages.shift();
            this.connectionHandlers[message.url](message.data, message.res);
        }
    }

    /**
     * Process message requests sent to asr_simple interface
     * @param data {ASRServiceRequest} data sent to ASR Service as listening request.
     * @param {JiboServerResponse} Response to ASR Service Request.
     * @method module:skills-service-manager/services/asr-service#onAsrSimple
     * @private
     */
    private onAsrSimple(data: ASRServiceRequest, res: JiboServerResponse): void {
        let asrResponse: ASRResponse = new ASRResponse({
            message: "received data request",
            task_id: data.task_id,
            status: ResponseStatus.NORMAL,
            event_type: EventType.ACKNOWLEDGEMENT
        });
        let action: ASRServiceRequest;
        let message = "received data request";
        if (data.command === "start") {
            if (this.actions.has(data.task_id)) {
                action = this.actions.get(data.task_id);
            }
            else {
                this.actions.set(data.task_id, data);
                action = data;
            }
            action.isActive = true;
            this.sendResponse(res, asrResponse);
        }

        else if (data.command === "enroll") {
            this.sendResponse(res, asrResponse);
            asrResponse.status = ResponseStatus.ERROR;
            message = "ERROR: cannot enroll via simulated ASR";
        }

        else if (data.command === "stop") {
            action = this.actions.get(data.task_id);
            if(!action || !action.isActive) {
                asrResponse.status = ResponseStatus.ERROR;
                message = "ERROR: cannot stop action which was not started" + data.task_id;
            }
            else {
                action.isActive = false;
            }
            this.sendResponse(res, asrResponse);
        }
    }

    /**
     * Process message requests sent to asr_interface interface.
     * @param data {ASRServiceRequest} data sent to ASR Service as listening request.
     * @param {JiboServerResponse} Response to ASR Service Request.
     * @method module:skills-service-manager/services/asr-service#onAsrSimple
     * @private
     */
    private onAsrInterface(data: ASRServiceRequest, res: JiboServerResponse): void {
        let asrResponse: ASRResponse = new ASRResponse({
            message: "received data request",
            task_id: data.task_id,
            status: ResponseStatus.NORMAL,
            event_type: EventType.RECEIVED
        });
        let action: ASRServiceRequest;
        let message = "received data request";
        if (data.command === "start") {
            if (this.actions.has(data.task_id)) {
                action = this.actions.get(data.task_id);
            }
            else {
                this.actions.set(data.task_id, data);
                action = data;
            }
            action.isActive = true;
            this.sendResponse(res, asrResponse);
        }

        else if (data.command === "enroll") {
            this.sendResponse(res, asrResponse);
            asrResponse.status = ResponseStatus.ERROR;
            message = "ERROR: cannot enroll via simulated ASR";
        }

        else if (data.command === "stop") {
            action = this.actions.get(data.task_id);
            if(!action) {
                asrResponse.status = ResponseStatus.ERROR;
                message = "ERROR: cannot stop action which was not started" + data.task_id;
            }
            else {
                action.isActive = false;
            }
            this.sendResponse(res, asrResponse);
        }
    }

    /**
     * Send ASR response through websocket.
     * @param {JiboServerResponse} Response to ASR Service Request.
     * @param data {ASRServiceRequest} data sent to ASR Service as listening request.
     * @method module:skills-service-manager/services/asr-service#sendResponse
     * @private
     */
    private sendResponse(res:JiboServerResponse, data: ASRResponse) {
        this.sendJson(res, {
            Status: 'OK',
            Message: 'received ASR request'
        }, 200);
        this.sendWsJson(this.socket, data);
    }

    /**
     * Handle Audio Source requests sent to ASR Service
     * @param data {ASRServiceRequest} data sent to ASR Service as listening request.
     * @param {JiboServerResponse} Response to ASR Service Request.
     * @method module:skills-service-manager/services/asr-service#onAudioSource
     * @private
     */
    private onAudioSource(data: any, res: JiboServerResponse): void {
        let asrResponse: ASRResponse = new ASRResponse({
            status: ResponseStatus.RECEIVED,
            task_id: data.task_id
        });
        // TODO: include way to include "wav" files (txt files)
        if (data.action === "start") {
            this.sources.push(data.audio_source_id);
            this.currentSource = data.audio_source_id;
        }
        else if (data.action === "clear") {
            let i = this.sources.indexOf(data.audio_source_id);
            this.sources.splice(i, 1);
        }

        this.sendJson(res, {
            Status: 'OK',
            Message: 'received data request'
        }, 204);
        this.sendWsJson(this.socket, asrResponse);
    }

    /**
     * Handle Speaker Interface requests sent to ASR Service
     * @param data {ASRServiceRequest} data sent to ASR Service as listening request.
     * @param {JiboServerResponse} Response to ASR Service Request.
     * @method module:skills-service-manager/services/asr-service#onSpeakerIdInterface
     * @private
     */
    private onSpeakerIdInterface(data: any, res: JiboServerResponse): void {
        this.sendJson(res, {
            Status: 'OK',
            Message: 'received data request'
        }, 200);
        let returnData = { status: ResponseStatus.RECEIVED, type: "spkrId" };
        this.sendWsJson(this.socket, returnData);
    }
}


export default ASRService;