import {ServiceOptions, HTTPWSService, JiboServerRequest, JiboServerResponse} from 'jibo-service-framework';
import WebSocket = require('ws-without-native');
import WiFiManager from "./WifiManager";
import {ErrorMsgCallback, ErrorCodeCallback, NetworkData, NetworkStats, SetNetworkOptions, SavedNetworkEntry} from "./WifiManager";
import {createLog} from "../../utils/Log";
import async = require('async');
import Router = require('router');
import ErrorCode from "./scanning/ErrorCode";
//import {WifiCallback} from "../../clients/SystemManagerClient";

let startVerifyTime:number = 0;

interface WifiOptions extends ServiceOptions {
    region:string;
}

class WifiService extends HTTPWSService {

    private static _instance: WifiService;

    public log:any;
    private _wifiMgr:WiFiManager;
    private _eventSocket:WebSocket;


    public static createInstance(options: WifiOptions, rootDir: string): WifiService {
        return new WifiService(options, rootDir);
    }

    public static get instance(): WifiService {
        return WifiService._instance;
    }

    constructor(public options: WifiOptions, rootDir: string) {
        super('wifi', options, rootDir);
        if (WifiService._instance) {
            throw new Error('WifiService is a singleton');
        }

        this.log = createLog("ssm-wifi-service");
        WifiService._instance = this;

        this._wifiMgr = new WiFiManager(this);
        this._eventSocket = null;

        this.log.info("Initialized");
    }

    public init(callback:ErrorMsgCallback): void {
        super.init((error?: Error) => {
            if (error) {
                return callback(error);
            }
            this._wifiMgr.init(callback);
        });
    }

    public routes(url:Router):void {
        super.routes(url);

        url.post('/remove_all', (req:JiboServerRequest, res:JiboServerResponse) => {
            this._onRemoveAll(req, res);
        });

        url.post('/remove_network', (req:JiboServerRequest, res:JiboServerResponse) => {
            this._onRemoveNetwork(req, res);
        });

        url.post('/select_network', (req:JiboServerRequest, res:JiboServerResponse) => {
            this._onSelectNetwork(req, res);
        });

        url.post('/add_network', (req:JiboServerRequest, res:JiboServerResponse) => {
            this._onAddNetwork(req, res);
        });

        url.post('/get_current_network', (req:JiboServerRequest, res:JiboServerResponse) => {
            this._onGetCurrentNetwork(req, res);
        });

        url.post('/get_saved_networks', (req:JiboServerRequest, res:JiboServerResponse) => {
            this._onGetSavedNetworks(req, res);
        });

        url.post('/verify_connection', (req:JiboServerRequest, res:JiboServerResponse) => {
            this._onVerifyConnection(req, res);
        });
    }

    public onConnection(client:WebSocket):void {
        super.onConnection(client);
        if(client.upgradeReq.url === '/wifi_events') {
            this._eventSocket = client;
        }
    }

    protected onClose(client:WebSocket):void {
        if(client === this._eventSocket) {
            this._eventSocket= undefined;
        }
    }

    protected onMessage(command: any, client: WebSocket): void {
        return;
    }

    public sendSocketData(_eventName:string, _data?:any) {
        if(this._eventSocket) {
            let socketData = {
                eventName: _eventName,
                data: _data
            };
            this.sendWsJson(this._eventSocket, socketData);
        }
    }

    public sendError(_data?:any) {
        this.sendSocketData("error", _data);
        this.log.info("error:", _data);
    }

    public verifyConnection(cb:ErrorCodeCallback) {
        this._wifiMgr.verifyConnection(cb);
    }

    public getScanResults(cb:(err:Error, results?:Array<string>) => void):void {
        this._wifiMgr.scan((err:Error, data:string)=> {
            if (err) {
                cb(new Error("Error scanning: " + err));
            }
            else {
                this._wifiMgr.getScanResults((err:Error, data)=> {
                    if (err) {
                        return cb(new Error("Error scanning results:" + err));
                    }

                    // convert to arrays and remove top entry
                    let results = data.split('\n');
                    if (results.length > 1) {
                        // there will always be a header for `bssid / frequency / signal level / flags / ssid`
                        // so remove it if we have at least one entry
                        results.shift();

                        // remove any empty lines
                        //results have a trailing new line, so ensure that we don't keep it
                        for (let i = results.length - 1; i >= 0; --i) {
                            if (!results[i]) {
                                results.pop();
                            } else {
                                break;
                            }
                        }

                        cb(null, results);
                    }
                    else {
                        cb(null, []);   // return empty array (nothing scanned)
                    }

                });
            }
        });
    }

    // @TODO- move constant variables to global space (rssi, etc.)
    public getCurrentNetwork(cb:(error:Error, data?:NetworkStats) => void) {
        this._wifiMgr.status((err:Error, statsData:string) => {
            if(err) {
                cb(err);
            }
            else{
                let stats:NetworkStats = {
                    ssid:'',
                    strength: 0,
                    speed: 0,
                    ip_address:''
                };

                if(statsData.indexOf('wpa_state=COMPLETED') > -1) {
                    let splitData = statsData.split('\n');
                    // console.log(statsData);
                    let len = splitData.length;
                    for(let i = 0; i < len; i++) {
                        if (splitData[i].indexOf('ssid=') > -1) {
                            stats.ssid = splitData[i].split('=')[1];
                        }
                        else if (splitData[i].indexOf('ip_address=') > -1) {
                            stats.ip_address = splitData[i].split('=')[1];
                        }
                    }

                    this._wifiMgr.pollStats((err:Error, pollData:string) => {
                        if(err){
                            cb(err);
                        }
                        else{
                            // console.log(pollData);
                            let splitData = pollData.split('\n');

                            let rssi = null;
                            let len = splitData.length;
                            for(let i = 0; i < len; i++) {
                                if(splitData[i].indexOf('RSSI') > -1) {
                                    if (!rssi) {
                                        // only set it if not set yet (just in case AVG_RSSI set it first)
                                        rssi = parseInt(splitData[i].split('=')[1]);
                                    }
                                }
                                else if(splitData[i].indexOf('AVG_RSSI') > -1) {
                                    // always override rssi with the AVG_RSSI if found
                                    rssi = parseInt(splitData[i].split('=')[1]);
                                }
                                else if(splitData[i].indexOf('LINKSPEED') > -1) {
                                    stats.speed = parseInt(splitData[i].split('=')[1]);
                                }
                            }

                            if (rssi) {
                                if (rssi > -50) {
                                    stats.strength = 100;
                                }
                                else {
                                    stats.strength = (rssi + 100) * 2;
                                }
                            }

                            cb(null, stats);
                        }
                    });
                }
                else{
                    cb(new Error("Not Connected"));
                }
            }
        });
    }

    private _onVerifyConnection(req:JiboServerRequest,  res:JiboServerResponse) {
        let chunk = "";
        req.on('data', data => chunk += data);
        req.on('end', () => {
            this._wifiMgr.verifyConnection((error?:ErrorCode) => {
                if (error) {
                    return this.sendJson(res, error, 500);
                }
                this.sendJson(res, {status: 'OK'});
            });
        });
    }

    private _onRemoveAll(req:JiboServerRequest,  res:JiboServerResponse) {
        let chunk = "";
        req.on('data', data => chunk += data);
        req.on('end', () => {
            this._removeAllNetworks((error?:Error) => {
                if (error) {
                    return this.sendJson(res, {error: error.stack}, 500);
                }
                this.sendJson(res, {status: 'OK'});
            });
        });
    }

    private _onRemoveNetwork(req:JiboServerRequest,  res:JiboServerResponse) {
        let chunk = "";
        req.on('data', data => chunk += data);
        req.on('end', () => {
            let data;
            try {
                data = JSON.parse(chunk);
                this._removeNetwork(data.ssid, (error?:Error) => {
                    if (error) {
                        return this.sendJson(res, {error: error.stack}, 500);
                    }
                    this.sendJson(res, {status: 'OK'});
                });
            }
            catch(e) {
                console.warn('Wifi service cannot parse ', chunk);
                this.sendJson(res, {status: 'error', message: 'could not parse json', json: chunk}, 400);
            }
        });
    }

    private _onSelectNetwork(req:JiboServerRequest,  res:JiboServerResponse) {
        let chunk = "";
        req.on('data', data => chunk += data);
        req.on('end', () => {
            let data;
            try {
                data = JSON.parse(chunk);
                this._selectNetwork(data.ssid, (error?:Error) => {
                    if (error) {
                        return this.sendJson(res, {error: error.stack}, 500);
                    }
                    this.sendJson(res, {status: 'OK'});
                });
            }
            catch(e) {
                console.warn('Wifi service cannot parse ', chunk);
                this.sendJson(res, {status: 'error', message: 'could not parse json', json: chunk}, 400);
            }
        });
    }

    private _onAddNetwork(req:JiboServerRequest, res:JiboServerResponse) {
        let chunk = "";
        req.on('data', data => chunk += data);
        req.on('end', () => {
            let data;
            try {
                data = JSON.parse(chunk);
                this._addNetwork(data.networkData, data.minVerifyTime, (error?:ErrorCode) => {
                    if (error) {
                        return this.sendJson(res, error, 500);
                    }
                    this.sendJson(res, {status: 'OK'});
                });
            }
            catch(e) {
                console.warn('Wifi service cannot parse ', chunk);
                this.sendJson(res, {status: 'error', message: 'could not parse json', json: chunk}, 400);
            }
        });
    }

    private _onGetCurrentNetwork(req:JiboServerRequest, res:JiboServerResponse) {
        let chunk = "";
        req.on('data', data => chunk += data);
        req.on('end', () => {
            this.getCurrentNetwork((error?:Error, _stats?:NetworkStats) => {
                if (error) {
                    return this.sendJson(res, {error: error.stack}, 500);
                }
                this.sendJson(res, {status: 'OK', stats: _stats});
            });
        });
    }

    private _onGetSavedNetworks(req:JiboServerRequest, res:JiboServerResponse) {
        let chunk = "";
        req.on('data', data => chunk += data);
        req.on('end', () => {
            this._wifiMgr.getSavedNetworks((error:Error, data?:Array<SavedNetworkEntry>) => {
                if (error) {
                    return this.sendJson(res, {error: error.stack}, 500);
                }
                this.sendJson(res, {status: 'OK', networks: data});
            });
        });
    }

    private _removeAllNetworks(callback:ErrorMsgCallback) {
        this._wifiMgr.getSavedNetworks((error:Error, data?:Array<SavedNetworkEntry>) => {
            if (data) {
                let tasks = [];
                let length = data.length;
                for (let i = 0; i < length; i++) {
                    tasks.push((callback) => {
                        this._wifiMgr.removeNetwork(data[i].index, data[i].ssid, callback);
                    });
                }
                async.parallel(tasks, (error?:Error) => {
                    callback(error);
                });
            }
        });
    }

    private _removeNetwork(ssid:string, callback:ErrorMsgCallback) {
        this._wifiMgr.getSavedNetworks((error:Error, data?:Array<SavedNetworkEntry>) => {
            if(error) {
                return callback(error);
            }

            let networkID = this._getNetworkID(ssid, data);
            if (networkID) {
                this._wifiMgr.removeNetwork(networkID, ssid, (err:Error)=>{
                    callback(err);
                });
            }
            else{
                callback(new Error(ssid + " is not currently saved"));
            }
        });
    }

    private _selectNetwork(ssid:string, callback:ErrorMsgCallback) {
        this._wifiMgr.getSavedNetworks((error:Error, data?:Array<SavedNetworkEntry>) => {
            if(error) {
                return callback(error);
            }

            let networkID = this._getNetworkID(ssid, data);
            if (networkID) {
                this._wifiMgr.selectNetwork(networkID, null, (err:Error)=>{
                    if (err) {
                        callback(err);
                    }
                    else {
                        this._wifiMgr.saveNetwork(networkID, (err:Error) => {
                            callback(err);
                        });
                    }
                });
            }
            else{
                callback(new Error(ssid + " is not currently saved"));
            }
        });
    }

    private _getNetworkID(ssid:string, data:Array<SavedNetworkEntry>):string {
        let foundNetworkId:string = null;
        const networkLen = data.length;
        for(let idx = 0; idx < networkLen; idx++) {
            if(data[idx].ssid === ssid) {
                foundNetworkId = data[idx].index;
                break;
            }
        }

        return foundNetworkId;
    }

    /*
     Checks saved Networks
     If it doesn't currently exist we add the network
     Configures the setings(ssid, network, psk) via supplicant
     Connects to the network
     */
    // @TODO - async.waterfall this sucker
    private _addNetwork(networkData:NetworkData, minVerifyTime:number, cb:ErrorCodeCallback) {
        if(this._wifiMgr.inProgress){
            let timer = setInterval(()=>{
                if(!this._wifiMgr.inProgress){
                    clearInterval(timer);
                    this._addNetwork(networkData, minVerifyTime, cb);
                }
                else{
                    console.log("Currently in process of adding network. Please wait!");
                }
            }, 1000);
        }
        else{
            this._wifiMgr.inProgress = true;
            if (!networkData.hasOwnProperty('ssid') || !networkData.ssid.length) {
                this._wifiMgr.inProgress = false;

                let error = new ErrorCode(6, "No SSID Specified");
                this.sendError(error);
                cb(error);
                return;
            }

            if(networkData.pswd.length === 0){
                networkData.security = "OPEN";
            }
            else if(networkData.pswd.length > 7 && networkData.pswd.length < 64){
                networkData.security = "WPA-PSK";
            }
            else{
                this._wifiMgr.inProgress = false;

                let error = new ErrorCode(5, "Invalid password length! Must be at least 8 characters and less than 64 characters");
                this.sendError(error);
                cb(error);
                return;
            }

            this._wifiMgr.getSavedNetworks((error:Error, networks?:Array<SavedNetworkEntry>) =>{
                if (error) {
                    return cb(new ErrorCode(666, error.message));
                }

                let networkID:string = this._getNetworkID(networkData.ssid, networks);
                if(networkID){
                    cb(new ErrorCode(666, networkData.ssid + " already exists...not adding"));
                    this._wifiMgr.inProgress = false;
                }
                else{
                    this._wifiMgr.addNetwork((err:Error, data:string)=>{
                        if(err){
                            this._wifiMgr.inProgress = false;
                            cb(new ErrorCode(666, "No access to wpa_cli " + err));
                        }
                        else{
                            let stringId:string = data.match(/\d+/)[0];
                            this._wifiMgr.scan((err:Error, data:string)=>{
                                if(err){
                                    this._wifiMgr.inProgress = false;
                                    cb(new ErrorCode(666, "Error Scanning! " + err));
                                }
                                else{
                                    this._wifiMgr.getScanResults((err,data)=>{
                                        if(err){
                                            this._wifiMgr.inProgress = false;
                                            cb(new ErrorCode(666, "Error retrieving Scan Results..."));
                                        }
                                        else{
                                            if(data.indexOf(networkData.ssid) > -1){
                                                console.log("network is NOT hidden!");
                                                networkData.hidden = 0;
                                            }
                                            else{
                                                console.log("network is hidden!");
                                                networkData.hidden = 1;
                                            }

                                            this._setNetwork(stringId, networkData, (err)=>{
                                                if(err){
                                                    this._wifiMgr.inProgress = false;
                                                    cb(new ErrorCode(1, "Could not set network! " + err));
                                                }
                                                else{
                                                    this._wifiMgr.saveNetwork(stringId, (err:Error)=>{
                                                        if(err){
                                                            this._wifiMgr.inProgress = false;
                                                            cb(new ErrorCode(666, "Could not save network! " + err));
                                                        }
                                                        else{
                                                            this._wifiMgr.selectNetwork(stringId, networkData, (err:Error)=>{
                                                                if(err){
                                                                    this._wifiMgr.inProgress = false;
                                                                    cb(new ErrorCode(1, "Could not select network! " + err));
                                                                }
                                                                else{
                                                                    this._wifiMgr.saveNetwork(stringId, (err:Error)=>{
                                                                        if(err){
                                                                            this._wifiMgr.inProgress = false;
                                                                            cb(new ErrorCode(666, "Could not save network! " + err));
                                                                        }
                                                                        else{
                                                                            if (minVerifyTime && minVerifyTime > 0) {
                                                                                console.log("Verifying network...");

                                                                                startVerifyTime = 0; // reset

                                                                                // kick off our timer in parallel
                                                                                let verifyTimer = setInterval(()=>{
                                                                                    startVerifyTime++;
                                                                                    // console.log("timer: " + startVerifyTime);
                                                                                }, 1000);

                                                                                this._verify(minVerifyTime, (errCode) => {
                                                                                    clearInterval(verifyTimer);
                                                                                    startVerifyTime = 0;

                                                                                    this._wifiMgr.inProgress = false;
                                                                                    if (errCode) {
                                                                                        // error happened
                                                                                        this.sendError(errCode);
                                                                                        cb(errCode);
                                                                                    }
                                                                                    else {
                                                                                        cb();
                                                                                    }
                                                                                });
                                                                            }
                                                                            else {
                                                                                this._wifiMgr.inProgress = false;
                                                                                cb();
                                                                            }
                                                                        }
                                                                    });
                                                                }
                                                            });
                                                        }
                                                    });
                                                }
                                            });
                                        }
                                    });
                                }
                            });
                        }
                    });
                }
            });
        }
    }

    /*
    Sets the specified settings via wpa_supplicant
    */
    // @TODO - collapse set network calls into one; we don't need to check each successful entry
    private _setNetwork(stringId:string, networkData:NetworkData, cb:ErrorMsgCallback) {

        let options:SetNetworkOptions = {
            ssid : networkData.ssid,
            psk: null,
            security : null,
            hidden: null
        };
        this._wifiMgr.setNetwork(stringId, options, (err:Error, data:string)=>{
            if(err){
                //   console.log("failed added ssid: " + err);
                cb(err);
            }
            else{
                console.log("Successfully added SSID " + networkData.ssid);

                if(networkData.pswd.length > 0){
                    let options:SetNetworkOptions = {
                        ssid : null,
                        psk:networkData.pswd,
                        security: null,
                        hidden: null
                    };
                    this._wifiMgr.setNetwork(stringId, options, (err:Error, data:string)=>{
                        if(err){
                            //console.log("failed psk: " + err);
                            cb(err);
                        }
                        else{
                            console.log("Successfully added PSK");

                            let options:SetNetworkOptions = {
                                ssid: null,
                                psk: null,
                                security: networkData.security,
                                hidden: null
                            };
                            this._wifiMgr.setNetwork(stringId, options, (err:Error, data:string)=> {
                                if (err) {
                                    //console.log("failed security setting: " + err);
                                    cb(err);
                                }
                                else {
                                    console.log("Successfully added Security");
                                    if(networkData.hidden === 1){
                                        let options:SetNetworkOptions = {
                                            ssid: null,
                                            psk: null,
                                            security: null,
                                            hidden: networkData.hidden
                                        };
                                        this._wifiMgr.setNetwork(stringId, options, (err:Error, data:string)=>{
                                            if(err){
                                                //console.log("failed set hidden: " + err);
                                                cb(new Error("Failed to set hidden SSID!"));
                                            }
                                            else{
                                                console.log("Successfully set (hidden) network!");
                                                cb();
                                            }
                                        });
                                    }
                                    else{
                                        console.log("Successfully set network!");
                                        cb();
                                    }
                                }
                            });
                        }
                    });
                }
                else if(networkData.pswd.length === 0){
                    let options:SetNetworkOptions = {
                        ssid: null,
                        psk:null,
                        security: networkData.security,
                        hidden: null
                    };
                    this._wifiMgr.setNetwork(stringId, options, (err:Error, data:string)=>{
                        if(err){
                            cb(err);
                        }
                        else{
                            //    console.log("Successfully added Security");
                            if(networkData.hidden === 1){
                                let options:SetNetworkOptions = {
                                    ssid: null,
                                    psk: null,
                                    security: null,
                                    hidden: networkData.hidden
                                };
                                this._wifiMgr.setNetwork(stringId, options, (err:Error, data:string)=>{
                                    if(err){
                                        cb(new Error("Failed to set hidden SSID!"));
                                    }
                                    else{
                                        // console.log("Successfully set network!");
                                        cb();
                                    }
                                });
                            }
                            else{
                                // console.log("Successfully set network!");
                                cb();
                            }
                        }
                    });
                }
                else{
                    cb(new Error("Invalid PSK Settings!"));
                }
            }
        });
    }

    // test connection for at least x secs (minVerifyTime) and return error if timed out;
    // stop test if passes (should return ErrorCode callback!)
    private _verify(minVerifyTime:number, cb:ErrorCodeCallback) {

        this._wifiMgr.verifyConnection((err?:ErrorCode) => {
            if (err) {
                if (startVerifyTime > minVerifyTime) {
                    // we timed out...
                    cb(err);
                }
                else {
                    // keep on checking....
                    this._verify(minVerifyTime, cb);
                }
            }
            else {
                cb();
            }
        });
    }
}

export default WifiService;
