import {StateMachine, State} from 'jibo-state-machine';
import {_GlobalListen, ListenerType} from '../GlobalListen';
import {ParseResults, ListenResults} from 'jibo-common-types';
import async = require('async');
import {GLOptions} from "../GLStateMachine";
import {ParseLaunch} from "../GLStateMachine";


/**
 * @description
 * ParseGlobalState
 * Parses all incoming messages from the ASR Service. It determines whether there
 * was a global or launch command parsed, including context of whether the phrase was
 * preceeded by a Hey Jibo.
 * @module skills-service-manager/services/listen-service/ParseGlobalState
 */
export default class ParseGlobalState extends State {

    public nativeSkillMap: {[key: string]: string};
    private nonInterruptingState: State;
    private handleGlobalParseState: State;
    private handleLaunchParseState: State;

    constructor(sm: StateMachine, name: string, private options: GLOptions) {
        super(sm, name);

        this.nonInterruptingState = options.nonInterruptingState;
        this.handleGlobalParseState = options.handleGlobalParseState;
        this.handleLaunchParseState = options.handleLaunchParseState;
    }

    emitNoGlobal(gl:_GlobalListen, hjHeard, results: ParseResults) {
        gl.events.listen.noGlobalMatch.emit(results);
        // If there are any HJ listeners then we notify them
        if (gl._activeHJListeners.size > 0 && hjHeard) {
            console.log(gl._activeHJListeners.size, "active HJ listeners");
            this.transitionTo(this.nonInterruptingState, ListenerType.HJ);
        }
        else {
            this.transitionTo(this.nonInterruptingState, ListenerType.NON_HJ);
        }
    }

    create(gl: _GlobalListen) {
        this.addInternalTransition('Local Win', this.nonInterruptingState);
        this.addInternalTransition('Global Win', this.handleGlobalParseState);
        this.addInternalTransition('Launch Win', this.handleLaunchParseState);

        this.onEntry = (trans, result) => {
            const parseLaunch = result as ParseLaunch;
            const listenResults = gl._lastCloudListenResults;
            const inputText = listenResults.result.Input;
            const willParseLaunch:boolean = (parseLaunch === ParseLaunch.HJ_HEARD || parseLaunch === ParseLaunch.FORCE_GLOBAL);
            let localParse:ParseResults;
            let globalParse:ParseResults;
            let launchParse:ParseResults;

            let parseAgainstRules = [];
            // get global parse
            parseAgainstRules.push((cb) => {
                gl.parseGlobal(listenResults, (err: any, parse: ParseResults) => {
                    if (err) {
                        cb(err);
                        return;
                    }
                    globalParse = parse || new ParseResults(inputText);
                    cb(null);
                });
            });
            // get skill launch rule parse if we parsed against Hey Jibo
            // could technically just check parseLaunch because of enum mappings, but this is more explicit.
            if(parseLaunch === ParseLaunch.FORCE_GLOBAL || parseLaunch === ParseLaunch.HJ_HEARD) {
                parseAgainstRules.push((cb) => {
                    gl.parseLaunch(listenResults, (err:any, parse:ParseResults) => {
                        if(err) {
                            cb(err);
                            return;
                        }
                        launchParse = parse || new ParseResults(inputText);
                        cb(null);
                    });
                });
            }
            // otherwise, give it an empty parse.
            else {
                launchParse = new ParseResults(inputText);
            }
            parseAgainstRules.push((cb) => {
                // parseLaunch.HJ_HEARD --> listener type HJ
                // parseLaunch.FORCE_GLOBAL --> listener type NHJ
                let listenerType:ListenerType = ListenerType.NON_HJ;
                if(parseLaunch === ParseLaunch.HJ_HEARD) {
                    listenerType = ListenerType.HJ;
                }
                gl.parseAndSaveLocal(listenResults, listenerType, (err:any, parses:ListenResults[]) => {
                    if(err) {
                        cb(err);
                        return;
                    }
                    // give it a temporary parse in case we don't get any parses.

                    // No local listeners subscribed
                    if (!parses.length) {
                        localParse = new ParseResults(listenResults.result.Input);
                        cb(null);
                        return;
                    }
                    // more than one cloud listener was subscribed with a local rule.
                    // want to take the highest heuristic score of the parses.
                    parses.sort((a, b) => {
                        return b.result.heuristic_score - a.result.heuristic_score;
                    });
                    localParse = parses[0].result;
                    cb(null);
                });
            });



            async.parallel(parseAgainstRules, (err,) => {
                if (err) {
                    return console.error(err);
                }

                const maxParseScore = Math.max(
                  (localParse.heuristic_score || 0),
                  (globalParse.heuristic_score || 0),
                  (launchParse.heuristic_score || 0));

                console.warn("local, global, and launch parses");
                console.warn(localParse);
                console.warn(globalParse);
                console.warn(launchParse);

                // Local parse is at least tied with max score, takes priority.
                if(localParse.heuristic_score === maxParseScore) {
                    this.emitNoGlobal(gl, willParseLaunch, localParse);
                }

                // launch parse won, and hjHeard
                else if(launchParse.heuristic_score === maxParseScore && willParseLaunch) {
                    listenResults.result.launchParse = launchParse;
                    this.transitionTo(this.handleLaunchParseState, listenResults);
                }

                // Global parsed higher than local, and could not be a launch parse since no HJ
                else if(globalParse.heuristic_score > localParse.heuristic_score) {
                    gl.handleGlobal(globalParse);
                    listenResults.result.NLParse = globalParse.NLParse;
                    this.transitionTo(this.handleGlobalParseState, listenResults);
                }

                // Nothing parsed, emit to the locals.
                else {
                    this.emitNoGlobal(gl, willParseLaunch, localParse);
                }
            });
        };
    }
}
