    /**
     * Save a rule to disk.
     * @param uri {String} URI of rule to be saved.
     * @param filePath {String} filePath of fst to be saved to.
     * @param callback {Function} callback once rule has been saved.
     * @method module:skills-service-manager/services/listen-service/GlobalListen#saveRule
     */
    public saveRule(uri:string, filePath:string, callback:Callback) {
        // reload the rules from disk
        RuleManager.instance.saveToDisk(uri, filePath, callback);
    }

    /**
     * Reload launch and global rules from disk. Used in event of NLU crash.
     * @param callback {Function} callback once rules have been reloaded.
     * @method module:skills-service-manager/services/listen-service/GlobalListen#reloadRules
     */

    public reloadRules(callback:Callback) {
        if (this._nluStatus === NLU_STATUS.CONNECTED) {
            let tasks = [];
            let uris = {'launch': this._launchRulesUri, 'global': this._globalRuleUri};
            for (let type in uris) {
                let uri = uris[type];
                tasks.push((done) => {
                    let paths = this._rulePaths[uri];
                    if (paths) {
                        RuleManager.instance.getUriFromRulePaths(paths, done, {desiredUri: uri});
                    }
                    else {
                        done(`reloadRules: no ${type} rule to reload`);
                    }
                });
            }
            async.parallel(tasks, callback);
        }
        else {
            const error:Error = {
                'name': 'RELOAD_ERROR',
                'message': 'Could not reload rules: NLU Service is disconnected.'
            };
            callback(error);
        }
    }

