import Router = require('router');
import path = require('path');
// import fs = require('fs');
import WebSocket = require("ws-without-native");
import {
    ServiceOptions, HTTPWSService, JiboServerRequest, JiboServerResponse,
    RegistryClient, RegistrationRecord
} from 'jibo-service-framework';

import tcpProxy = require('tcp-proxy');
import {ProxyServer} from "tcp-proxy";
import {createServer} from 'jibo-sync';
import SkillsService from "../skills-service/SkillsService";
import {spawn, exec} from 'child_process';
import http = require('http');
import jibo = require('jibo');

import {createLog} from "../../utils/Log";
let log = createLog("ssm-dev-shell");

interface DevShellOptions extends ServiceOptions {
    debugPort:number;
    syncPort:number;
    skillDest:string;
    sdkDest:string;
}

// @TODO - when jibo.systemMangaer is ts-ifyd, move this interface there and export it.
interface OTARecord {
    id:string;
    subsystem:string;
    changes:string;
    length:number;
    toVersion:string;
    dependencies:any;
    downloaded:boolean;
}

export function createProxyServer(targetPort:number, debugPort:number):ProxyServer {
    let proxy:ProxyServer = tcpProxy.createServer({
        target: {
            host: "0.0.0.0",
            port: targetPort
        }
    });
    proxy.on('error', (error) =>{ log.info("Debug Proxy socket error: " + error); });
    proxy.on('close', () =>{ log.info("Debug Proxy socket closed"); });
    proxy.listen(debugPort, (error) => {
        if (error) {
            log.info('Error with Debug Proxy: ' + error);
        }
    });
    return proxy;
}

class DevShell extends HTTPWSService {

    private static _instance:DevShell;
    private _syncPort:number;
    private _skillDest:string;
    private _sdkDest:string;
    private _otaSocket:WebSocket;

    public static createInstance(options:DevShellOptions, rootDir:string):DevShell {
        return new DevShell(options, rootDir);
    }

    public static get instance():DevShell {
        return DevShell._instance;
    }

    constructor(options:DevShellOptions, rootDir:string) {
        super('dev-shell', options, rootDir);
        DevShell._instance = this;
        this._skillDest = options.skillDest;
        this._sdkDest = options.sdkDest;
        this._syncPort = options.syncPort;
        this._otaSocket = null;
        log.info("Initialized");
    }

    public init(callback:(err?:Error)=>void) {
        super.init((err:Error) => {
            this.server.timeout = 0; //disable timeouts for all devshell sockets
            callback(err);
        });
    }

    public routes(url:Router) {
        super.routes(url);
        url.post('/sync-skill', this._syncSkill.bind(this));
        url.post('/delete-skill', this._deleteSkill.bind(this));
        url.post('/run', this._startSkill.bind(this));
        url.post('/stop', this._stopSkill.bind(this));
        url.post('/diskspace', this._diskSpace.bind(this));
        url.post('/reboot', this._reboot.bind(this));
        url.post('/poweroff', this._poweroff.bind(this));
        url.post('/version', this._getVersion.bind(this));
        url.post('/index', this._index.bind(this));
        url.post('/setvolume', this._setVolume.bind(this));
        url.post('/getvolume', this._getVolume.bind(this));
        url.post('/check-update', this._checkForUpdates.bind(this));
        url.post('/download-update', this._downloadUpdates.bind(this));
        url.post('/install-update', this._installUpdates.bind(this));
    }

    public onConnection(client:WebSocket):void {
        super.onConnection(client);
        if(client.upgradeReq.url === '/download-update') {
            console.log("Opening OTA download socket");
            this._otaSocket = client;
        }
    }

    protected onClose(client:WebSocket):void {
        if(client === this._otaSocket) {
            console.log("Closing OTA download socket");
            this._otaSocket = undefined;
        }
    }

    protected onMessage(command: any, client: WebSocket): void {
        return;
    }

    private parseRequest(req:JiboServerRequest, res:JiboServerResponse, cb) {

        if (req.body) {
            cb(req.body);
            return;
        }

        let chunk = "";
        req.on('data', function (data) {
            chunk += (data);
        });

        req.on('end', function () {
            let data;
            try {
                data = JSON.parse(chunk);
            }
            catch(e) {
                this.sendJson(res, {
                    Status: 'ERROR',
                    Message: 'Invalid request. Request body is not valid JSON'
                }, 200);
                cb(null);
            }
            cb(data);
        });

        req.on('error', function(e) {
            this.sendJson(res, {
                Status: 'ERROR',
                Message: 'Error parsing dev shell request: ' + e.message
            }, 200);
            cb(null);
        });
    }

    private _syncSkill(request:JiboServerRequest, response:JiboServerResponse) {

        log.info("Syncing skill");

        this.parseRequest(request, response, (data) => {

            let name = data.dirName;
            let dest = this._skillDest + "/" + name;

            // start server for syncing...
            let verbose = true; // for now?
            createServer(this._syncPort, dest, verbose, (error) => {
                if (error) {
                    response.writeHead(200, {'Content-Type': 'text/plain'});
                    response.write(JSON.stringify({
                        Status: 'ERROR',
                        Message: error
                    }));
                    response.end();
                }
                else {
                    response.writeHead(200, {'Content-Type': 'text/plain'});
                    response.write(JSON.stringify({
                        Status: 'OK',
                        Message: 'Sync server started successfully'
                    }));
                    response.end();
                }
            });
        });
    }

    /**
     * Called from the jibo-cli to start a skill
     * @param request
     * @param response
     */
    private _startSkill(request:JiboServerRequest, response:JiboServerResponse) {
        this.parseRequest(request, response, (data) => {
            this.sendJson(response, {
                Status: 'ERROR',
                Message: data.command
            }, 200);
            let skillName:string = data.dirName;
            SkillsService.instance.launch(skillName, {}, (error:Error) => {
                if (error) {
                    this.sendJson(response, {
                        Status: 'ERROR',
                        Message: 'Error starting "' + skillName + '\n' + error.message
                    }, 200);
                }
                else {
                    this.sendJson(response, {
                        Status: 'OK',
                        Message: 'Skill "' + name + '" started successfully'
                    }, 200);
                }
            });
        });
    }

    private _stopSkill(request:JiboServerRequest, response:JiboServerResponse) {

        console.log("Stopping skill");

        SkillsService.instance.terminate((error:Error) => {
            if(error) {
                this.sendJson(response, {
                    Status: 'ERROR',
                    Message: 'Error stopping: ' + error
                }, 200);
            }
            else {
                this.sendJson(response, {
                    Status: 'OK',
                    Message: 'Stopped skill successfully.'
                }, 200);
            }
        });
    }


    private _deleteSkill(request:JiboServerRequest, response:JiboServerResponse) {
        log.info("Deleting skill");

        this.parseRequest(request, response, (data) => {

            let name = data.dirName;
            let dest = this._skillDest + "/" + name;
            let command = "rm -rf " + dest;

            exec(command, (err) => {
                if (err) {
                    this.sendJson(response, {
                        Status: 'ERROR',
                        Message: 'Error deleting: ' + err
                    }, 200);
                }
                else {
                    this.sendJson(response, {
                        Status: 'OK',
                        Message: 'Skill deleted successfully.'
                    }, 200);
                }
            });
        });
    }

    private _diskSpace(request:JiboServerRequest, response:JiboServerResponse) {

        log.info("Retrieving disk space");

        let command = path.join(this.rootDir, this._sdkDest + 'disk-space.sh');

        let proc = spawn('sh', [`${command}`, `${this._skillDest}`]);
        let data = "not found: " + command;
        proc.stdout.on('data', (_data) => {
            data = _data;
        });
        proc.on('exit', () => {
            this.sendJson(response, {
                Status: 'OK',
                Message: 'Diskspace Usage [' + this._skillDest + ']:\n\n' + data
            }, 200);

        });
    }

    private _reboot(request:JiboServerRequest, response:JiboServerResponse) {
        log.info("Rebooting");

        exec("reboot", (err) => {
            if(err){
                this.sendJson(response, {
                    Status: 'ERROR',
                    Message: 'Error trying to reboot: ' + err
                }, 200);
            }
            else {
                this.sendJson(response, {
                    Status: 'OK',
                    Message: 'Rebooting...'
                }, 200);
            }
        });
    }

    private _poweroff(request:JiboServerRequest, response:JiboServerResponse) {
        log.info("Powering off");

        exec("poweroff", (err) => {
            if(err){
                this.sendJson(response, {
                    Status: 'ERROR',
                    Message: 'Error trying to poweroff: ' + err
                }, 200);
            }
            else {
                this.sendJson(response, {
                    Status: 'OK',
                    Message: 'Powering off...'
                }, 200);
            }
        });
    }

    private _getVersion(request:JiboServerRequest, response:JiboServerResponse) {
        log.info("Retrieving version");

        let exiting:boolean = false;
        // for now, can do this via command; might be better to use system manager once we get that setup...or maybe not?
        let proc = spawn('jibo-version');

        let data = "Not found";
        proc.stdout.on('data', (_data) => {
            if (!exiting) {
                data = _data;
                this.sendJson(response, {
                    Status: 'OK',
                    Message: `${data}`
                }, 200);
            }

            exiting = true;
            proc.kill('SIGTERM');
            return;
        });

        proc.stderr.on('data', (_data) => {
            if (!exiting) {
                data = _data;
                this.sendJson(response, {
                    Status: 'ERROR',
                    Message: `${data}`
                }, 200);
            }

            exiting = true;
            proc.kill('SIGTERM');
            return;

        });
    }

    private _index(request:JiboServerRequest, response:JiboServerResponse) {

        log.info("Indexing");

        let bodyService:RegistrationRecord;
        RegistryClient.instance.getRecords((error: Error, records?: Array<RegistrationRecord>) => {
            for(let i:number = 0; i < records.length; i++) {
                let record:RegistrationRecord = records[i];
                if(record.name === 'body') {
                    bodyService = record;
                    break;
                }
            }
            if(!bodyService) {
                this.sendJson(response, {
                    "Status": 'ERROR',
                    "Message": 'Cannot find body service'
                }, 200);
                return;
            }

            let socketUrl:string = 'ws://' + bodyService.host + ':' + bodyService.port;

            // open axis_state socket
            let stateSocket:WebSocket = new WebSocket(socketUrl + "/axis_state");
            stateSocket.onerror = () => {
                this.sendJson(response, {
                    "Status": 'ERROR',
                    "Message": 'Error opening axis_state socket'
                }, 200);
            };

            let commandSocket:WebSocket = new WebSocket(socketUrl + "/axis_command");
            commandSocket.onopen = function() {
                console.log("Axis command socket open!");
            };
            commandSocket.onmessage = function(msg) {
                console.log("Got command message: " + msg.data);
            };
            commandSocket.onclose = function() {
                console.log("Axis command socket close!");
            };

            let latestAxisState:any = null;
            let timeout:number = 300;
            let stateOnMessage = (data) => {

                timeout--;
                latestAxisState = JSON.parse(data);
                let isIndexed:boolean = _isIndexed();

                if ((timeout < 0) || isIndexed) {

                    // Timed out or is already indexed
                    let temp = 'Robot is ' + (isIndexed ? '' : 'NOT ') + 'indexed.';
                    if (timeout < 0) {
                        temp = temp + ' (timed out)';
                    }

                    log.info(temp);

                    this.sendJson(response, {
                        "Status": (isIndexed ? 'OK' : 'ERROR'),
                        "Message": temp
                    }, 200);
                    stateSocket.removeListener('message', stateOnMessage);

                    commandSocket.close();
                    stateSocket.close();
                    return;
                }
                else {

                    // Send command for axis that are not indexed
                    //
                    if (commandSocket.readyState === WebSocket.OPEN) {
                        let pelvisOK = _isIndexed('pelvis');
                        let torsoOK = _isIndexed('torso');
                        let neckOK = _isIndexed('neck');

                        let cmd = _buildCmd(pelvisOK, torsoOK, neckOK);
                        commandSocket.send(cmd);
                    }
                }
            };

            stateSocket.on('message', stateOnMessage);

            //
            // helper methods
            //
            function _isIndexed(axis?:string) {
                if (axis === undefined) {
                    // check them all
                    return (latestAxisState !== null) &&
                        !!(latestAxisState.pelvis.status & 0x01) &&
                        !!(latestAxisState.torso.status & 0x01) &&
                        !!(latestAxisState.neck.status & 0x01);
                }
                else {
                    // check a specific axis
                    if(latestAxisState.hasOwnProperty(axis)) {
                        return !!(latestAxisState[axis].status & 0x01);
                    }
                    else {
                        return false;
                    }
                }
            }

            function _buildCmd(pelvisOK, torsoOK, neckOK) {
                if (latestAxisState === null) {
                    return undefined;
                }

                let vpelvis = {
                    mode : (pelvisOK ? 0 : 4),  // 4 = VEL
                    value : (pelvisOK ? [0] : [-1]),
                    vel_limit : latestAxisState.pelvis.vel_limit,
                    acc_limit : latestAxisState.pelvis.acc_limit,
                    cur_limit : latestAxisState.pelvis.cur_limit
                };
                let vtorso = {
                    mode : (torsoOK ? 0 : 4),  // 4 = VEL
                    value : (torsoOK ? [0] : [-1]),
                    vel_limit : latestAxisState.torso.vel_limit,
                    acc_limit : latestAxisState.torso.acc_limit,
                    cur_limit : latestAxisState.torso.cur_limit
                };
                let vneck = {
                    mode : (neckOK ? 0 : 4),  // 4 = VEL
                    value : (neckOK ? [0] : [-1]),
                    vel_limit : latestAxisState.neck.vel_limit,
                    acc_limit : latestAxisState.neck.acc_limit,
                    cur_limit : latestAxisState.neck.cur_limit
                };
                let data = {
                    ts : [latestAxisState.ts[0], latestAxisState.ts[1]],
                    pelvis : vpelvis,
                    torso : vtorso,
                    neck : vneck
                };
                return JSON.stringify(data);
            }
        });
    }

    private _getMixerSettings(url, cb) {

        let req = http.get(url, (res) => {

            let str = '';
            res.on('data', (chunk) => {
                str += chunk;
            });

            res.on('end', () => {
                let settings = undefined;
                try {
                    settings = JSON.parse(str);
                }
                catch (e) {
                    cb('Cannot retrieve mixer settings from ' + url, null);
                    return;
                }

                cb(null, settings);
            });
        });

        req.on('error', () => {
            cb('Cannot retrieve mixer settings from ' + url, null);
        });
    }

    private _getVolume(request:JiboServerRequest, response:JiboServerResponse) {
        log.info("Getting volume");

        this.parseRequest(request, response, () => {
            let audio:RegistrationRecord;
            RegistryClient.instance.getRecords((error: Error, records?: Array<RegistrationRecord>) => {
                for (let i:number = 0; i < records.length; i++) {
                    let record:RegistrationRecord = records[i];
                    if (record.name === 'audio') {
                        audio = record;
                        break;
                    }
                }
                if (!audio) {
                    this.sendJson(response, {
                        "Status": 'ERROR',
                        "Message": 'Cannot find audio service'
                    }, 200);
                    return;
                }

                let url = 'http://' + audio.host + ':' + audio.port + '/mixer';
                this._getMixerSettings(url, (error, settings) => {
                    if (error) {
                        this.sendJson(response, {
                            "Status": 'ERROR',
                            "Message": error
                        }, 200);
                    }
                    else {
                        let masterVol = settings.master.playbackVolume;

                        this.sendJson(response, {
                            Status: 'OK',
                            Message: masterVol.toFixed(2) + ' [0.0-1.0]'
                        }, 200);
                    }
                });
            });
        });
    }

    private _setVolume(request:JiboServerRequest, response:JiboServerResponse) {
        log.info("Setting volume");

        this.parseRequest(request, response, (data) => {

            let newVol = data.volume;

            let audio;
            RegistryClient.instance.getRecords((error: Error, records?: Array<RegistrationRecord>) => {
                for (let i:number = 0; i < records.length; i++) {
                    let record:RegistrationRecord = records[i];
                    if (record.name === 'audio') {
                        audio = record;
                        break;
                    }
                }
                if (!audio) {
                    this.sendJson(response, {
                        "Status": 'ERROR',
                        "Message": 'Cannot find audio service'
                    }, 200);
                    return;
                }

                // first get current mixer settings
                let url = 'http://' + audio.host + ':' + audio.port + '/mixer';
                this._getMixerSettings(url, (error, settings) => {
                    if (error) {
                        this.sendJson(response, {
                            "Status": 'ERROR',
                            "Message": error
                        }, 200);
                    }
                    else {
                        let options = {
                            hostname: audio.host,
                            port: audio.port,
                            path: '/mixer',
                            method: 'POST',
                            headers: {
                                'Content-Type': 'application/json'
                            }
                        };

                        let req = http.request(options, (res) => {
                            let str = '';
                            res.on('data', (chunk) => {
                                str += chunk;
                            });

                            res.on('end', () => {
                                this.sendJson(response, {
                                    Status: 'OK',
                                    Message: newVol.toFixed(2)
                                }, 200);
                            });

                        });

                        req.on('error', (e) => {
                            this.sendJson(response, {
                                "Status": 'ERROR',
                                "Message": 'Cannot set master volume (' + e + ')'
                            }, 200);
                        });

                        // update our new master volume and send entire mixer settings over
                        settings.master.playbackVolume = newVol;
                        req.write(JSON.stringify(settings));
                        req.end();
                    }
                });
            });
        });
    }

    /**
     * Called from the jibo-cli to check for OTA updates
     * @param request
     * @param response
     */
    private _checkForUpdates(request:JiboServerRequest, response:JiboServerResponse) {

        this.parseRequest(request, response, (data) => {
            log.info("Checking for updates");

            jibo.systemManager.checkForUpdates((error:any, data?:Array<OTARecord>) => {
                if (error || !data) {
                    this.sendJson(response, {
                        Status: 'ERROR',
                        Message: (error ? error : 'Service temporarily unavailable.')
                    }, 200);
                    return;
                }

                const count = data.length;
                let ids = '';
                for (let i = 0; i < count; i++) {
                    ids += '\n' + data[i].id + ': ' + data[i].changes;
                    if (data[i].downloaded) {
                        ids += ' [DOWNLOADED]';
                    }
                }
                let retVal = 'Found ' + count + ' update' + ((count > 1 || count === 0)? 's' : '') + ids;

                this.sendJson(response, {
                    Status: 'OK',
                    Message: {
                        msg: retVal,
                        data
                    }
                }, 200);

            },
            data.filter);
        });
    }


    /**
     * Called from the jibo-cli to download OTA updates
     * @param request
     * @param response
     */
    private _downloadUpdates(request:JiboServerRequest, response:JiboServerResponse) {

        this.parseRequest(request, response, (data) => {
            log.info("Downloading updates", data);

            jibo.systemManager.downloadUpdates(data, (err:any, dlData:any) => {

                //console.log("SSM DL UPDATE ", dlData);

                if (err || dlData.status === "failed") {
                    let reason = (err ? err : dlData.reason);
                    this.sendJson(response, {
                        Status: 'ERROR',
                        Message: 'Error downloading OTA updates: ' + reason
                    }, 200);
                }
                else {
                    // only send socket message if still downloading...
                    if (dlData.status === "downloading") {
                        if(this._otaSocket) {
                            this.sendWsJson(this._otaSocket, dlData);
                        }
                    }
                    else {
                        // otherwise send back response
                        this.sendJson(response, {
                            Status: 'OK',
                            Message: dlData
                        }, 200);
                    }
                }
            });

        });
    }

    /**
     * Called from the jibo-cli to install OTA updates
     * @param request
     * @param response
     */
    private _installUpdates(request:JiboServerRequest, response:JiboServerResponse) {

        this.parseRequest(request, response, (data) => {
            log.info("Installing updates", data);

            jibo.systemManager.installUpdates(data, (err:any) => {

                if (err) {
                    this.sendJson(response, {
                        Status: 'ERROR',
                        Message: 'Error installing OTA updates: ' + err
                    }, 200);
                }
                else {
                    // otherwise send back response
                    this.sendJson(response, {
                        Status: 'OK',
                        Message: 'Installing OTA updates! Robot will reboot a handful of times in between installations. Go get a snack.'
                    }, 200);
                }
            });
        });
    }
}

export default DevShell;