import { Event, EventContainer } from 'jibo-typed-events';
import {ParseResults, ListenResults, SpeakerId} from 'jibo-common-types';

/**
 * @class DialogListenerEvents
 * @description Typed Events for DialogListeners
 * @memberof services.ListenService
 */
export class DialogListenerEvents extends EventContainer {
  /**
   * Emit {@link services.ListenService.ListenResults} when cloud results are received.
   * @name services.ListenService.ClientDialogListener#cloudReceived
   * @type {Event}
   */
  cloudReceived = new Event<ListenResults>('Received Cloud results');
  /**
   * Emit event when an interrupt is requested.
   * @name services.ListenService.ClientDialogListener#interrupted
   * @type {Event}
   */
  interrupted = new Event<any>('Listen behavior interrupted');
  /**
   * Emit event when a listener is unsubscribed
   * @name services.ListenService.ClientDialogListener#unsubscribed
   * @type {Event}
   */
  unsubscribed = new Event<any>('Listener has been unsubscribed');
  /**
   * Emit {@link services.ListenService} when incremental results are received.
   * @name services.ListenService.ClientDialogListener#incremental
   * @type {Event}
   */
  incremental = new Event<ListenResults>('Incremental speech results');
  /**
   * Emit event when end of speech is detected.
   * @name services.ListenService.ClientDialogListener#eos
   * @type {Event}
   */
  eos = new Event<any>('End of Speech signal received');
  /**
   * Emit event when start of speech is detected.
   * @name services.ListenService.ClientDialogListener#sos
   * @type {Event}
   */
  sos = new Event<any>('Start of Speech signal received');
  /**
   * Emit {@link services.ListenService} when "Hey Jibo" is heard.
   * @name services.ListenService.ClientDialogListener#hj
   * @type {Event}
   */
  hjHeard = new Event<any>('Heard Hey Jibo');
  /**
   * Emit when Speaker is identified.
   * @name services.ListenService.ClientDialogListener#speakerId
   * @return {Event}
   */
  speakerId = new Event<any>('Got speaker Id results');
  hjOnly = new Event<ListenResults>('Heard Hey Jibo only');

  constructor() {
    super();
  }
}


/**
 * @class ListenEvents
 * @description Typed Events for ListenService
 * @memberof services.ListenService.GlobalListen
 */
export class ListenEvents extends EventContainer {
  /**
   * Received Cloud results.
   * @name services.ListenService.GlobalListen#cloudReceived
   * @type {Event}
   */
  cloudReceived = new Event<ListenResults>('Received Cloud results');
  /**
   * Received only a `hey jibo`
   * @name services.ListenService.GlobalListen#hjOnly
   * @type {Event}
   */
  hjOnly = new Event<ListenResults>('Heard only HJ');
  /**
   * SDK listener finished.
   * @name services.ListenService.GlobalListen#listenFinished
   * @type {Event}
   */
  listenFinished = new Event<any>('SDK listener finished');
  /**
   * Incremental speech results.
   * @name services.ListenService.GlobalListen#incremental
   * @type {Event}
   */
  incremental = new Event<ParseResults>('Incremental speech results');
  /**
   * Heard `hey jibo`.
   * @name services.ListenService.GlobalListen#hjHeard
   * @type {Event}
   */
  hjHeard = new Event<ListenResults>('Heard Hey Jibo');
  /**
   * Speaker was identified.
   * @name services.ListenService.GlobalListen#speakerId
   * @type {Event}
   */
  speakerId = new Event<SpeakerId>('Got speaker Id results');
  /**
   * End of Speech signal received.
   * @name services.ListenService.GlobalListen#eos
   * @type {Event}
   */
  eos = new Event<any>('End of Speech signal received');
  /**
   * Start of Speech signal received.
   * @name services.ListenService.GlobalListen#sos
   * @type {Event}
   */
  sos = new Event<any>('Start of Speech signal received');
  /**
   * Starting `hey jibo` listening
   * @name services.ListenService.GlobalListen#startHjListen
   * @type {Event}
   */
  startHjListen = new Event<any>('Starting HJ listening');
  /**
   * Parsed against global grammar and no result.
   * @name services.ListenService.GlobalListen#noGlobalMatch
   * @type {Event}
   */
  noGlobalMatch = new Event<ParseResults>('Parsed against global grammar and no result');
  /**
   * Starting a non `hey jibo` listen.
   * @name services.ListenService.GlobalListen#startNonHjListen
   * @type {Event}
   */
  startNonHjListen = new Event<any>('Starting a non Hey Jibo listen');
  /**
   * Launch grammar evoked for currently running skill
   * @name services.ListenService.GlobalListen#skillRelaunch
   * @type {Event}
   */
  skillRelaunch = new Event<any>('Parsed launch grammar from currently running skill');

  constructor() {
    super();
  }
}



export class SkillManagerEvents extends EventContainer {
  globalCommand = new Event<ListenResults>('Global Command detected');
  nonInterruptingGlobal = new Event<void>('Non-Interrupting Global Command Handled');
  skillLaunch = new Event<ListenResults>('Skill Launch Command detected');

  constructor() {
    super();
  }
}



export class InternalEvents extends EventContainer {
  enteringSuspend = new Event<any>('Entering suspended state');

  constructor() {
    super();
  }
}



export default class TypedEvents {
  listen = new ListenEvents();
  skillManager = new SkillManagerEvents();
  internal = new InternalEvents();
}