// set to false to bypass testing jibo server in verifyConnection
const testJiboServer = true;

// where do the custom static settings go for multiple APs?
const savedInterfacePath = '/var/etc/networks.conf';

// how long should we wait to get scan results
const scanResultsInterval = 1000;

// how often we do an active scan
const scanInterval = 15000;

// how often we do a wifi status check
const statusInterval = 1000;

//
// WifiManager handles switching connections, scanning and all the calls to wpa/systemManager
//
class WiFiManager {
    // @TODO - mark with '_' to denote private-ness
    public inProgress:boolean;
    private networkManager:NetworkManager;
    private statusHandler:StatusHandler;
    private activeScan:ActiveScan;
    private scanData:string;
    private tempNetworks;
    private lastState;
    private connecting;
    private connected;
    private _wifiService:WifiService;
    private syncedTime:boolean;
    private _jiboServerUrl:string;

    constructor(_wifiService){
        this.inProgress = false;
        this.networkManager = new NetworkManager();
        this.statusHandler = new StatusHandler();
        this.activeScan = new ActiveScan();
        this.tempNetworks = null;
        this.lastState = -1;
        this.scanData = null;
        this.connecting = 0;
        this.connected = 0;
        this._wifiService = _wifiService;
        this.syncedTime = false;
        this._jiboServerUrl = null;

        this._wifiService.on('scan_results_populated',(data)=>{this.updateSavedProfiles(data);});
    	this.scanListen(scanInterval);
        this.statusListen(2500); // @TODO - don't use hard-coded number
    }

    public init(cb:ErrorMsgCallback) {
        // get credential's region to use as jibo server url (doesn't work for oobe-config so will
        // use passed-in wifi options' region
        SystemManagerClient.instance.getCredentials((err, data) => {
            if(!err) {
                this._jiboServerUrl = data.region + ".jibo.com";
            }
            else {
                // get it from passed-in wifi options
                this._jiboServerUrl = this._wifiService.options.region + ".jibo.com";
            }

            this._wifiService.log.info("Jibo server url is " + this._jiboServerUrl);

            // don't pass up the credentials error to factory because we don't want SSM to fail
            // if no credentials!
            cb();
        });
    }


    public addNetwork(callback:WifiCallback){
 	    this.connecting = 1;
	    SystemManagerClient.instance.addNetwork(callback);
	}


    /*
        When a user adds a network, and it fails to connect(verified by: getCurrentNetwork)
    */
    public removeNetwork(networkId:string, ssid:string, callback:WifiCallback){
        SystemManagerClient.instance.removeNetwork(networkId, (err, data)=>{
            if(data){
		        this._removeInterfaceSetting(ssid, (err)=>{
		            if(err){
			            callback(err);
		            }
		            else{
                        SystemManagerClient.instance.saveConfig((err, data)=>{
                            if(data){
				                callback(null);
			                }
			                else{
				                callback(err);
			                }
			            });
		            }
		        });
	        }
	        else{
		        callback(err);
	        }
	    });
    }

    public disconnect(callback:WifiCallback) {
        SystemManagerClient.instance.disconnect((err, data)=> {
            if (err) {
                //    console.log(err);
                callback(err);
            }
            else {
                //  console.log("Disconnecting. After Authentication, Device went to SCANNING");
                callback(null, data);
            }
        });
    }

    /*
     gets scan results
     */
    // @TODO- make interval timer a global in this file so we don't have 2 running?
    public getScanResults(callback:WifiCallback) {
        let t = setInterval((err, data)=> {
            this.activeScan.scanResults((err, data)=> {

                if (err) {
                    clearInterval(t);
                    callback(err);
                }
                else {
                    if (data && (data.split('\n').length > 2)) {
                        clearInterval(t);
                        callback(null, data);
                    }
                }
            });
        }, scanResultsInterval);
    }


    /*
     returns signal, linkspeed, and ssid
     */
    public pollStats(callback:WifiCallback) {
        SystemManagerClient.instance.signalPoll(callback);
    }

    public scan(callback:WifiCallback) {
        this.activeScan.scan(callback);
    }

    /*
        Returns an array of saved network entries
     */
    public getSavedNetworks(cb:(error:Error, data?:Array<SavedNetworkEntry>) => void):void {
        this.networkManager.getNetworks((err:Error, data?:string)=> {
            if (err) {
                cb(err);
                return;
            }
            else {

                //data is a raw string of the saved profiles in wpa_supplicant
                let networkArray:Array<SavedNetworkEntry> = [];
                const networks = data.split('\n');
                for (let i = 0; i < networks.length; ++i) {
                    let data:Array<string> = networks[i].split('\t');

                    const _network = data[1];
                    if (_network) {
                        const _index = data[0];
                        const _current = (data[3] === '[CURRENT]');
                        networkArray.push({
                            index: _index,
                            ssid: _network,
                            current: _current
                        });
                    }
                }
                cb(null, networkArray);
            }
        });
    }

    /*
     networkID = string - key in wpa_cli list_networks
     networkData = NetworkData(can be null; only required on new networks)
     callback = required

     Checks conf file to see if static or not.
     if not, it will reset the config file to be dhcp - via systemManager
     if it is, it will adjsut the config file to be static - via systemManager
     Called from updateActiveNetworksDictionary
     */
    // @TODO - clean up callback hell; use async.series/waterfall where acceptable
    public selectNetwork(networkID:string, networkData:NetworkData, callback:WifiCallback) {
        //console.log("*** selectNetwork " + networkID + " ***");
        //Only occurs when managed through wifimanager
        if (!networkData) {
            this.getSavedNetworks((error:Error, networkData?:Array<SavedNetworkEntry>) => {
                if (error) {
                    return callback(error);
                }

                const networkLen = networkData.length;
                for (let idx = 0; idx < networkLen; idx++) {
                    if (networkData[idx].index === networkID) {

                        //console.log("selectNetwork: existing networks...");
                        //read from networks.conf to see if the network being searched for is static or dhcp
                        this._getInterfaceSettings(networkData[idx].ssid, (err, data:StaticNetworkSettings)=> {

                            //if not null, it's static
                            if (data) {
                                //console.log("selectNetwork: it is static...");
                                this._configureNetworkSettings(NetworkType.STATIC, data, (error) => {
                                    if (error) {
                                        // try to remove entry from saved settings
                                        this._removeInterfaceSetting(networkID, ()=> {
                                            return callback(error);
                                        });
                                    }
                                    else {
                                        //console.log(msg);
                                        this.adjustStatusPolling(networkID, (err)=> {
                                            if (err) {
                                                return callback(err);
                                            }
                                            else {
                                                return callback(null, "success");
                                            }
                                        });
                                    }
                                });
                            }
                            else {
                                // console.log("selectNetwork: it is dhcp...");
                                this._configureNetworkSettings(NetworkType.DHCP, null, (error, msg) => {
                                    if (error) {
                                        return callback(error);
                                    }
                                    else {
                                        // console.log(msg);
                                        this.adjustStatusPolling(networkID, (err)=> {
                                            if (err) {
                                                return callback(err);
                                            }
                                            else {
                                                return callback(null, "success");
                                            }
                                        });
                                    }
                                });
                            }
                        });

                        break;
                    }
                }
            });
        }
        //only occurs when user adds a network
        else {
            //console.log("...we have networkData!", networkData);
            //this.logToSupplicant(networkData,(err:string,data?:string)=>{
            //systemManager will look up the conf in the configureNetworkSettings call
            this._saveInterfaceSettings(networkData, (err:Error)=> {
                if (err) {
                    console.log("Save Interface Settings Failure");
                    callback(err, null);
                }
                else {
                    if (networkData.networkType === NetworkType.DHCP) {
                        this._configureNetworkSettings(NetworkType.DHCP, null, (error, msg) => {
                            if (error) {
                                console.log("DHCP Failure Settings!");
                                callback(error);
                            }
                            else {
                                // console.log(msg);
                                this.adjustStatusPolling(networkID, (err:Error)=> {
                                    if (err) {
                                        callback(err);
                                    }
                                    else {
                                        callback(null, "success");
                                    }
                                });
                            }
                        });
                    }
                    else if (networkData.networkType === NetworkType.STATIC) {
                        console.log("Setting network as a static network!");
                        this.getSavedNetworks((error:Error, data?:Array<SavedNetworkEntry>) => {
                            if (error) {
                                return callback(error);
                            }

                            //check to make sure network exists in the saved networks
                            let foundNetwork = false;
                            const networkLen = data.length;
                            for (let idx = 0; idx < networkLen; idx++) {
                                if (data[idx].ssid === networkData.ssid) {
                                    foundNetwork = true;
                                    break;
                                }
                            }

                            if (foundNetwork) {
                                this._configureNetworkSettings(NetworkType.STATIC, networkData.staticSettings, (error: Error, msg) => {
                                    if (error) {
                                        // try to remove entry from saved settings
                                        this._removeInterfaceSetting(networkData.ssid, ()=> {
                                            callback(error);
                                        });
                                    }
                                    else {
                                        // console.log(msg);
                                        //selects the network
                                        this.adjustStatusPolling(networkID, (err: Error, data)=> {
                                            if (err) {
                                                callback(err);
                                            }
                                            else {
                                                callback(null, "success");
                                            }
                                        });
                                    }
                                });
                            }
                            else {
                                callback(new Error("Could not select network " + networkData.ssid));
                            }
                        });
                    }
                }
            });
        }
    }


    /*
     Confirms that jibo is actually connected
     Checks that Jibo is connected to AP
     then checks that Jibo has an IP Address
     then checks that Jibo can talk to the internet
     then checks that Jibo can talk to the jibo server

     Emits specific error code associated to any of these failing.
     */
    // @TODO - use async.series
    public verifyConnection(callback:ErrorCodeCallback) {
        this.status((err, data)=> {
            if (err) {
                callback(new ErrorCode(666, "BAD THINGS ARE HAPPENING: " + err));
                return;
            }

            //Check if Jibo detects connection to AP
            if (data.indexOf('COMPLETED') > -1) {
                console.log("VerifyConnection #1 (AP): OK");

                //Check if it has an IP Address
                this.status((err, data) => {
                    //IP address is present
                    if (data && data.indexOf('ip_address=') > -1) {
                        console.log("VerifyConnection #2 (IP): OK");

                        if (testJiboServer) {
                            this._checkJiboServers((err)=> {
                                let status = (err ? err : 'OK');
                                console.log("VerifyConnection #3 (Jibo Servers): " + status);

                                if (err) {
                                    callback(new ErrorCode(4, "Cannot Ping Jibo Servers"));
                                }
                                else {
                                    callback();
                                }
                            });
                        }
                        else {
                            callback();
                        }
                    }
                    else {
                        callback(new ErrorCode(2, "Could Not Obtain IP Address"));
                    }
                });
            }
            else {
                callback(new ErrorCode(1, "Did not connect to the Access Point"));
            }
        });
    }

    public setNetwork(networkId, options:SetNetworkOptions, callback:WifiCallback) {
        let cmd:string;
        if(options.ssid){
            cmd = networkId + " ssid " + '\"' + options.ssid + '\"' ;
        }
        else if(options.hidden){
            cmd = networkId + " scan_ssid 1";
        }
        else if(options.psk){
            //psk will be null on Open
            cmd = networkId + " psk " + '\"' + options.psk + '\"' ;
        }
        else if(options.security){
            switch(options.security){
                case('WPA-PSK'):
                    cmd = networkId + " key_mgmt WPA-PSK";
                    break;
                case('WPA2-PSK'):
                    cmd = networkId + " key_mgmt WPA-PSK";
                    break;
                case('OPEN'):
                    cmd = networkId + " key_mgmt NONE";
                    break;
            }
        }

        SystemManagerClient.instance.setNetwork(cmd, callback);
    }

    public status(callback:WifiCallback) {
        this.statusHandler.status(callback);
    }

    public statusListen(interval) {
        this.statusHandler.listen(interval, this.statusCB.bind(this));
    }

    public scanListen(interval) {
        this.activeScan.listen(interval, this.scanCB.bind(this));
    }

    /*
     public method to get scan results
     */
    public networkProfiles(callback:WifiCallback) {
        this.networkManager.getContainer(callback);
    }

    public saveNetwork(networkID, callback:WifiCallback) {
        SystemManagerClient.instance.saveConfig((err, data)=> {
            if (err) {
                callback(err);
            }
            else {
                //console.log("Successfully saved network");
                callback(null, data);
            }
        });
    }

    /*
     Increase status listen frequency until:
     connected or failure to connect.
     Allows very precise state listening to determine exact failure
     point(ie: Exchange, DHCP, etc)
     */

    private adjustStatusPolling(networkID, cb) {
        this.connecting = 1;
        this.statusListen(statusInterval);
        SystemManagerClient.instance.selectNetwork(networkID, (err:Error)=> {
            if (err) {
                //console.log("Err selecting network!");
                cb(err);
            }
            else {
                SystemManagerClient.instance.enableNetwork(networkID, (err:Error)=> {
                    if (err) {
                        // console.log("Error Enabling Network Detected " + err);
                        cb(err, null);
                    }
                    else {
                        //  console.log("Successfully enabled network");

                        cb(null);
                    }
                });
            }
        });
    }


    private scanCB(err, data) {
        if (err) {
            console.log("Error Detected: " + err);
            return;
        }
        else {
            this.activeScan.scanResults(this.scanResultsCB.bind(this));
        }
    }

    //When saved network profiles are requested
    private networkCB(err, networks) {
        if (err) {
            console.log("Error Detected: " + err);
            return;
        }
        else {
            //console.log("Updating Saved Profiles");

            //first two lines are just headers
            if (networks.split('\n').length > 2) {
                //Passes raw networks data and networkManager populates it into a NetworkContainer
                this.networkManager.updateProfiles(networks, this.updateActiveNetworksDictionary.bind(this));
            }
            else {
                return;
            }
        }
    }


    /*
     Lets WiFiManager know scan results are populated
     data = raw data of scan results
     */
    private updateSavedProfiles(data) {
        this.scanData = data;
        this.networkManager.getNetworks(this.networkCB.bind(this));
    }


    /*
     This is called everytime ScanResults is populated via networkCB
     */
    private updateActiveNetworksDictionary(networkContainer:NetworkContainer) {
        if (this.scanData) {
            networkContainer.updateWiFiProfiles(this.scanData, ()=> {
                networkContainer.getBestNetwork((bestNetwork:NetworkProfile)=> {

                    //console.log("Selecting Network " + bestNetwork.networkID);
                    if (bestNetwork.rssi) {
                        this.selectNetwork(bestNetwork.networkID, null, (err:Error, data:string)=> {
                            bestNetwork.tried = true;
                        });
                    }
                });
            });
        }
    }

    // @TODO - could add method to InterfaceData
    private _isInterfaceEqual(lhs:InterfaceData, rhs:InterfaceData):boolean {

        return (lhs.method === rhs.method) &&
            (lhs.address === rhs.address) &&
            (lhs.network === rhs.network) &&
            (lhs.netmask === rhs.netmask) &&
            (lhs.broadcast === rhs.broadcast) &&
            (lhs.gateway === rhs.gateway) &&
            (lhs.dns === rhs.dns);

    }

    private _getDNSString(staticSettings:StaticNetworkSettings):string {
        let dnsStr:string = "";

        if (staticSettings) {
            if (staticSettings.dns1) {
                dnsStr += staticSettings.dns1;
            }
            if (staticSettings.dns2) {
                if (staticSettings.dns1) {
                    dnsStr += " "; // add space in between
                }
                dnsStr += staticSettings.dns2;
            }
        }
        return dnsStr;
    }

    private _configureNetworkSettings(type:NetworkType, settings:StaticNetworkSettings, cb:WifiCallback) {
        let typeStr = (type === NetworkType.DHCP ? "dhcp" : "static");

        SystemManagerClient.instance.getInterface((error, currentInterface:InterfaceData) => {

            // check if we need to change interface
            let newInterface:InterfaceData = {
                method: typeStr,
                address: (settings ? settings.staticIP : ""),
                network: "",
                netmask: (settings ? settings.netmask : ""),
                broadcast: "",
                gateway: (settings ? settings.gateway : ""),
                dns: this._getDNSString(settings)
            };

            if (!this._isInterfaceEqual(currentInterface, newInterface)) {

                this._setInterface(typeStr, settings, (error, msg) => {
                    if (error) {
                        console.log("setInterface error; reverting to dhcp");
                        this._setInterface("dhcp", null, () => {
                            cb(error); // use the previous error from failed set interfaces
                        });

                    }
                    else {
                        cb(null, "Network settings updated. [" + msg + "]");

                    }
                });
            }
            else {
                cb(null, "Network settings are the same. Do not need to update.");
            }
        });
    }

    private _setInterface(_type:string, staticSettings:StaticNetworkSettings, callback:WifiCallback) {

        let dnsStr:string = this._getDNSString(staticSettings);

        let interfaceData:InterfaceData = {
                method: _type,
                address: (staticSettings ? staticSettings.staticIP : ""),
                network: "",
                netmask: (staticSettings ? staticSettings.netmask : ""),
                broadcast: "",
                gateway: (staticSettings ? staticSettings.gateway : ""),
                dns: dnsStr
        };

        SystemManagerClient.instance.setInterface(interfaceData, callback);
    }

    // save interface settings
    private _saveInterfaceSettings(networkData:NetworkData, cb:ErrorMsgCallback) {

        if (networkData.staticSettings && networkData.staticSettings.staticIP) {

            //   console.log("Saving interface settings to /var/etc/networks.conf for " + networkData.ssid);

            let data = {};
            if (fs.existsSync(savedInterfacePath)) {
                // read in old one first
                try {
                    data = JSON.parse(fs.readFileSync(savedInterfacePath, 'utf8'));
                }
                catch (e) {
                    cb(e);
                    return;
                }
            }

            // set data
            data[networkData.ssid] = {
                staticIP: networkData.staticSettings.staticIP,
                gateway: networkData.staticSettings.gateway,
                netmask: networkData.staticSettings.netmask,
                dns1: networkData.staticSettings.dns1,
                dns2: networkData.staticSettings.dns2
            };

            // write file
            try {
                fs.writeFile(savedInterfacePath, JSON.stringify(data), 'utf8', (err:string) => {
                    if (err) {
                        cb(new Error(err));
                    }
                    else {
                        cb(); // YAY! success!!
                    }
                });
            } catch (e) {
                cb(new Error(e));
            }
        }
        else {
            cb(); // dhcp
        }
    }

    // get a specific interface setting if exists
    private _getInterfaceSettings(ssid:string, cb:InterfaceSettingsCallback) {
        fs.readFile(savedInterfacePath, 'utf8', (err, strData)=> {
            //no reason for file to exist yet - all networks have been dhcp?
            if (err) {
                cb();
            }

            try {
                // Load file
                let data = JSON.parse(strData);
                if (data.hasOwnProperty(ssid)) {
                    cb(null, data[ssid]);  // found entry so return it
                }
                else {
                    cb();   // entry doesn't exist
                }
            }
            catch (e) {
                cb(e);
            }
        });
    }


    // remove interface settings
    private _removeInterfaceSetting(ssid:string, cb:ErrorMsgCallback) {
        fs.readFile(savedInterfacePath, 'utf8', (err, strData)=> {
            //no reason for file to exist yet - all networks have been dhcp?
            if (err) {
                cb();
                return;
            }

            try {
                // Load file
                let data = JSON.parse(strData);
                if (data.hasOwnProperty(ssid)) {
                    // found entry so delete it and write it back
                    delete data[ssid];

                    fs.writeFile(savedInterfacePath, JSON.stringify(data), 'utf8', (err:string) => {
                        if (err) {
                            cb(new Error(err));
                        }
                        else {
                            cb();
                        }
                    });
                }
                else {
                    cb();   // entry doesn't exist so that's ok
                }
            }
            catch (e) {
                cb(new Error(e));
            }
        });
    }

    // @TODO - set global timer variable so we don't do 2 at once?
    private scanResultsCB(err, data) {
        let t = setInterval((err, data)=> {
            this.activeScan.scanResults((err, data)=> {
                if (err) {
                    clearInterval(t);
                    return;
                }
                else {
                    if (data && (data.split('\n').length > 2)) {
                        if (this.connecting === 0 && this.connected === 0 && !this.inProgress) {
                            this._wifiService.sendSocketData('scan_results_populated', data);
                        }
                        clearInterval(t);
                        return;
                    }
                }
            });
        }, scanResultsInterval);
    }


    /*
     Called everytime the state is polled(default is every two seconds).
     */
    // @TODO - clean up this method (big-ass switch); make an enums for states
    private stateCB(currentState) {
        /*
         currentState == 0: SCANNING
         currentState == 1: AUTHENTICATING
         currentState == 2: 4WAY_HANDSHAKE
         currentState == 3: CONNECTED
         currentState == 4: DISCONNECTED
         */

        let _states = {
            '-1': "INIT",
            0: "SCANNING",
            1: "AUTHENTICATING",
            2: "4WAY_HANDSHAKE",
            3: "CONNECTED",
            4: "DISCONNECTED"
        };

        let verifyTime = 15000;

        if (currentState === 3) {
            this.connected = 1;
            this.activeScan.stopListener();
        }
        else {
            this.connected = 0;
        }
        if (currentState !== 1 && currentState !== 2) {
            this.resetStatus();
        }

        switch (currentState) {
            //Don't foresee when this specific case(-1) will ever happen, but we should catch it in case
            case -1: //JUST BOOTED
                switch (this.lastState) {
                    case 0: //Jibo went from being SCANNING -> turned on
                        this.resetStatus();
                        break;

                    case 1: //Jibo went from being AUTHENTICATING -> turned on
                        this.resetStatus();
                        break;

                    case 3: //Jibo went from being CONNECTED -> turned on
                        this.resetStatus();
                        break;

                    case 4: //Jibo went from being DISCONNECTED -> turned on
                        this.resetStatus();
                        break;
                }
                break;

            case 0: //SCANNING
                switch (this.lastState) {
                    case -1: //Jibo went from being turned on -> SCANNING
                        this.resetStatus();
                        break;

                    case 0: //Jibo is still scanning
                        this.resetStatus();
                        break;

                    case 1: //Jibo went from AUTHENTICATING -> SCANNING
                        if (!this.inProgress) {
                            setTimeout(()=> {
                                this.verifyConnection((err?:ErrorCode)=> {
                                    if (err) {
                                        this._wifiService.sendError(err);
                                        this.resetStatus();
                                    }
                                    else {
                                        this.resetStatus();
                                    }
                                });
                            }, verifyTime);
                            break;
                        }

                    case 2: //Jibo went from 4WAY_HANDSHAKE -> SCANNING
                        if (!this.inProgress) {
                            setTimeout(()=> {
                                this.verifyConnection((err?:ErrorCode)=> {
                                    if (err) {
                                        this._wifiService.sendError(err);
                                        this.resetStatus();
                                    }
                                    else {
                                        this.resetStatus();
                                    }
                                });
                            }, verifyTime);
                            break;
                        }

                    case 3: //Jibo went from CONNECTED -> SCANNING
                        this.resetStatus();
                        break;
                }
                break;

            case 1: //AUTHENTICATING
                switch (this.lastState) {
                    case 1: //Jibo is AUTHENTICATING
                        break;

                    case 2: //Jibo went from 4WAY_HANDSHAKE -> AUTHENTICATING
                        break;

                    case 3: //Jibo went from CONNECTED -> AUTHENTICATING
                        /*
                         I don't see any reason for this to ever happen
                         */
                        break;

                    case 4: //Jibo went from DISCONNECTED -> AUTHENTICATING
                        /*
                         I don't see any reason for this to ever happen
                         */
                        break;
                }
                break;

            case 2: //4WAY_HAND_SHAKE
                switch (this.lastState) {
                    case 1:  //jibo went from AUTHENTICATING -> 4WAY_HANDSHAKE
                        break;
                    case 2: //jibo is still in 4WAY_HANDSHAKE
                        break;
                    case 3: //jibo went from COMPLETED -> 4WAY_HANDSHAKE
                        //Don't see any reason this would happen
                        break;
                    case 4: //jibo went from DISCONNECTED -> 4WAY_HANDSAHEK
                        break;
                }
                break;

            case 3: //CONNECTED
                switch (this.lastState) {
                    case 0: //Jibo went from SCANNING -> CONNECTED
                        this.resetStatus();
                        break;
                    case 1: //Jibo went from AUTHENTICATING -> CONNECTED
                        this.resetStatus();
                        break;
                    case 2: //Jibo went from 4WAY_HANDSHAKE -> CONNECTED
                        this.resetStatus();
                        break;
                    case 3: //Jibo is still connected
                        break;
                    case 4: //Jibo went from DISCONNECTED -> CONNECTED
                        //Means everything was missed, but possible
                        this.resetStatus();
                        break;
                }
                break;

            case 4: //DISCONNECTED
                switch (this.lastState) {
                    case 0: //Jibo went from SCANNING -> DISCONNECTED
                        this.resetStatus();
                        break;
                    case 1: //Jibo went from AUTHENTICATING -> DISCONNECTED
                        if (!this.inProgress) {
                            setTimeout(()=> {
                                this.verifyConnection((err?:ErrorCode)=> {
                                    if (err) {
                                        this._wifiService.sendError(err);
                                        this.resetStatus();
                                    }
                                    else {
                                        this.resetStatus();
                                    }
                                });
                            }, verifyTime);
                            break;
                        }

                    case 2: //Jibo went from 4WAY_HANDSHAKE -> DISCONNECTED
                        /*
                         lastState == 1: jibo was attempting to connect, but failed during 4way_handshake. Likely Wrong PSK.
                         */
                        if (!this.inProgress) {
                            setTimeout(()=> {
                                this.verifyConnection((err?:ErrorCode)=> {
                                    if (err) {
                                        this._wifiService.sendError(err);
                                        this.resetStatus();
                                    }
                                    else {
                                        this.resetStatus();
                                    }
                                });
                            }, verifyTime);
                            break;
                        }
                        break;
                    case 3: //Jibo went from CONNECTED -> DISCONNECTED
                        this.connected = 0;
                        this.inProgress = false;
                        this.connecting = 0;
                        this.resetStatus();
                        break;
                }
                break;
        }

        if (this.lastState !== currentState) {
            // emit state change please
            let data:any = {
                newState: _states[currentState],
                oldState: _states[this.lastState]
            };
            this._wifiService.sendSocketData("state-change", data);
            this._wifiService.emit("state-change", data);
            this._wifiService.log.info("state-change:", data);

            if(data.oldState === "CONNECTED") {
                ErrorService.instance.addError("Q1-Lost_Wi-Fi_connection");
            } else if(data.newState === "CONNECTED") {
                ErrorService.instance.removeError("Q1-Lost_Wi-Fi_connection");
            }
        }

        //Check connection status - inProgress will make sure wifiManager doesn't handle API features
        if (currentState === 3 && this.lastState !== 3 && !this.inProgress) {
            setTimeout(()=> {
                this.verifyConnection((err?:ErrorCode)=> {
                    if (err) {
                        this._wifiService.sendError(err);
                        this.resetStatus();
                    }
                    else {
                        this.resetStatus();
                    }
                });
            }, verifyTime);
        }

        this.lastState = currentState;

        if (this.lastState === 3) {
            this.resetStatus();
        }
    }

    // @TODO - make these consts :( Also, probably fine to call this in ctor?
    private resetStatus() {
        /*
         When a user attempts to add a network or we try to connect to a network,
         after the connection process is complete(connected properly or failed)
         */
        if (this.connected === 1) {
            this.connecting = 0;
            this.statusListen(15000);
            this.activeScan.stopListener();
        }

        else if (this.connecting === 1) {
            this.connecting = 0;
            this.statusListen(1000);
            this.scanListen(20000);
        }
        else {
            this.statusListen(5000);
            this.scanListen(15000);
        }

    }

    //When the status is polled.
    private statusCB(err:Error, data:any) {
        if (err) {
            console.log("Error Detected: " + err);
            return;
        }

        let tempState = 0;
        //No connection currently
        if (data.indexOf("SCANNING") > -1) {
            tempState = 0;
        }
        else if (data.indexOf("AUTHENTICATING") > -1) {
            tempState = 1;
        }
        else if (data.indexOf("4WAY_HANDSHAKE") > -1) {
            tempState = 2;
        }
        else if (data.indexOf("COMPLETED") > -1) {
            tempState = 3;
        }
        else if (data.indexOf("DISCONNECTED") > -1) {
            tempState = 4;
        }
        this.stateCB(tempState);
    }

    private _checkJiboServers(cb) {
        if(!this._jiboServerUrl) {
            cb("Do not have a jibo server url to check!");
            return;
        }

        let options = {
            host: this._jiboServerUrl,
            path: '/'
        };

        // Set up the request
        let req = https.get(options, (res) => {
            let temp = '';
            res.on('data', function (chunk) {
                temp += chunk;
            }).on('error', function (e) {
                cb(e.message);
            }).on('end', function () {
                cb();
            });
        });

        req.on('error', (e) => {
            // grr...typescript doesn't like socket property...and i don't know how to use custom typings so
            // just going to attempt to sync time if we haven't already...
            //if(req.socket && req.socket.authorized === false && req.socket.authorizationError === 'CERT_NOT_YET_VALID') {
            //}

            // make sure our time is synchronized
            if(!this.syncedTime) {
                console.log("Attempting to sync time...");
                SystemManagerClient.instance.syncTime((error) => {
                    if (!error) {
                        this.syncedTime = true;
                    }
                    cb(e);
                });
            }
            else {
                cb(e);
            }
        });

        req.on('socket', function (socket) {
            socket.setTimeout(15000);
            socket.on('timeout', function () {
                req.abort();
            });
        });
    }
}

