import BodyClient from '../../clients/BodyClient';
import BackgroundUtilsManager from '../../utils/BackgroundUtilsManager';

let timeoutId;
const timeToBlank:number = 1000 * 5 * 60;

class ScreenScheduler {

    public static start() {
        clearTimeout(timeoutId);
        timeoutId = setTimeout(() => {
            BodyClient.instance.setScreen('off');
            ScreenScheduler.headTouchOn();
        }, timeToBlank);
    }


    public static async stopTimerAndTurnOn() {
        clearTimeout(timeoutId);
        ScreenScheduler.headTouchOff();
        await BodyClient.instance.setScreen('on');
    }

    private static headTouchOn() {
        BodyClient.instance.once('touched', ScreenScheduler.onHeadTouched);
    }

    private static headTouchOff() {
        BodyClient.instance.removeListener('touched', ScreenScheduler.onHeadTouched);
    }

    private static async onHeadTouched():Promise<void> {
        await BodyClient.instance.setScreen('on');
        ScreenScheduler.headTouchOff();
        ScreenScheduler.start();
    }
}
export default ScreenScheduler;

BackgroundUtilsManager.register((mode:string) => {
    //if we're in developer mode
    if(mode && mode.indexOf('developer') >= 0) {
        ScreenScheduler.start();
    }
}, 'screen');