import * as uuid from 'uuid';
import ASRVariables from './ASRVariables';
import {EventEmitter} from 'events';
import {ASRRequestOptions} from "jibo-common-types";
/**
 * All speech actions are coodinated by this class. Create a new instance through the
 * asr module.
 * Coordinates action state as recognized through incoming messages to the ASR Service.
 * Since messages to the ASR Service MUST be received in certain orders, this class
 * maintains state about which message has been received -- the ASR Service always sends
 * back a "received" message with respect to a particular action ID.
 * @class AudioAction
 * @extends EventEmitter
 * @memberof module:jibo.services.asr
 * @private
 */

export interface ASRRequest {
    audio_source_id?: string;
    bargein?: string;
    command: string;
    expected_duration?: string;
    hasMadeFirstResponse?: boolean;
    heardHotphrase?: boolean;
    hotphrase?: string;
    isActive?: boolean;
    incremental?: boolean;
    known_speaker_id?: string;
    meta?: any;
    nbest?: number;
    request_id: string;
    speaker_id?: string;
    speech_to_text?: boolean;
    language?: string;
    task_id: string;
}


export enum ActionStatus {
    NOT_STARTED = <any> "NOT_STARTED",
    STARTING = <any> "STARTING",
    STARTED = <any> "STARTED",
    STOPPING = <any> "STOPPING",
    STOPPED =<any> "STOPPED",
    CLEARING = <any> "CLEARING",
    CLEARED = <any> "CLEARED"    
}

/**
 * @class AudioAction
 * @description Action Management for starting/stopping through ASR Service
 * @param {string} url interface through which to talk to ASR Service
 * @param {string} [id] ID of audio action to send to ASR Service.
 * @memberof module:skills-service-manager/clients/asr
 */
class AudioAction extends EventEmitter {
    public id:string;
    public status: ActionStatus;
    /**
     * Whether or not AudioAction should log events to console.
     * @name module:module:skills-service-manager/clients/asr.AudioAction#shouldLog
     * @type {Boolean}
     */
    public shouldLog: boolean = false;
    /**
     * Interface through which to talk to ASR Service
     * @name module:module:skills-service-manager/clients/asr.AudioAction#httpInterface
     * @type {String}
     * @private
     */
    private httpInterface: string;
    /**
     * ID of audio source to listen through
     * @name module:module:skills-service-manager/clients/asr.AudioAction#audioSourceId
     * @type {String}
     * @private
     */
    private audioSourceId: string;
    /**
     * Callbacks subscribed waiting for action to start
     * @name module:module:skills-service-manager/clients/asr.AudioAction#startCallbacks
     * @type {Array<Funcion>}
     * @private
     */
    private startCallbacks: Array<Function>;
    /**
     * Callbacks subscribed waiting for action to stop
     * @name module:module:skills-service-manager/clients/asr.AudioAction#stopCallbacks
     * @type {Array<Funcion>}
     * @private
     */
    private stopCallbacks: Array<Function>;
    /**
     * Callbacks subscribed waiting for action to stop
     * @name module:module:skills-service-manager/clients/asr.AudioAction#stopCallbacks
     * @type {Array<Funcion>}
     * @private
     */
    private clearCallbacks: Array<Function>;    

    constructor(url, id?) {
        super();
        this.httpInterface = url;
        this.id = id || 'action-' + uuid.v4();
        ASRVariables.idToAction[this.id] = this;
        this.status = ActionStatus.NOT_STARTED;
        this.startCallbacks = [];
        this.stopCallbacks = [];
        this.clearCallbacks = [];
    }

    setAudioSourceId(id) {
        this.audioSourceId = id;
    }

    setId(id:string) {
        this.id = id;
    }

    getId() {
        return this.id;
    }

    /**
     * Starts this audio action.
     * ```
     * var asr = require('jibo').asr;
     * var action = asr.createAudioAction();
     * var task = {
     *      hotphrase: true,
     *      incremental: false
     * }
     * action.startAudioTask(task);
     * ```
     * @function AudioAction#start
     * @param {String} task The ASRRequestOptions representation of the task. This is built by concatonating Recognizers.
     */
    startAudioTask(task:ASRRequestOptions, cb?:Function) {
        this._log({"someone wants to start ": this.id});
        this.startCallbacks.push(cb);
        if(this.status === ActionStatus.STARTING) {
            return;
        }
        else if(this.status === ActionStatus.STARTED) {
            this._callIfExists(cb);
            return;
        }
        this.status = ActionStatus.STARTING;
        let body:ASRRequest = {
            audio_source_id: this.audioSourceId,
            bargein: task.bargein,
            command: 'start',
            expected_duration: task.expectedDuration,
            hotphrase: task.hotphrase,
            incremental: task.incremental,
            language: task.language,
            meta: task.metadata,
            nbest: task.nbest,
            request_id: this.id,
            speaker_id: task.known_speaker_id,
            speech_to_text: task.speech_to_text,
            task_id: this.id
        };
        let bodyString:string = JSON.stringify(body);
        this.once('acknowledgement', () => {
            // ASR Service has recognized our action.
            this._log({"OFFICIALLY STARTED ": this.id});
            this.status = ActionStatus.STARTED;
            this.startCallbacks.forEach((callback) => {
                this._callIfExists(callback);
            });
            this.startCallbacks = [];
            ASRVariables.numberActiveActions++;
            this._log({"Number of active Actions": ASRVariables.numberActiveActions});
        });
        this._log({"starting ": this.id, "task:": body});
        let request = new XMLHttpRequest();
        request.open("POST", this.httpInterface, true);
        request.send(bodyString);
    }

    startOldTask(task, cb?:Function) {
        this.startCallbacks.push(cb);
        if(typeof task !== "string") {
            task = JSON.stringify(task);
        }
        if(this.status === ActionStatus.STARTING) {
            return;
        }
        else if(this.status === ActionStatus.STARTED) {
            this._callIfExists(cb);
            return;
        }
        this.status = ActionStatus.STARTING;
        let body:any = {
            action: 'init_and_start',
            audio_source_id: this.audioSourceId,
            // TODO: implement requestIdToAction
            request_id: this.id,
            task: task,
            task_id: this.id
        };
        body = JSON.stringify(body);
        this.once('received', () => {
            this.status = ActionStatus.STARTED;
            this.startCallbacks.forEach((callback) => {
                this._callIfExists(callback);
            });
            ASRVariables.numberActiveActions++;
            this.startCallbacks = [];
        });
        let request = new XMLHttpRequest();
        request.open("POST", this.httpInterface, true);
        request.send(body);
        this._log({"Number of active Actions": ASRVariables.numberActiveActions});
        return;
    }

    /**
     * Stops the current action and shuts down all recognizers.
     * @function AudioAction#stop
     */
    stop(cb?) {
        this._log({"someone wants to stop ": this.id});
        // TODO: MODULARIZE THIS SECTION
        if(this.status === ActionStatus.STOPPING) {
            return;
        }
        else if(this.status === ActionStatus.STOPPED) {
            this._callIfExists(cb);
            return;
        }
        // Catch if haven't started but want to stop.
        else if(this.status === ActionStatus.STARTING) {
            this.startCallbacks.push(() => {
                this.stop(cb);
            });
            return;
        }
        this.stopCallbacks.push(cb);
        this.status = ActionStatus.STOPPING;
        let body = {
            command: 'stop',
            request_id: this.id,
            task_id: this.id
        };
        let bodyString:string = JSON.stringify(body);
        this.once('acknowledgement', () => {
            // ASR Service has stopped our action
            this._log({"OFFICIALLY STOPPED ": this.id});
            this.status = ActionStatus.STOPPED;
            this.stopCallbacks.forEach((callback) => {
                this._callIfExists(callback);
            });
            this.stopCallbacks = [];
            ASRVariables.numberActiveActions--;
            this._log({"Number of active Actions": ASRVariables.numberActiveActions});
            delete ASRVariables.idToAction[this.id];
        });
        let request = new XMLHttpRequest();
        this._log({"stopping ": this.id});
        request.open("POST", this.httpInterface, true);
        request.send(bodyString);
    }

    /**
     * Stops the current action and shuts down all recognizers.
     * @function AudioAction#stop
     */
    stopOldTask(cb?) {
        if(this.status === ActionStatus.STOPPING) {
            return;
        }
        else if(this.status === ActionStatus.STOPPED ||
                this.status === ActionStatus.CLEARED ||
                this.status === ActionStatus.CLEARING) {
            this._callIfExists(cb);
            return;
        }
        else if(this.status === ActionStatus.STARTING) {
            this.startCallbacks.push(() => {
                this.stop(cb);
            });
            return;
        }
        this.stopCallbacks.push(cb);
        this.status = ActionStatus.STOPPING;
        let request = new XMLHttpRequest();
        let body = {
            action: 'stop',
            audio_source_id: this.audioSourceId,
            // TODO: implement requestIdToAction
            request_id: this.id,
            task: '',
            task_id: this.id
        };
        let bodyString = JSON.stringify(body);
        // listen for event emitted from action via ASR now.
        this.once('received', () => {
            this.status = ActionStatus.STOPPED;
            this.stopCallbacks.forEach((callback) => {
                this._callIfExists(callback);
            });
            ASRVariables.numberActiveActions--;
            this.stopCallbacks = [];
        });
        this._log({'stopping old': this.id});
        request.open("POST", this.httpInterface, true);
        request.send(bodyString);
    }

    /**
     * Stops the current action and shuts down all recognizers.
     * @function AudioAction#stop
     */
    clearOldTask(cb?) {
        this.clearCallbacks.push(cb);
        if(this.status === ActionStatus.CLEARING) {
            return;
        }
        if(this.status === ActionStatus.CLEARED) {
            this._callIfExists(cb);
            return;
        }
        let request = new XMLHttpRequest();
        let body = {
            action: 'clear',
            audio_source_id: this.audioSourceId,
            // TODO: implement requestIdToAction
            request_id: this.id,
            task: '',
            task_id: this.id
        };
        this.once('received', () => {
            this.status = ActionStatus.CLEARED;
            this.clearCallbacks.forEach((callback) => {
                this._callIfExists(callback);
            });
            this.clearCallbacks = [];
            this._log({"OFFICIALLY CLEARED ": this.id});
            delete ASRVariables.idToAction[this.id];
        });
        let bodyString = JSON.stringify(body);
        this._log({"clearing old ": this.id});
        request.open("POST", this.httpInterface, true);
        request.send(bodyString);
        return true;
    }

    /**
     * Generates the grapheme to phoneme graph for a given word, which is 
     * necessary before running a name-learning task. Prompts a response from the
     * ASRService with pronunciations for the word.
     * @param listener {NameListener} the word to generate pronunciation guesses.
     * @method module:jibo/asr/AudioAction~generateGraphemeToPhoneme
     */
    generateGraphemeToPhoneme(listener:any) {
        let body = {
            action: "g2p",
            word: listener.word,
            nbest: "10",
            task_id: this.id,
            audio_source_id: this.audioSourceId,
        };
        ASRVariables.idToAction[listener.listenerId] = listener;
        let bodyString = JSON.stringify(body);
        let request = new XMLHttpRequest();
        request.open("POST", this.httpInterface, true);
        request.send(bodyString);
    }

    /**
     * Logs data to console if it should.
     * @param data {any} Data to log.
     * @method module:jibo/asr/AudioAction~_log
     * @private
     */
    _log(data: any) {
        if(this.shouldLog) {
            console.log("AudioAction Debug: ", data);
        }
    }

    /**
     * Call the callback if it exists. 
     * @param cb {Function} Function to call as callback
     * @method module:skills-service-manager/clients/asr/AudioAction~_callIfExists
     * @private
     */
    _callIfExists(cb?) {
        if(cb) {
            cb();
        }
    }

}

export default AudioAction;