import Scan from "./Scan";
import SystemManagerClient from "../../../clients/SystemManagerClient";

// @TODO - add comments/documentation
class ActiveScan extends Scan {
    private listener;
    private interval:number;

    constructor(){
        super();
	    this.listener = null;
    }
    
    public scan(callback){
        SystemManagerClient.instance.scan(callback);
    }
    
    public listen(interval, callback){
        if(this.listener === null && this.interval !== interval) {
            this.listener = setInterval(() => {
                SystemManagerClient.instance.scan((err,data)=>{
                    if(err){
                        callback(err,data);
                    }
                    else{
                        callback(err,data);
                    }
		        });
            }, interval);
        }
        else {
            if (this.interval !== interval){
                clearInterval(this.listener);
                this.listener = setInterval(() => {
		            SystemManagerClient.instance.scan((err,data)=>{
		                if(err){
		                    callback(err,data);
			            }
			            else{
			                callback(err,data);
			            }
		            });
                }, interval);
            }
            else{
                callback(null,null);
            }
        }

        this.interval = interval;
    }
    
    public stopListener(){
        clearInterval(this.listener);
    }
    
    
    
}

export default ActiveScan;
