import Router = require('router');
import {JiboServerRequest, JiboServerResponse, ServiceOptions, HTTPWSService} from 'jibo-service-framework';
import WebSocket = require("ws-without-native");
import {GlobalCommand, ParseResults, ListenResults} from "jibo-common-types";
import {createLog} from "../../utils/Log";
import SkillsService from "../skills-service/SkillsService";
import SkillsServiceSim from "../skills-service/SkillsServiceSim";
import {WSResponse} from "../listen-service/ListenService";
import {Event as TypedEvent} from "jibo-typed-events";

let log = createLog("global-manager-service");

//for now we want to hardcode subskills to be so we relaunch into be
const NATIVE_SKILL_MAP: {[key: string]: string} = {
    '@be/clock': '@be/be',
    '@be/settings': '@be/be',
    '@be/greetings': '@be/be',
    '@be/chitchat': '@be/be',
    '@be/main-menu': '@be/be',
    '@be/friendly-tips': '@be/be',
    '@be/who-am-i': '@be/be',
    "@be/create": "@be/be",
    "@be/gallery": "@be/be",
    '@be/idle': '@be/be',
    "@be/ifttt": "@be/be",
    "@be/circuit-saver": "@be/be",
    '@be/demo': '@be/be'
};

interface GlobalServiceOptions extends ServiceOptions {
    nativeSkillMap?:{[key: string]: string};
}

/**
 * @description
 * GlobalManagerService.
 * This class handles incoming requests to subscribe to global commands and manages
 * the state of those commands by accepting not only the command to which a skill
 * wants to subscribe and keeping track of all of the different global event stacks,
 * but also maintains knowledge of which skill subscribed to that global.
 * Because this service also handles relaunching and launching skills, at each skill
 * launch (or relaunch) it automatically unsubscribes that skill from the global event
 * stacks, so state is maintained across skill instances.
 * @module skills-service-manager/services/listen-service
 */
class GlobalManagerService extends HTTPWSService {

    private static _instance:GlobalManagerService;

    /**
     * Map from global command to whether jibo can handle it
     * @type {Map<GlobalCommand, boolean>}
     * @readonly
     */
    public globalHandlers: Map<GlobalCommand, boolean>;
    /**
     * Event to let other parts of SSM know we have fired a skillRelaunch
     * @type {TypedEvent<ParseResults>}
     * @readonly
     */
    public skillRelaunch: TypedEvent<ParseResults>;
    /**
     * Event to let other parts of SSM know we have gotten a global event
     * @type {TypedEvent<ParseResults>}
     * @readonly
     */
    public globalEvent: TypedEvent<ParseResults>;
    /**
     * Map from global command to whether jibo can handle it
     * @type {Map<GlobalCommand, boolean>}
     * @readonly
     */
    private nativeSkillMap: {[key: string]: string};
    private globalSocket: WebSocket;

    public static createInstance(options:GlobalServiceOptions, rootDir:string):GlobalManagerService {
        return new GlobalManagerService(options, rootDir);
    }

    public static get instance():GlobalManagerService {
        return GlobalManagerService._instance;
    }

    constructor(options:GlobalServiceOptions, rootDir:string) {
        super('global-manager', options, rootDir);
        GlobalManagerService._instance = this;
        this.onGlobal = this.onGlobal.bind(this);
        this.skillRelaunch = new TypedEvent<ParseResults>('Skill relaunch sent through socket.');
        this.globalEvent = new TypedEvent<ParseResults>('Global event sent through socket.');

        // initialize map of global handlers
        this.globalHandlers = new Map<GlobalCommand, boolean>();
        Object.keys(GlobalCommand).forEach((command) => {
            this.globalHandlers.set(GlobalCommand[command], false);
            this.nativeSkillMap = options.nativeSkillMap || NATIVE_SKILL_MAP;
        });
    }

    public init(callback: (err?:Error)=>void) {
        super.init((err:Error) => {
            log.info("Initialized");
            callback(err);
        });
    }

    public routes(url:Router) {
        super.routes(url);
        url.post('/global', (req:JiboServerRequest, res:JiboServerResponse) => {
            this.onGlobal(req, res);
        });
        url.post('/clean_relaunch', (req:JiboServerRequest, res:JiboServerResponse) => {
            this.onCleanRelaunch(req, res);
        });
    }

    public onConnection(client:WebSocket):void {
        super.onConnection(client);
        if(client.upgradeReq.url === '/globals') {
            this.globalSocket = client;
        }
    }

    public sendWsJson(client:WebSocket, json: Object | string): void {
        if(client) {
            super.sendWsJson(client, json);
        }
    }

    /**
     * Launch or relaunch a skill, including handling cleanup of GLSM.
     * Send out actual event for which skills will listen.
     * Alert Skills Service to switch skills.
     * @public
     */
    public handleSkillLaunch(parse:ParseResults, listenResults?:ListenResults) {
        if(listenResults) {
            console.warn("ListenResults no longer necessary for handleSkillLaunch");
        }

        const instance = SkillsService.instance || SkillsServiceSim.instance;

        const skillName = parse.NLParse.skill;
        // relaunch
        if (instance &&
            instance.currentSkill && (
            instance.currentSkill.name === skillName ||
            instance.currentSkill.name === this.nativeSkillMap[skillName])) {
            this.skillRelaunch.emit(parse);
            let body:any = this.returnType('OK', 'skill-relaunch', '', parse);
            this.sendWsJson(this.globalSocket, body);
        }
        // launch
        else {
            let body:any = this.returnType('OK', 'skill-launch', '', parse);
            this.sendWsJson(this.globalSocket, body);
        }
        return;
    }

    /**
     * Given a global command, returns whether or not the jibo module has registered to handle it.
     * @param {GlobalCommand} command to query if jibo module has said it can handle
     * @returns {Boolean} returns whether or not the jibo module can handle the global command.
     * @public
     */
    public canHandleGlobal(command: GlobalCommand) {
        log.info(`getting canHandle ${command} which is ${this.globalHandlers.get(command)}`);
        return this.globalHandlers.get(command);
    }

    /**
     * Given a global command, returns whether or not the jibo module has registered to handle it.
     * @param {GlobalCommand} command to query if jibo module has said it can handle
     * @param {Boolean} canHandle returns whether or not the jibo module can handle the global command.
     * @public
     */
    public setHandleGlobal(command: GlobalCommand, canHandle: boolean) {
        log.info(`setting canHandle ${command} to ${canHandle}`);
        this.globalHandlers.set(command, canHandle);
    }

    public emitGlobal(command:GlobalCommand, globalResults:ListenResults) {
        log.info("emitting global", globalResults.result);
        this.globalEvent.emit(globalResults.result);
        let body:any = this.returnType('OK', 'global', '', globalResults.result);
        this.sendWsJson(this.globalSocket, body);
    }

    protected onMessage(command:any, client:WebSocket) {
        return;
    }

    protected onClose():void {
        // Happens on skill crash!
        this.globalSocket = undefined;
    }

    /**
     * Parse out global command subscribers
     * @param req {JiboServerRequest} the request data to be processed.
     * @param res {JiboServerResponse} the response to send through WS.
     * @private
     */
    private onGlobal(req:JiboServerRequest, res:JiboServerResponse) {
        req.on('data', (chunk) => {
            let data = JSON.parse(chunk);
            this.globalHandlers.set(data.action, data.canHandle);
            let body = this.returnType('OK', JSON.stringify(data.action + ':' + data.canHandle), '', {});
            this.sendJson(res, JSON.stringify(body), 200);
        });
    }

    /**
     * Cleanly shut down listeners and kill the current skill and relaunch
     * @param req {JiboServerRequest} the request data to be processed.
     * @param res {JiboServerResponse} the response to send through WS.
     * @private
     */
    private onCleanRelaunch(req: JiboServerRequest, res: JiboServerResponse):void {
        let data:any;
        req.on('data', (chunk) => {
            // ignoring data object, because we're not supposed to get any data.
            // However, req doesn't like it when you have an `end` but no data handler.
            data += chunk;
        });
        req.on('end', () => {
            const launchParse = {
                skill: "@be/idle",
                intent: "@be/idle"
            };
            const parse = new ParseResults("stop", launchParse, launchParse, 50);
            this.handleSkillLaunch(parse);
            let body = this.returnType('OK', null, '', {});
            this.sendJson(res, JSON.stringify(body), 200);
        });
    }

    /**
     * Wrapper to create a return type
     * @param status {string} status of response
     * @param message {string} accompanying message of response
     * @param id {string} listener id if applicable
     * @param data {data} result of web request
     * @private
     */
    private returnType(status:string, message:string, id:string, data:any): WSResponse {
        let body: WSResponse = {
            status: status,
            message: message,
            id: id,
            result: data || {},
            moreinfo: ''
        };
        return body;
    }
}

export default GlobalManagerService;
