import Router = require('router');
import path = require('path');
import {JiboServerRequest, JiboServerResponse, ServiceOptions, HTTPWSService, RegistrationRecord, RegistryClient} from 'jibo-service-framework';

import fs = require('fs');
import uuid = require('uuid');
import async = require('async');
import WebSocket = require("ws-without-native");


const DEFAULT_TESTING_CREDENTIALS = {  // we should not embed credentials FIXME
    secretAccessKey: 'W5dxPYfmdGTETneE1LeuIcp8aCXrgr4eomrfW50s',
    accessKeyId: '3MRGwcKUvQuAk8Hsl7Xp',
    region: 'stg-entrypoint'
};

const OLD_TESTING_CREDENTIALS_SECRET_ACCESS_KEY = 'EdNNKxicwehgIXhlLM4Nb1L66NZC6NXTLhVRuyCs';

class SystemManagerService extends HTTPWSService {

    private static _instance:SystemManagerService;

    public static createInstance(options:ServiceOptions, rootDir:string):SystemManagerService {
        return new SystemManagerService(options, rootDir);
    }

    public static get instance():SystemManagerService {
        return SystemManagerService._instance;
    }

    constructor(options:ServiceOptions, rootDir:string) {
        super('system-manager', options, rootDir);
        SystemManagerService._instance = this;
        this.onGetIdentity = this.onGetIdentity.bind(this);
        this.onGetCredentials = this.onGetCredentials.bind(this);
        this.onSetCredentials = this.onSetCredentials.bind(this);
        this.onGetMode = this.onGetMode.bind(this);
        this.onSetMode = this.onSetMode.bind(this);
        this.onGetVersion = this.onGetVersion.bind(this);
        this.onWipe = this.onWipe.bind(this);
        this.onBackup = this.onBackup.bind(this);
        this.onRestore = this.onRestore.bind(this);
        this.onReboot = this.onReboot.bind(this);
        this.onPoweroff = this.onPoweroff.bind(this);
        this.onForceLogs = this.onForceLogs.bind(this);
    }

    public init(callback: (err?:Error)=>void) {
        super.init((err:Error) => {
            callback(err);
        });
    }

    public routes(url:Router) {
        super.routes(url);
        url.get('/credentials', this.onGetCredentials);
        url.post('/credentials', this.onSetCredentials);
        url.get('/identity', this.onGetIdentity);
        url.get('/mode', this.onGetMode);
        url.post('/mode', this.onSetMode);
        url.get('/version', this.onGetVersion);
        url.post('/wipe', this.onWipe);
        url.post('/backup', this.onBackup);
        url.post('/restore', this.onRestore);
        url.post('/power/off', this.onPoweroff);
        url.post('/power/reboot', this.onReboot);
        url.post('/logs/upload', this.onForceLogs);
    }

    protected onMessage(command:any, client:WebSocket) {
        return;
    }

    protected getRequestData(req:JiboServerRequest, callback:(err:Error, data?:any) => void):void {
        let chunk = "";
        req.on('data', data => chunk += data);
        req.on('end', () => {
            try {
                let data = JSON.parse(chunk);
                callback(null, data);
            }
            catch(e) {
                callback(e);
            }
        });
    }

    /*
     * @description Posts backup request to all other services. Replies with 204 response when the
     * other services have replied.
     * @param req {JiboServerRequest} request to service
     *                                param "directory" -- directory to backup to
     *                                param "dataDirectory" (optional) -- directory where data is stored
     *                                  otherwise, use service's own data directory
     * @param res {JiboServerResponse} response to send from service.
     * @private
     */
    private onBackup(req:JiboServerRequest, res:JiboServerResponse) {

        this.doBackupOrRestoreOp("backup", (code:number) => {
            this.sendJson(res, {}, code);
        });
    }

    /*
     * @description Posts wipe request to all other services. Replies with 204 response when the
     * other services have replied.
     * @param req {JiboServerRequest} request to service
     *                                param "dataDirectory" (optional) -- directory where data is stored
     *                                  otherwise, use service's own data directory
     * @param res {JiboServerResponse} response to send from service.
     * @private
     */
    private onWipe(req:JiboServerRequest, res:JiboServerResponse) {
        this.doBackupOrRestoreOp("wipe", (code:number) => {
            this.sendJson(res, {}, code);
        });
    }

    /*
     * @description Posts restore request to all other services. Replies with 204 response when the
     * other services have replied.
     * @param req {JiboServerRequest} request to service
     *                                param "directory" -- directory where backup is
     *                                param "dataDirectory" (optional) -- directory where data is stored
     *                                  otherwise, use service's own data directory
     * @param res {JiboServerResponse} response to send from service.
     * @private
     */
    private onRestore(req:JiboServerRequest, res:JiboServerResponse) {

        this.doBackupOrRestoreOp("restore", (code:number) => {
            this.sendJson(res, {}, code);
        });
    }

    private doBackupOrRestoreOp(opType:string, callback:(code:number) => void) {
        RegistryClient.instance.getRecords((error:Error, records:Array<RegistrationRecord>) => {
            if (error) {
                callback(500);
            }

            let tasks = []; // asynchronous tasks
            for(let i = 0; i < records.length; i++) {

                let record = records[i];

                let opFolder = path.join(process.env.HOME || process.env.USERPROFILE, '.jibo', 'backup', record.name);
                let data = { 'directory': opFolder };

                // Don't want to send a POST to ourselves, just to every other Node-JS service
                if (record.name !== 'system-manager') {
                    tasks.push((cb) => {
                        console.log(`${opType} registry record is: `, record.name);
                        console.log(`${opType} registry host, port are: `, record.host, record.port);

                        const request = new XMLHttpRequest();
                        let postString = '/_M_/system/'+opType;
                        request.open('POST',  `http://${record.host}:${record.port}${postString}`, true);
                        request.onreadystatechange = () => {
                            if (request.readyState === 4) {
                                //console.log("status is ", request.status);
                                cb();
                            }
                        };
                        request.send(JSON.stringify(data));
                    });
                }
            } // end for (through tasks)

            async.parallel(tasks, (err) => {
                if (err) {
                    callback(500);
                } else {
                    console.log(`Have completed service ${opType} calls`);
                    callback(204);
                }
            });
        }); // End RegistryClient.instance.getRecords((error, records)
    }

    private onGetCredentials(req:JiboServerRequest, res:JiboServerResponse) {
        let filename = path.join(process.env.HOME || process.env.USERPROFILE, '.jibo', 'credentials.json');
        fs.readFile(filename, 'utf8', (err, data) => {
            let credentials;
            if (err && err.code === 'ENOENT') {
                // eventually we'll change this so we have a built in fake root for the simulator
                // and we'll only read in credentials from ~/.jibo/credentials.json if it already exists
                err = null;
                credentials = DEFAULT_TESTING_CREDENTIALS;
                fs.writeFileSync(filename, JSON.stringify(credentials, null, 4));
            }
            else {
                try {
                    credentials = JSON.parse(data);
                }
                catch (e) {
                    console.error(`The credentials file has invalid JSON at ${filename}`);
                }
                if (credentials && credentials.secretAccessKey === OLD_TESTING_CREDENTIALS_SECRET_ACCESS_KEY) {
                    credentials = DEFAULT_TESTING_CREDENTIALS;
                    fs.writeFileSync(filename, JSON.stringify(credentials, null, 4));
                }
            }
            if (credentials) {
                this.sendJson(res, credentials);
            }
        });
    }

    private onSetCredentials(req:JiboServerRequest, res:JiboServerResponse) {
        // fix me for real?
        this.sendJson(res, {}, 204);
    }

    private onGetIdentity(req:JiboServerRequest, res:JiboServerResponse) {
        this.sendJson(res, {
            "guid": uuid.v4(),
            "name": 'opal-sage-victor-valley',
            "cpuid": uuid.v4(),
            "wifi_mac": uuid.v4()
        });
    }

    private onGetMode(req:JiboServerRequest, res:JiboServerResponse) {
        this.sendJson(res, {
            mode: 'normal'
        });
    }

    private onSetMode(req:JiboServerRequest, res:JiboServerResponse) {
        this.sendJson(res, {}, 204);
    }

    private onGetVersion(req:JiboServerRequest, res:JiboServerResponse) {
        this.sendJson(res, {
            version: 'Jibo Release Version: Release-3.1.0\n'
        });
    }

    private onReboot(req:JiboServerRequest, res:JiboServerResponse) {
        this.sendJson(res, {}, 204);
    }

    private onPoweroff(req:JiboServerRequest, res:JiboServerResponse) {
        this.sendJson(res, {}, 204);
    }

    private onForceLogs(req:JiboServerRequest, res:JiboServerResponse) {
        this.sendJson(res, {
            result: 'success'
        }, 200);
    }

}


export default SystemManagerService;
