import Recognizer from './Recognizer';
import ASRService from "./ASRService";


class NameRecognizer extends Recognizer {

    protected path: string;

    private word: string;

    constructor(word:string) {
        let options = {
            path: "namelearning",
            timeout: 0
        };
        super(options);
        this.word = word;
        this.path = ASRService.instance.OLD_BASE + "namelearning";
    }

    toString() {
        return this.pack();
    }

    pack() {
        let body = {
            name: "name_learning",
            path: this.path,
            timeout: 100000,
            speaker_name: this.word,
            bargein: false,
            incremental: false
        };
        return JSON.stringify(body);
    }

    onResult(data) {
        console.log("name reco onresult");
        this.emit('result', data);
    }
}

export default NameRecognizer;