        // just an example of overriding the default '/' routing in the superclass
        // url.all('/', (req:JiboServerRequest, res:JiboServerResponse) => {
        //     this.sendFile(res, path.join(this.staticDir, 'index2.html'), 'text/html');
        // });

        url.get('/v1/kb/:kbname/node/load/:id', (req:JiboServerRequest, res:JiboServerResponse) => {
            this.attachKBDB(req, res, () => {
                this.load(req, res);
            });
        });

        url.get('/v1/kb/:kbname/node/loadRoot', (req:JiboServerRequest, res:JiboServerResponse) => {
            this.attachKBDB(req, res, () => {
                this.loadRoot(req, res);
            });
        });

        url.post('/v1/kb/:kbname/node/save', (req:JiboServerRequest, res:JiboServerResponse) => {
            this.attachKBDB(req, res, () => {
                this.save(req, res);
            });
        });

        url.delete('/v1/kb/:kbname/node/remove/:id', (req:JiboServerRequest, res:JiboServerResponse) => {
            this.attachKBDB(req, res, () => {
                this.remove(req, res);
            });
        });

        url.get('/v1/kb/:kbname/asset/:filename', (req:JiboServerRequest, res:JiboServerResponse) => {
            this.attachKBDB(req, res, () => {
                this.getAsset(req, res);
            });
        });

        url.post('/v1/kb/:kbname/asset/:filename', (req:JiboServerRequest, res:JiboServerResponse) => {
            this.attachKBDB(req, res, () => {
                this.addAsset(req, res);
            });
        });

        url.delete('/v1/kb/:kbname/asset/:filename', (req:JiboServerRequest, res:JiboServerResponse) => {
            this.attachKBDB(req, res, () => {
                this.removeAsset(req, res);
            });
        });

        url.post('/v1/kb/:kbname/create', (req:JiboServerRequest, res:JiboServerResponse) => {
            this.createSlice(req, res);
        });

        url.get('/v1/kb/:kbname/exists', (req:JiboServerRequest, res:JiboServerResponse) => {
            this.existsSlice(req, res);
        });

        // these next two are very dangerous

        url.delete('/v1/kb/:kbname/remove/yesiamsure', (req:JiboServerRequest, res:JiboServerResponse) => {
            this.removeSlice(req, res);
        });

        url.delete('/v1/removeall/yesiamsure', (req:JiboServerRequest, res:JiboServerResponse) => {
            this.removeKbEverything(req, res);
        });

        ///
        /// loop/account update routes
        ///

        url.post('/v1/loop/updatePhoneticName', (req:JiboServerRequest, res:JiboServerResponse) => {
            this.attachLoopKBDB(req, res, () => {
                this.loopUpdatePhoneticName(req, res);
            });
        });

        url.post('/v1/loop/enrollment', (req:JiboServerRequest, res:JiboServerResponse) => {
            this.attachLoopKBDB(req, res, () => {
                this.loopSetEnrollment(req, res);
            });
        });

        url.post('/v1/loop/suspend', (req:JiboServerRequest, res:JiboServerResponse) => {
            this.attachLoopKBDB(req, res, () => {
                this.loopSuspend(req, res);
            });
        });

        ///
        /// media list manager routes
        ///

        url.post('/v1/media/storePhoto', (req:JiboServerRequest, res:JiboServerResponse) => {
            this.mediaStorePhoto(req, res);
        });

        url.post('/v1/media/downloadThumbnails', (req:JiboServerRequest, res:JiboServerResponse) => {
            this.mediaDownloadThumbnails(req, res);
        });

        url.post('/v1/media/downloadPhoto', (req:JiboServerRequest, res:JiboServerResponse) => {
            this.mediaDownloadPhoto(req, res);
        });

        url.post('/v1/media/deletePhoto', (req:JiboServerRequest, res:JiboServerResponse) => {
            this.mediaDeletePhoto(req, res);
        });
