    load(req:JiboServerRequest, res:JiboServerResponse) {
        let kbdb = req.params.kbdb;
        let _id = req.params.id;
        kbdb.load(_id, (err, node) => {
            log.iferr(err, 'kb.load');
            if (node && node._id) {
                log.debug('loaded node', node._id);
            }
            this.sendJson(res, node);
        });
    }


    loadRoot(req:JiboServerRequest, res:JiboServerResponse) {
        let kbdb = req.params.kbdb;
        kbdb.loadRoot((err, node) => {
            log.iferr(err, 'kb.load');
            if (node && node._id) {
                log.debug('loaded root node', node._id);
            }
            this.sendJson(res, node);
        });
    }


    save(req:JiboServerRequest, res:JiboServerResponse) {
        let kbdb = req.params.kbdb;
        if (req.body && req.body._id) {
            log.debug('save', req.body._id);
        }
        let node = new jibo.kb.Node(null, null, req.body);
        kbdb.adoptNodeAsOurOwn(node);
        node.save( (err) => {
            log.iferr(err, 'node.save');
            this.finish(res, err);
        });
    }


    remove(req:JiboServerRequest, res:JiboServerResponse) {
        let kbdb = req.params.kbdb;
        let _id = req.params.id;
        log.debug('remove', _id);
        kbdb.remove(_id, (err) => {
            log.iferr(err, 'node.remove');
            this.finish(res, err);
        });
    }


    createAssetInstance(req:JiboServerRequest) {
        let kbdb = req.params.kbdb;
        let filename = req.params.filename;

        let rootDir = kbdb.getDirectory();
        let asset = new jibo.kb.Asset(filename);
        asset.setRootDir(rootDir);
        return asset;
    }


    getAsset(req:JiboServerRequest, res:JiboServerResponse) {
        let asset = this.createAssetInstance(req);
        let filename = asset.fullFilenameOrURL();
        this.sendFile(res, filename);
    }


    addAsset(req:JiboServerRequest, res:JiboServerResponse) {
        let asset = this.createAssetInstance(req);
        asset.save(req, (err) => {
            this.finish(res, err);
        });
    }


    removeAsset(req:JiboServerRequest, res:JiboServerResponse) {
        let asset = this.createAssetInstance(req);
        asset.remove((err) => {
            this.finish(res, err);
        });
    }


    createSlice(req:JiboServerRequest, res:JiboServerResponse) {
        let kbName = querystring.unescape(req.params.kbname);
        jibo.kb.databaseManager.create(kbName, (err, created) => {
            if (err) {
                throw err;
            } else {
                this.sendJson(res, {created: created});
            }
        });
    }


    existsSlice(req:JiboServerRequest, res:JiboServerResponse) {
        let kbName = querystring.unescape(req.params.kbname);
        jibo.kb.databaseManager.exists(kbName, (err, exists) => {
            if (err) {
                throw err;
            } else {
                this.sendJson(res, {exists: exists});
            }
        });
    }


    /** Unload a given kb slice from memory and remove it from disk.
     * Also removes any sub-kbs inside this slice. For example, if you
     * remove '/jibo', that would also remove '/jibo/loop', '/jibo/settings'
     * and all other kb slices under '/jibo'.
     */
    removeSlice(req:JiboServerRequest, res:JiboServerResponse) {
        let kbName = querystring.unescape(req.params.kbname);
        if (kbName === '/jibo/loop' && this.loopManager) {
            this.loopManager.shutdown( (err) => {
                log.iferr(err);
                if (err) {
                    throw err;
                }
                this.loopManager = null;
                this.removeSlice(req, res);
            });
        } else {
            // release the model and any submodels
            Object.keys(this.kbdbs).forEach( (name) => {
                if ((kbName === name) || (name.startsWith(kbName+'/'))) {
                    delete this.kbdbs[kbName];
                    jibo.kb.databaseManager.release(kbName);
                }
            });

            let directory = jibo.kb.KnowledgeDatabase.getKbDirectory(kbName);

            // just a sanity check to prevent '/' or '.' or 'C:\'
            // minimum path is either /opt/jibo/Knowledge or [~]/.jibo/kb
            directory = path.normalize(directory);
            if (directory.length < 8) {
                throw new Error('not comfortable with kb slice directory name '+directory);
            } else {
                log.info('removing kb slice', directory);
                rimraf(directory, {disableGlob: true}, (err) => {
                    this.finish(res, err);
                });
            }
        }
    }


    /** Unload all kb slices from memory, stop the Loop Manager, and
     * delete the ENTIRE KNOWLEDGEBASE!
     */
    removeKbEverything(req:JiboServerRequest, res:JiboServerResponse) {
        this.loopManager.shutdown( (err) => {
            log.iferr(err);
            if (err) {
                throw err;
            }
            this.loopManager = null;

            // release all the models
            this.kbdbs = null;

            // get the root directory of the entire kb
            let rootDirectory = jibo.kb.KnowledgeDatabase.getRootDirectory();

            // just a sanity check to prevent '/' or '.' or 'C:\'
            // minimum path is either /opt/jibo/Knowledge or [~]/.jibo/kb
            rootDirectory = path.normalize(rootDirectory);
            if (rootDirectory.length < 8) {
                throw new Error('not comfortable with kb root directory name '+rootDirectory);
            } else {
                log.warn('removing the entire kb at', rootDirectory);
                rimraf(rootDirectory, {disableGlob: true}, (err) => {
                    if (err) {
                        throw err;
                    }
                    // put back the kb root directory stub
                    fs.mkdir(rootDirectory, (err) => {
                        this.finish(res, err);
                    });
                });
            }
        });
    }


    ///
    /// loop/account update methods
    ///

    loopUpdatePhoneticName(req:JiboServerRequest, res:JiboServerResponse) {
        if (req.body && req.body._id) {
            log.debug('loop updatePhoneticName', req.body._id);
        }

        let params = req.body;
        let acceptableFields = ['loopId', 'id', 'phoneticName'];
        Object.keys(params).forEach( (field) => {
            if (acceptableFields.indexOf(field) < 0) {
                throw new Error('unacceptable field in account update: '+field);
            }
        });

        this.loopManager.loopUpdatePhoneticName(params, (err) => {
            this.finish(res, err);
        });
    }


    loopSetEnrollment(req:JiboServerRequest, res:JiboServerResponse) {
        if (req.body && req.body._id) {
            log.debug('loop set enrollment', req.body._id);
        }

        let params = req.body;
        let acceptableFields = ['loopId', 'id', 'face', 'voice'];
        Object.keys(params).forEach( (field) => {
            if (acceptableFields.indexOf(field) < 0) {
                throw new Error('unacceptable field in loop set enrollment:'+field);
            }
        });

        this.loopManager.loopSetEnrollment(params, (err) => {
            this.finish(res, err);
        });
    }


    loopSuspend(req:JiboServerRequest, res:JiboServerResponse) {
        if (req.body && req.body._id) {
            log.debug('loop suspend', req.body._id);
        }

        let params = req.body;
        let acceptableFields = ['loopId'];
        Object.keys(params).forEach( (field) => {
            if (acceptableFields.indexOf(field) < 0) {
                throw new Error('unacceptable field in loop set enrollment:'+field);
            }
        });

        this.loopManager.loopSuspend(params, (err) => {
            this.finish(res, err);
        });
    }


    ///
    /// media list manager methods
    ///

