import ASRVariables from './ASRVariables';
import AudioAction from './AudioAction';
import SpeakerAction from './SpeakerAction';
import AudioSource from './AudioSource';
import Recognizer from './Recognizer';
import SpeakerRecognizer from './SpeakerRecognizer';
import NameRecognizer from './NameRecognizer';
import NameListener from './NameListener';
import Listener from './Listener';
import Enroller from './Enroller';
import {WSClient} from 'jibo-service-framework';
import {EventEmitter} from 'events';
import {SpeakerId, SpeakerIdRecord} from 'jibo-common-types';

export enum UrlInterface {
    STANDARD = <any> 'STANDARD',
    OLD = <any> 'OLD',
    PRONUN = <any> 'PRONUN'
}

export class ASRData {
    event_type: string; //type of listening event. Options: [hotphrase, speech_to_text_incremental, speech_to_text_final, end_of_speech, acknowledgement]
    task_id: string; //Recognition task ID matching input requested
    status: string; //Status of request. options: [normal, error]
    message: string; // Message to augment status. options: [No request ID given, No matching request ID for 'stop' command, Network initialization timed out after 2000 ms.]
    /*
     * exists for platform builds <3.0.0.
     */
    speaker_id: SpeakerId;
    /*
     * exists for platform builds >=3.0.0.
     */
    speaker_id_record?:SpeakerIdRecord;
    utterances:Array<any>;  //Array of nbest utterances recognized by the ASR service. Only applicable if response_type is 'hotphrase', 'speech_to_text' or 'incremental'.
    timestamp: string; // Timestamp of response in YYYY-MM-DDTHH:MM:SS.UUUZ
    message_id: string; // Unique id of the message originated from ASR used for coordination between ASR, NLU and SDK.
    request_id: string; // the id of the request to which this message refers to.

    constructor(data) {
        this.event_type = data.event_type;
        this.task_id = data.task_id;
        this.status = data.status;
        this.message = data.message || "";
        this.speaker_id = data.speaker_id ? new SpeakerId(data.speaker_id) : null;
        this.speaker_id_record = data.speaker_id_record ? new SpeakerIdRecord(data.speaker_id_record) : null;
        this.utterances = data.utterances || [{utterance:""}];
        this.timestamp =  data.timestamp || "";
        this.message_id = data.message_id || ""; 
        this.request_id = data.request_id || ""; 
    }
}


/**
 * @description
 * Audio Speech Recognition client. Recieves messages from ASR Service
 * both in simulator and on robot.
 * This class manages incoming responses through the ASR Websocket, as well as
 * requests to name learning, enrollment, and speaker ID listing and deletion.
 * It also ensures an audio source is initialized.
 * @class ASRService
 * @module jibo/asr
 */
class ASRService extends EventEmitter {

    private static _instance:ASRService;

    public isInitialized: boolean;
    public BASE: string = "/usr/local/share/asrservice/sharedresources/";
    public OLD_BASE : string = "/var/jibo/asr/";
    public verbose:boolean = false;
    public pronunAction: AudioAction;
    private msgs: Array<any>;
    private listSpeakerCallbacks: Array<any>;
    private deleteSpeakerCallbacks: Array<any>;
    private audioUrl: string;
    private asrInterfaceUrl: string;
    private asrInterfaceOld: string;
    private speakerInterfaceUrl: string;
    private asrPronunUrl: string;
    private socketUrlOld: string;
    private socketUrl: string;
    private alsaSource: AudioSource;
    private wavSource: AudioSource;
    private socketOld: WSClient;
    private socket: WSClient;
    private loggingEnabled: boolean;
    private paused: boolean;
    private enrollerId: string;

    public static createInstance():ASRService {
        return new ASRService();
    }

    public static get instance():ASRService {
        return ASRService._instance;
    }

    constructor() {
        super();
        if(ASRService._instance) {
            throw new Error("ASRService is a singleton");
        }
        ASRService._instance = this;
        this.isInitialized = false;
        this.msgs = [];
        this.listSpeakerCallbacks = [];
        this.deleteSpeakerCallbacks = [];
        this.enrollerId = "";
    }

    get Recognizer() {
        return Recognizer;
    }

    get SpeakerRecognizer() {
        return SpeakerRecognizer;
    }

    get NameRecognizer() {
        return NameRecognizer;
    }

    init(service, cb) {
        try {
            this.socketUrl = "ws:" + service.host + ":" + service.port + "/simple_port";
            this.socketUrlOld =  "ws:" + service.host + ":" + service.port + "/port";
            this.audioUrl = "http://" + service.host + ":" + service.port + "/audio_source";
            this.asrInterfaceUrl = "http://" + service.host + ":" + service.port + "/asr_simple_interface";
            this.speakerInterfaceUrl = "http://" + service.host + ":" + service.port + "/spkr_id_interface";
            this.asrPronunUrl = "http://" + service.host + ":" + service.port + "/pronun_interface";
            this.asrInterfaceOld= "http://" + service.host + ":" + service.port + "/asr_interface";

            this.socket = new WSClient(this.socketUrl);
            this.socketOld = new WSClient(this.socketUrlOld);

            this.loggingEnabled = false;

            this.socket.on('error', (err, data) => {
                if(err.startsWith('json')) {
                    console.warn(err, data);
                }
                else {
                    console.warn("error connecting to server");
                }
            });
            this.socketOld.on('error', (err, data) => {
                if(err.startsWith('json')) {
                    // Leaving this commented out in here for
                    // TODO: this isn't actually invalid json data,
                    // TODO: there is an issue with jibo-client-framework
                    // TODO: in which it tries to parse this but it is already parsed.
                    console.warn(err, data);
                    // let socketData = {
                    //     task_id: this.enrollerId,
                    //     status: 'ERROR',
                    //     api: 'old',
                    //     message: err,
                    //     content: data
                    // };
                    this.processMessage(data);
                }
                else {
                    console.warn("error connecting to old server");
                }
            });
            this.socket.on('reopen', () => {
                this.initAlsaSource((err) => {
                    console.log('ALSA SOURCE INIT', err);
                    this.emit('reopen');
                });
            });
            this.socket.on('close', () => {
                this.emit('close');
            });

            this.socket.on('message', (data) => {
                data.api = 'simplified';
                this.msgs.push(data);
                while(!this.paused && this.msgs.length) {
                    this.processNextMessage();
                }
            });
            this.socketOld.on('message', (data) => {
                data.api = 'old';
                this.msgs.push(data);
                while(!this.paused && this.msgs.length) {
                    this.processNextMessage();
                }
            });

            this.initAlsaSource(cb);
        }
        catch(err){
            console.warn(err);
        }
    }


    initAlsaSource(cb) {
        this.alsaSource = new AudioSource(this.audioUrl);
        this.alsaSource.init((err) => {
            if(err) {
                console.warn(err);
            }
            this.isInitialized = true;
            cb();
        });
    }

    /*
     * Pauses ASR messages to preserve message order for other asynchronous events.
     * @method module:jibo/asr~pause
     */
    pause() {
        this.paused = true;
    }

    /*
     * Finishes processing queued ASR messages then continues processing as they arrive.
     * @method module:jibo/asr~resume
     */
    resume() {
        this.paused = false;
        while(this.msgs.length) {
            this.processNextMessage();
        }
    }

    /*
     * Sends next msg in queue to processMessage.
     * @method module:jibo/asr~processNextMessage
     * @private
     */
    processNextMessage() {
        this.processMessage(this.msgs.shift());
    }

    /*
     * Processes data messages by sending and emitting to appropriate recipients
     * @method module:jibo/asr~processMessage
     * @param {Object} data
     * @private
     */
    processMessage(data) {
        const action = ASRVariables.idToAction[data.task_id];
        if(data.nlu_req_id) {
            const content = data.nlu_json_content;
            if(content && content.Status === "ERROR") {
                console.error("NLU ERROR", content.Message.exception, content.Message.info);
            }
        }

        if(data.status === "ERROR" && action) {
            action.emit('error', data.message, data.content);
        }

        // Old ASR API, either enrollment or pronunciation
        // Eventually we're ignoring this and not even opening the socket.
        if(data.api === 'old') {
            if(data.status === "received") {
                if(action) {
                    action.emit("received");
                }
                return;
            }

            if(data.final_composite && action) {
                action.emit('finished', action);
                return;
            }
            // name pronunciation API for g2p
            let pronunciations = data.pronunciations;
            if(pronunciations && pronunciations.length > 0) {
                // g2p
                if(data.success && this.pronunAction) {
                    this.pronunAction.emit('got-pronunciations', pronunciations);
                }
                // acoustic example
                else if (data.pronunciations[0].success && action) {
                    action.emit('got-pronunciations', pronunciations[0]);
                }
                else {
                    this.pronunAction.emit('pronun-error', pronunciations);
                }
                return;
            }
            // there's a recognizer to recognize
            const recognizer = ASRVariables.idToRecognizer[data.simple_recog_name];
            if(recognizer) {
                recognizer.onResult(data);
                return;
            }

            // listing and deleting speaker api
            if(data.speaker_idstatus === 'LISTING-SPEAKERS') {
                this.listSpeakerCallback(data);
                return;
            }
            else if(data.speaker_idstatus === 'DELETING-SPEAKER') {
                this.deleteSpeakerCallback(data);
                return;
            }
        }

        if (data.status !== 'normal') {
            if (data.status === 'error' && action) {
                console.warn('ASR Service returned error response. Check ASR debug', data.message);
                console.warn("Network Initialization Timeouts may be due to poor wifi connectivity");
                action.emit('speech_to_text_final', data);
                action.emit('error', data.message);
                // action.emit('restart');
            }
            else if(action) {
                /*
                    TODO: catch enrollment ASR messages here -- update once this is
                    fixed in ASR service (should send back status 'normal')
                */
                action.emit(data.event_type, data.status);
            }
            return;
        }

        else if(data.api === 'simplified') {
            data = new ASRData(data);
            if(!action) {
                const unrecognizedAction = new AudioAction(this.asrInterfaceUrl, data.task_id);
                if(data.task_id.startsWith("DEBUG:")) {
                    return;
                }
                else {
                    unrecognizedAction.stop();
                    console.error("No action found for ASR response", data);
                }
                return;
            }
            // UNCOMMENT to see all ASR emits
            // console.log('emitting ' + data.event_type + ' for ' + action.id);
            action.emit(data.event_type, data);
        }
    }

    /**
     * Sets this.enrollerId to map to incoming socket messages
     * if we get an error during the enrollment process. 
     * This if for fireproofing purposes ONLY 
     * @method module:jibo/asr~setEnrollerId
     * @public
     */
    setEnrollerId(id) {
        this.enrollerId = id;
    }    


    /**
     * Creates a single AudioSource.
     * @method module:jibo/asr~createWavSource
     * @returns {AudioAction}
     * @private
     */
    createWavSource(wavs) {
        this.wavSource = new AudioSource(this.audioUrl, wavs);
        return this.wavSource;
    }

    /**
     * Creates a single AudioAction that will use initialized wav source as audio.
     * @method module:jibo/asr~createAudioAction
     * @returns {AudioAction}
     * @private
     */
    createWavAction() {
        let action = new AudioAction(this.asrInterfaceUrl);
        this.wavSource.link(action);
        return action;
    }

    /**
     * Creates a single AudioAction.
     * @method module:jibo/asr~createAudioAction
     * @returns {AudioAction}
     * @private
     */
    createAudioAction(url?:UrlInterface, id?:string) {
        let action:any;
        if(!url || url === UrlInterface.STANDARD) {
            action = new AudioAction(this.asrInterfaceUrl, id);
        }
        else if (url === UrlInterface.OLD){
            action = new AudioAction(this.asrInterfaceOld, id);
        }
        else if (url === UrlInterface.PRONUN){
            action = new AudioAction(this.asrPronunUrl, id);
            this.pronunAction = action;
        }
        this.alsaSource.link(action);
        return action;
    }

    /**
     * Creates a single AudioAction.
     * @method module:jibo/asr~createAudioAction
     * @returns {AudioAction}
     * @private
     */
    createSpeakerAction() {
        let action = new SpeakerAction(this.speakerInterfaceUrl);
        this.alsaSource.link(action);
        return action;
    }


    /**
     * Creates a single AudioAction and returns in callback.
     * @method module:jibo/asr~createAudioAction
     * @returns {AudioAction}
     * @private
     */
    createSpeakerActionAsync(cb) {
        let action = new SpeakerAction(this.speakerInterfaceUrl);
        this.alsaSource.link(action);
        return cb(action);
    }


    /**
     * Lists all speakers enrolled on connected Robot.
     * @method module:jibo/asr~listEnrolledSpeakers
     * @param cb {Function} the callback through which the speaker ID status 
     * (list/delete) will be returned.
     */
    listEnrolledSpeakers(cb) {
        this.listSpeakerCallbacks.push(cb);
        this.createSpeakerActionAsync((action) => {
            action.listSpeakers();
        });
    }


    /*
     * Sends every subscribed callback listening for a listing-speakers 
     * ASR message the most recently received speaker list through ASR socket. 
     *                      then removes all callbacks in the subscribed list. 
     * @method module:jibo/asr~listSpeakerCallback
     * @param data {Object} ASR socket data for speakers.
     * @param data.speaker_idstatus {String} "LISTING-SPEAKERS"
     * @param data.speaker_ids for Text-Dependent {Array} Array of speakers enrolled with 'hey jibo'
     * @param data.speaker_ids for Text-Independent {Array} Array of speakers enrolled with free speech
     * @private
     */
    listSpeakerCallback(data) {
        this.listSpeakerCallbacks.forEach((cb) => {
            cb(data);
        });
        this.listSpeakerCallbacks = [];
    }


    /**
     * Deletes speaker from enrolled speakers. 
     * @method module:jibo/asr~deleteSpeaker
     * @param speaker {String} the name of the speaker to be deleted
     * @param textIdType {String} type of enrollment to be deleted. "Text-Dependent", 
     * "Text-Independent", "TD+TI" are only options
     * @param cb {Function} the callback through which the speaker ID status 
     * (list/delete) will be returned.
     */
    deleteSpeaker(speaker, textIdType="TD+TI", cb) {
        this.deleteSpeakerCallbacks.push(cb);
        this.createSpeakerActionAsync((action) => {
            action.deleteSpeaker(speaker, textIdType);
        });
    }

    /*
     * Sends every subscribed callback listening for a delete-speakers 
     * ASR message the most recently received deleted speaker through ASR socket. 
     * then removes all callbacks in the subscribed list. 
     * @method module:jibo/asr~deleteSpeakerCallback
     * @param data {Object} ASR socket data for speakers.
     * @param data.speaker_idstatus {String} "DELETING-SPEAKER" or "NO-SPEAKERS-TO-DELETE"
     * @private
     */
    deleteSpeakerCallback(data) {
        this.deleteSpeakerCallbacks.forEach((cb) => {
            cb(data);
        });
        this.deleteSpeakerCallbacks = [];
    }

    /*
     * Logs every message recieved by ASR service
     * @method module:jibo/asr~setLogging
     * @param loggingEnabled {boolean} send true to log all ASR messages
     * @public
     */
    setLogging(loggingEnabled) {
        this.loggingEnabled = loggingEnabled;
    }

    /**
     * Sends a listener as an argument to callback which emits listen events.
     * @param options {Object} Listen options.
     * @param options.bargein {boolean} `true` to use echo cancellation.
     * @param options.heyJibo {boolean} `true` to listen for "hey jibo".
     * @param options.detectEnd {boolean} `true` to listen for end of speech.
     * @param options.incremental {boolean} `true` to listen for incremental results.
     * @param options.authenticateSpeaker {String} Name of speaker, if applicable.
     * @param [options.speech_to_text] {boolean} false to listen only for 'hey jibo'.
     * @param rule {String}  The rule to use to parse audio input.
     * @returns {module:jibo.services.asr.Listener} Listener with given recognition options.
     * @method module:jibo/asr~createListener
     */
    createListener(options) {
        return new Listener(options);
    }

    /**
     * Returns enroller which emits enrollment events.
     * @param options {Object} Enroller options.
     * @param options.speakerName {String} name of speaker to enroll.
     * @param options.enrollmentType {enum} 'text-dependent' or 'text-independent'.
     * @returns {module:jibo.services.asr.Enroller} Enroller with given enrollment options.
     * @method module:jibo/asr~createEnroller
     */
    createEnroller(options, cb?) {
        return new Enroller(options, cb);
    }

    /*
     * Fakes a speech_to_text_final to all registered actions. 
     * @param utterance {string} the string to be "heard".
     * @param speaker {string} the speakerId to "hear" it.
     * @method module:jibo/asr~spoofUtterance
     * @private
     */
    public spoofUtterance(utterance:string, speaker?:string) {
        let activeActionKeys = Object.keys(ASRVariables.idToAction);
        activeActionKeys.forEach((actionKey) => {
            let data:any = {
                event_type: "speech_to_text_final",
                task_id: actionKey,
                status: "normal",
                message: "spoofed",
                utterances:[{
                    utterance: utterance,
                    score: 1000
                }],
                timestamp: "---",
                message_id: "",
                request_id: actionKey,
                spoofed: true,
                api: 'simplified'
            };
            data.speaker_id = new SpeakerId();
            if(speaker) {
                data.speaker_id.status = "ACCEPTED";
            }
            this.processMessage(data);
        });
    }

    /**
     * Returns enroller which emits enrollment events.
     * @param options {Object} Enroller options.
     * @param options.speakerName {String} name of speaker to enroll.
     * @param options.enrollmentType {enum} 'text-dependent' or 'text-independent'.
     * @returns {module:jibo.services.asr.Enroller} Enroller with given enrollment options.
     * @method module:jibo/asr~createEnroller
     */
    createNameListener(options) {
        let listener = new NameListener(options);
        this.alsaSource.link(listener);
        return listener;
    }

}

export default ASRService;
