import Router = require('router');
import {ServerRequest, ServerResponse} from 'http';
import {ServiceOptions, RegistrationRecord, HTTPService, RegistryClient} from 'jibo-service-framework';

import {createLog} from "../../utils/Log";
let log = createLog("ssm-service-manager");

class SingletonEnforcer{}

class ServiceManager extends HTTPService {

    private static _instance:ServiceManager;

    public services:Array<HTTPService>;

    public static createInstance(options:ServiceOptions, rootDir:string):ServiceManager {
        return new ServiceManager(new SingletonEnforcer(), options, rootDir);
    }

    public static get instance():ServiceManager {
        return ServiceManager._instance;
    }

    constructor(enforcer:SingletonEnforcer, options:ServiceOptions, rootDir:string) {
        super('service-manager', options, rootDir);
        if(ServiceManager._instance) {
            throw new Error('ServiceManager is a singleton');
        }
        ServiceManager._instance = this;

        log.info("Initialized");
    }

    routes(url:Router):void {
        super.routes(url);
        url.get('/', (req:ServerRequest, res:ServerResponse) => {
            RegistryClient.instance.getRecords((err:Error, records:Array<RegistrationRecord>) => {
                let html = '<!doctype html><html><head><title>Skills Service Manager</title></head><body>\n';
                records.forEach( (record:RegistrationRecord) => {
                    if(record.name.indexOf('-service') > 0) {
                        html += `<div><a href="http://${RegistryClient.instance.host}:${record.port}">${record.name}</a></div>\n`;
                    }
                });
                html += '</body></html>\n';
                res.end(html);
            });
        });
        url.get('/test', (req:ServerRequest, res:ServerResponse) => {
            this.sendJson(res, {foo: "bar"});
        });
    }
}

export default ServiceManager;
