import * as ruleGenerator from 'rule-generator';

import * as jibo from 'jibo';

import {createLog} from "../../utils/Log";
import {RegistryClient, RegistrationRecord, WSClient} from "jibo-service-framework";
import ListenService from "../listen-service/ListenService";
const log = createLog("ssm-loop-manager");

export type ErrCallback = (err?:Error)=>void;

const enum SocketState {
    Closed,
    Ready,
    Reconnect
};

enum NLUMessages {
    RESET_MEMORY = <any> "NLU_EXECUTED_RESET_MEMORY"
};

/** Handle loop update events to inform the NLU of all names (and associated ids) of
 * loop members upon startup, and again each time anything in the loop
 * changes.
 *
 * @class NLU Loop Informer - Keep NLU updated with loop members
 */
class NLULoopInformer {
    private rule:string;
    private nluSocketUrl:string;
    private nluSocket:WSClient;
    private socketState:SocketState;

    public init(callback:ErrCallback) {
        this._setupNLULoopStub(() => {
            RegistryClient.instance.getRecords( (err, records:RegistrationRecord[]) => {
                if (err) {
                    callback(err);
                } else if (!records) {
                    callback(new Error('no records from registry'));
                } else {
                    records.forEach( (record) => {
                        if (record.name === 'nlu') {
                            this.nluSocketUrl = `ws://${record.host}:${record.port}/port`;
                        }
                    });
                    this.socketState = SocketState.Closed;
                    this._setupNLUSocket(callback);
                }
            });
        });
        ListenService.instance.on('reload-rules', () => {
            this._reinitLoopRule();
        });
    }


    public update(loop, callback:ErrCallback) {
        let ruleInfoList = [];
        loop.forEach( (user) => {

            let ruleInfo = {
                userId: user._id,
                first_name: (user.data.firstName || '').toLowerCase(),
                last_name: (user.data.lastName || '').toLowerCase(),
                nick_name: (user.data.nickName || '').toLowerCase()
            };

            //log.debug('ruleInfo', ruleInfo);
            ruleInfoList.push(ruleInfo);
        });

        this.rule = ruleGenerator.crew2rule(ruleInfoList);
        //log.debug('rule', rule);

        this._sendRule(this.rule, callback);
    }


    // setup empty static loop/crew rules so the NLU doesn't throw errors if there is no loop
    private _setupNLULoopStub(callback:ErrCallback) {
        let ruleInfoList = [];
        let rule = ruleGenerator.crew2rule(ruleInfoList);
        this._sendRule(rule, callback);
    }


    private _sendRule(rule:string, callback:ErrCallback) {
        let doCrewToo = (err) => {
            // for backwards compatability with older .rule files
            log.iferr(err, 'nlu.compile error compiling "loop" static rule');
            jibo.nlu.compile(rule, done, 'crew');
        };

        let done = (err) => {
            log.iferr(err, 'nlu.compile error compiling "crew" static rule');
            callback(err);
        };

        if (jibo.nlu) {
            jibo.nlu.compile(rule, doCrewToo, 'loop');
        } else {
            log.warn('no jibo.nlu object, no update to NLU done');
            setImmediate(callback);
        }
    }

    private _setupNLUSocket(callback:ErrCallback) {
        if (this.socketState === SocketState.Ready) {
            setImmediate(callback);
        }
        else if (this.socketState === SocketState.Closed) {
            this.nluSocket = new WSClient(this.nluSocketUrl);

            this.nluSocket.on('reopen', () => {
                this.socketState = SocketState.Ready;
                this._reinitLoopRule();
            });

            this.nluSocket.on('error', (err) => {
                this.socketState = SocketState.Reconnect;
            });

            this.nluSocket.on('close', () => {
                this.socketState = SocketState.Reconnect;
            });

            this.nluSocket.on('message', (message) => {
                if(message.Event === NLUMessages.RESET_MEMORY) {
                    this._reinitLoopRule();
                }
            });

            this.nluSocket.once('open', () => {  // note: 'open' also called on automatic reopen
                this.socketState = SocketState.Ready;
                callback();
            });
        }
        else {
            this.nluSocket.once('reopen', callback);
        }
    }

    /**
     * Reupload the loop rule.
     * @method module:skills-service-manager/services/kb-service/NLULoopInformer#_reinitLoopRule
     * @public
     */
    private _reinitLoopRule() {
        if(this.rule) {
            this._sendRule(this.rule, () => {
                // ListenService notifies listeners that NLU loop rule
                // has been restored.
                ListenService.instance.emit('loop-uploaded');
                log.warn("sent rule to nlu");
            });
        }
    }
}


export default NLULoopInformer;
