import jibo = require('jibo');
import ASRService from './clients/asr/ASRService';
import {RegistrationRecord, RegistryClient} from "jibo-service-framework";
import BodyClient from "./clients/BodyClient";

declare type Callback = (err?:Error) => void;

class JiboInitializer {
    public static tts(record:RegistrationRecord):(done:Callback) => void {
        return (done:Callback) => {
            done();
            // jibo.tts.init({
            //     host: RegistryClient.instance.host,
            //     port: record.port
            // }, done);
        };
    }

    public static nlu(record:RegistrationRecord):(done:Callback) => void {
        return (done:Callback) => {
            jibo.nlu.init({
                host: RegistryClient.instance.host,
                port: record.port
            }, done);
        };
    }

    public static asr(record:RegistrationRecord):(done:Callback) => void {
        return (done: Callback) => {
            let asr = ASRService.createInstance();
            asr.init({
                host: RegistryClient.instance.host,
                port: record.port
            }, done);
        };
    }

    public static lps(record:RegistrationRecord):(done:Callback) => void {
        return (done:Callback) => {
            done();
            // jibo.lps.init({
            //     host: RegistryClient.instance.host,
            //     port: record.port
            // }, done);
        };
    }

    public static body(record:RegistrationRecord):(done:Callback) => void {
        return (done:Callback) => {
            BodyClient.createInstance('127.0.0.1', record.port);
            done();
            //not used right now
            // jibo.animUtils.initUtilities(() => {
            //     jibo.animUtils.initOutput({
            //         host: RegistryClient.instance.host,
            //         port: record.port
            //     });
            //     jibo.animUtils.attachOutput();
            //     jibo.animUtils.detachOutput();
            // }, true);
        };
    }
    
    //mapping needs to be initialized after we declare the functions that it will include
    // tslint:disable-next-line: member-ordering
    public static mapping:{[key:string]: Function} = {
        tts: JiboInitializer.tts,
        nlu: JiboInitializer.nlu,
        asr: JiboInitializer.asr,
        lps: JiboInitializer.lps,
        body: JiboInitializer.body
    };
}

export default JiboInitializer;
