import * as request from 'request';
import {WSClient, RegistryClient, RegistrationRecord} from 'jibo-service-framework';

import {createLog} from "../../utils/Log";
const log = createLog("ssm-loop-manager");

const ASR_UPLOAD_GRAMMAR_NAME = 'loop';
const MAX_UPLOAD_ATTEMPTS = 3;
const RETRY_MILLISECONDS = 1000;  // pause between upload attempts


export type ErrCallback = (err?:Error)=>void;

const enum SocketState {
    Closed,
    Ready,
    Reconnect
};


/** Handle loop update events to inform the ASR service of all names
 * (and associated ids) of loop members upon startup, and again each
 * time anything in the loop changes. The ASR uploads the loop member
 * names to Nuance as a custom vocabulary specific to this account.
 *
 * @class ASR Loop Informer - Keep ASR updated with loop members
 */
class ASRLoopInformer {
    private asrSocketUrl;
    private asrUploadVocabUrl;
    private nuanceUserId:string;
    private asrSocket:any;
    private taskId:number;
    private socketState:SocketState;
    private wordUpload:any;
    private pendingWordUpload:any;
    private lastWordUpload:any;
    private uploadAttempts:number;


    public constructor(accountId) {
        this.taskId = 0;
        this.socketState = SocketState.Closed;

        // Compute the Nuance user id from account id:
        // Nuance user ids should be GUIDs without hyphens (string
        // with length 32 consists of hexadecimal numbers).  This is a
        // limitation imposed by Nuance.
        // Use the account id (which is currently only 24 hex characters)
        let nuanceUserId = accountId;
        // strip out anything that isn't a hex character (e.g. '-' if we are using proper GUIDs)
        nuanceUserId = nuanceUserId.replace(/[^A-Fa-f0-9]/g, '');
        // make sure it is 32 characters long
        while (nuanceUserId.length < 32 && nuanceUserId.length > 1) {
            nuanceUserId += nuanceUserId;
        }
        nuanceUserId = nuanceUserId.substr(0, 32);
        this.nuanceUserId = nuanceUserId;
    }


    public init(callback:ErrCallback) {
        RegistryClient.instance.getRecords( (err, records:RegistrationRecord[]) => {
            if (err) {
                callback(err);
            } else if (!records) {
                callback(new Error('no records from registry'));
            } else {
                records.forEach( (record) => {
                    if (record.name === 'asr') {
                        this.asrSocketUrl = `ws://${record.host}:${record.port}/port`;
                        this.asrUploadVocabUrl = `http://${record.host}:${record.port}/upload_interface`;
                    }
                });
                this._setupASRSocket(callback);
            }
        });
    }


    public update(loop, callback:ErrCallback) {
        let newWordUpload = this._buildWordUpload(loop);

        if (!this.wordUpload) {
            this._sendWords(newWordUpload, callback);
        }
        else {
            // in the middle of an upload, server must have restarted
            // queue up the upload to happen after the current one is finished
            this.pendingWordUpload = newWordUpload;
            setImmediate(callback);
        }
    }


    private _buildWordUpload(loop) {
        let loopList = [];
        loop.forEach( (user) => {
            // make sure there is a name (i.e. skip the robot record)
            if (user.data.firstName || user.data.lastName || user.data.nickName) {
                let first_name = (user.data.firstName || '').toLowerCase();
                let last_name = (user.data.lastName || '').toLowerCase();
                // .trim is in case first_name or last_name is blank:
                let full_name = (first_name + ' ' + last_name).trim();
                let nick_name = (user.data.nickName || '').toLowerCase();

                let words = {
                    first_name: first_name,
                    last_name: last_name,
                    full_name: full_name,
                    nick_name: nick_name
                };

                loopList.push(words);
            }
        });

        let wordUpload = {
            task_id: this.nuanceUserId+'.'+this.taskId++,
            command: 'add',
            grammar: ASR_UPLOAD_GRAMMAR_NAME,
            mode: 'full',
            new_checksum: '1',
            old_checksum: '1',
            userid_list: [this.nuanceUserId],
            loop_list: loopList
        };
        log.info('ASR word upload', wordUpload);

        return wordUpload;
    }


    private _sendWords(wordUpload, callback) {
        this.wordUpload = wordUpload;  // also acts as an upload sentinel
        
        this._setupASRSocket( () => {  // make sure the socket is ready in case asr restarted
            this._postWordsToASR(this.wordUpload, (err) => {
                if (!err) {
                    this._waitForOurASRMessage( () => {
                        // save the word upload for asr restarts
                        this.lastWordUpload = this.wordUpload;
                        // finished, clear out the upload sentinel
                        this.wordUpload = null;
                        if (this.pendingWordUpload) {
                            log.info('sending pending ASR word upload');
                            let wordUpload = this.pendingWordUpload;
                            this.pendingWordUpload = null;
                            this._sendWords(wordUpload, callback);
                        }
                        else {
                            callback();
                        }
                    });
                }
                else {
                    callback(err);
                }
            });
        });
    }


    // FIXME SB-2924 ticket for a future refactoring of this so it's not recursive
    private _waitForOurASRMessage(callback) {
        this.asrSocket.once('message', (data) => {
            log.info('message from ASR service:', data);
            if (!data.grammar || data.grammar !== ASR_UPLOAD_GRAMMAR_NAME) {
                // message wasn't for us, ignore it and wait for the next one
                this._waitForOurASRMessage(callback);
            }
            else {
                // grammar matches, this message must be meant for us
                if (data.success === 'success') {
                    log.info('succeeded grammar update task message from ASR:', data);
                    callback(null, data);
                }
                else {
                    log.warn('failed grammar update task message from ASR:', data);
                    this.uploadAttempts = (this.uploadAttempts || 0) + 1;
                    log.warn('ASR word upload attempts: ', this.uploadAttempts);
                    if (this.uploadAttempts < MAX_UPLOAD_ATTEMPTS) {
                        // try again after a short delay
                        setTimeout( () => {
                            log.warn('trying again');
                            this._sendWords(this.wordUpload, callback);
                        }, RETRY_MILLISECONDS);
                    }
                    else {
                        this.uploadAttempts = 0;
                        let err = new Error('giving up on ASR word upload attempts');
                        log.error(err);
                        callback(err);
                    }
                }
            }
        });
    }


    private _setupASRSocket(callback) {
        if (this.socketState === SocketState.Ready) {
            setImmediate(callback);
        }
        else if (this.socketState === SocketState.Closed) {
            this.asrSocket = new WSClient(this.asrSocketUrl);

            this.asrSocket.on('reopen', () => {
                log.warn('reconnected to ASR service');
                this.socketState = SocketState.Ready;
                this._resendWordUpload();
            });

            this.asrSocket.on('error', (err) => {
                log.error('error on ASR service socket:', err);
                this.lastWordUpload = this.wordUpload || this.lastWordUpload;
                this.wordUpload = null;
                this.socketState = SocketState.Reconnect;
            });

            this.asrSocket.on('close', () => {
                log.warn('ASR service closed');
                this.lastWordUpload = this.wordUpload || this.lastWordUpload;
                this.wordUpload = null;
                this.socketState = SocketState.Reconnect;
            });

            this.asrSocket.once('open', () => {  // note: 'open' also called on automatic reopen
                log.info('connected to ASR service');
                this.socketState = SocketState.Ready;
                callback();
            });
        }
        else {
            this.asrSocket.once('reopen', callback);
        }
    }


    private _postWordsToASR(wordUpload, callback) {
        log.info('POSTing word upload to ASR', wordUpload);

        request.post(this.asrUploadVocabUrl, {json:wordUpload}, (err, res, data) => {
            err = this._checkStatusCode(err, res, data);
            if (err) {
                log.error('ASR word upload task POSTing failed!', err);
            }
            else {
                log.info('ASR word upload task finished POSTing');
            }
            // callback(err); // can't do it this way because ASR doesn't complete the POST in time
        });
        callback();  // FIXME workaround.
	// We can't deal with POST errors like this. Basically we
	// can't wait to see if there is is an error because the call
	// won't complete until *after* ASR has acted on the task and
	// already sent the socket response message, which is too late
	// for us to setup our event in the callback to watch for it.
	// That also means we can't tell if our POST might have failed
	// because the ASR service was down during a restart.
	//
	// If we get a loop update during an ASR restart callbacks
	// won't be called. And Loop updates will stop.
        //
        // See SB-2827, SB-2828
    }


    private _resendWordUpload() {
        if (this.lastWordUpload) {
            log.info('resending last word upload...');
            this._sendWords(this.lastWordUpload, () => {
                log.info('done resending last word upload');
            });
        }
    }


    /** Check http request result for null error object and 2xx result code and
     * generate an error object if not (or pass through non null error object).
     *
     * @param {Error} err Error object returned from request.
     * @param {Object} res Http request result object.
     * @param {string} [message] Message to add to error object.
     * @returns {Error} Error object or null.
     * @private
     */
    private _checkStatusCode(err:Error, res, message:string=null):Error {
        if (!err) {  // game over if we already have an err
            if (res.statusCode < 200 || res.statusCode > 299) {
                let description = 'HTTP Error Code '+res.statusCode;
                if (message) {
                    description += message;
                }
                err = new Error(description);
            }
        }
        return err;
    }
}


export default ASRLoopInformer;
