import * as path from 'path';
import * as fs from 'fs';
import jibo = require('jibo');
import async = require('async');
import SkillsService from '../skills-service/SkillsService';
import md5 = require('md5');
import {ParseResults} from 'jibo-common-types';

declare type Callback = (error:Error|string, result?:string | ParseResults) => void;

/**
 * @description
 * Rule Manager.
 * Manages the caching and memory clearing of the Listen Service through communication with
 * the parser (on robot). Manages caching, retrieving, and parsing from different rule file types.
 * @module skills-service-manager/services/listen-service/RuleManager
 */
export class RuleManager {

    public static get instance() {
        if(!RuleManager._instance) {
            RuleManager._instance = new RuleManager();
        }
        return RuleManager._instance;
    }

    private static _instance:RuleManager;
    private cachePerformanceTimestamp = 0;
    // Use the user's local Jibo folder when running in the simulator or during tests.
    private FST_CACHE_DIR = fs.existsSync('/var/jibo') ? '/var/jibo' : path.join(process.env.HOME || process.env.USERPROFILE, '.jibo');

    // Map a rule file path to a handle for the compiled rule.
    private _uriCache = new Map<string, string>();

    constructor() {
        if(RuleManager._instance) {
            throw new Error('RuleManager is a singleton');
        }
        RuleManager._instance = this;
    }

    /**
     * Retrieves either cached or compiles new URI for NLU file
     * @param {String} nluPath Path to NLU file
     * @returns {Promise} Resolved when uri compiled
     */
    public getNluUri(nluPath:string, callback:Callback):void {
        nluPath = path.resolve(nluPath);
        // See if we already have cached the rule uri for this
        if(this._uriCache.has(nluPath)) {
            callback(null, this._uriCache.get(nluPath));
        }
        else {
            this._compileNLUFromPath(nluPath, callback);
        }
    }

    /**
     * Size of URI cache
     * @returns {number}
     */
    public size() {
        return this._uriCache.size;
    }

    /**
     * TOFIX
     * This is not implemented in the SDK layer yet so we can't do it still
     * @param {String} [nluRulePath] The path to the rule to remove from
     * cache. If none is provided, we clear all
     * @returns {Promise}
     */
    public clearCache(nluRulePath?:string):void {
        if (nluRulePath) {
            nluRulePath = path.resolve(nluRulePath);
            this._uriCache.delete(nluRulePath);
        }
        else {
            this._uriCache = new Map<string, string>();
        }
    }

    public getUriFromText(ruleText:string, callback:Callback, uri?:string):void {
        jibo.nlu.compile(ruleText, (error:string, result) => {
            if (error) {
                callback(error);
            }
            else {
                callback(null, result);
            }
        });
    }

    /**
     * Get the rule URI from an FST file.
     * @param {String} fstUri to use as handle to rule (which is actually the filename in this case).
     * @param {Function} callback for once rule is compiled.
     * @method module:skills-service-manager/services/listen-service/RuleManager#getUriFromFst
     */
    public getUriFromFst(fstUri:string, callback:Callback, uri?:string):void {
        // path.resolve() will resolve to /usr/local/bin/jibo-ssm...
        // need to resolve to skill path.
        let fstPath;
        if(path.isAbsolute(fstUri)) {
            fstPath = fstUri;
        }
        else {
            fstPath = path.join(SkillsService.instance.currentSkill.path, fstUri);
        }

        // See if we already have cached the rule uri for this
        if (this._uriCache.has(fstUri)) {
            callback(null, this._uriCache.get(fstUri));
            return;
        }
        this.compileFromFst(fstUri, fstPath, callback);
    }

    /**
     * Compile a rule from an FST path with a given URI.
     * @param {String} fstUri to use as handle to rule
     * @param {String} fstPath absolute path on disk to fst file to compile.
     * @param {Function} callback returning the handle for the compiled rule.
     * @method module:skills-service-manager/services/listen-service/RuleManager#compileFromFst
     */
    public compileFromFst(fstUri:string, fstPath:string, callback:Callback) {
        jibo.nlu.compileFromFst(fstPath, (error, result) => {
            if (error) {
                callback(error);
            }
            else {
                this._uriCache.set(fstUri, result);
                callback(null, result);
            }
        }, fstUri);
    }

    /**
     * Parses text against a possibly cached rule file
     * @param {String} text
     * @param {String} nluPath
     * @method module:skills-service-manager/services/listen-service/RuleManager#parseFromRulePath
     */
    public parseFromRulePath(text:string, nluPath:string, callback:Callback):void {
        this.getNluUri(nluPath, (error:Error, uri:string) => {
            if(error) {
                return callback(error);
            }
            this.parseFromUri(text, uri, callback);
        });
    }

    /**
     * Parses text against an NLU rule
     * Notice that this does not cache anything but recompiles the rule on
     * every call
     * @param {String} text Text to parse
     * @param {String} nluRule The text content of a rule
     * @method module:skills-service-manager/services/listen-service/RuleManager#parseFromNlu
     */
    public parseFromNlu(text:string, nluRule:string, callback:Callback):void {
        jibo.nlu.parseFromRule(nluRule, text, (error, result) => {
            if (error) {
                callback(error);
            }
            else {
                callback(null, result);
            }
        });
    }

    /**
     * Parses text against an NLU rule
     * Notice that this does not cache anything but recompiles the rule on
     * every call
     * @param {String} text Text to parse
     * @param {String} nluRule The text content of a rule
     * @method module:skills-service-manager/services/listen-service/RuleManager#parseFromFst
     */
    public parseFromFst(text:string, fstUri: string, callback:Callback) :void {
        jibo.nlu.parseFromFile(fstUri, text, (error, result) => {
            if (error) {
                 callback(error);
            }
            else {
                callback(null, result);
            }
        });
    }

    /**
     * Parses text against an URI representing a compiled rule
     * @param {String} text the text to parse
     * @param {String} nluURI a URI for a compiled grammar.
     * @method module:skills-service-manager/services/listen-service/RuleManager#pasreFromUri
     */
    public parseFromUri(text:string, nluURI:string, callback:Callback):void {
        jibo.nlu.parseFromURI(nluURI, text, (error, result) => {
            if (error) {
                callback(error);
            }
            else {
                callback(null, result);
            }
        });
    }

    /**
     * Create a filename to cache the FST produced from the given rulePaths that is
     * unique, based on their names and creation times.
     * @param {string []} rulePaths the list of files being used for the final FST
     * @returns {string} the unique cache file name
     */
    public createCacheFilenameFromRulePaths(rulePaths:string[]) {
        let hashInput = '';
        for (let rulePath of rulePaths) {
            let stats = fs.statSync(rulePath);
            // The key is a concatenation of the file names and the file modification times
            hashInput += `${rulePath}:${stats.mtime.getTime()},`;
        }
        const md5sum = md5(hashInput);
        return `${this.FST_CACHE_DIR}/${md5sum}-cache.fst`;
    }

    /**
     * Look for an FST file on disk that corresponds to the given set of rule paths.
     * If found, compile it into a URI and return it via the callback.
     * @param {string []} rulePaths list of rules to be found in cache.
     * @param {function} callback called with (error, uri) if successfully found in cache.
     * @param {string} [desiredUri] rule URI handle to assign to compiled result
     * @returns {boolean} true if previously compiled FST file was found.
     */
    public foundInRulePathsCache(rulePaths:string[], callback:Callback, desiredUri:string):boolean {
        const filename = this.createCacheFilenameFromRulePaths(rulePaths);
        try {
            fs.accessSync(filename, fs.F_OK);
            jibo.nlu.compileFromFst(filename, (err, result) => {
                console.log(`Fetched and compiled ${filename} in ${(Date.now() - this.cachePerformanceTimestamp)/1000.0} seconds`);
                callback(err, result);
            }, desiredUri);
            return true;
        } catch (e) {
            return false;
        }
    }

    /**
     * Given a list of rules files and a handle to their compiled form, save the compiled form to the cache.
     * @param {string []} rulePaths List of rules files that generated the fst to be saved.
     * @param {string} uri handle to compiled FST
     * @param {function} callback called with (error, result) when save operation completes.
     */
    public addToRulePathsCache(rulePaths:string[], uri:string, callback:Callback):string {
        const filename = this.createCacheFilenameFromRulePaths(rulePaths);
        this.saveToDisk(uri, filename, (err) => {
            if (err) {
                console.error(`addToFstFileCache failed: ${err}`);
            }
            callback(err, uri);
        });
        // Whenever we add an entry we prune the cache back to 6 entries.
        this.pruneRulePathsCache(6);
        return filename;
    }

    /**
     * Clean the FST cache, keeping only the given number of most recently used entries.
     * @param {number} numberToKeep the number of entries to be retained after cleaning.
     */
    public pruneRulePathsCache(numberToKeep) {
        fs.readdir(this.FST_CACHE_DIR, (err, items) => {
            let files = [];
            for (let item of items) {
                if (item.endsWith('-cache.fst')) {
                    const filename = this.FST_CACHE_DIR + '/' + item;
                    files.push({filename, accessTime: fs.statSync(filename).atime.getTime()});
                }
            }
            // sort the list into most-recently-accessed-first order
            files.sort((a, b) => b.accessTime - a.accessTime);
            for (let i = numberToKeep; i < files.length; i++) {
                console.log(`cleanFstCache: removing ${files[i].filename}`);
                fs.unlink(files[i].filename);
            }
        });
    }

    /**
     * Given a set of rule paths, produce a single URI "handle" representing their compiled grammar.
     * When complete, call the callback with a URI "handle" to the compiled FST.
     * @param {Array<string>} rulePaths to combine
     * @param {Callback} callback once rules are combined.
     * @param {Boolean} ignoreErrors ignore errors from NLU Service
     * @method module:skills-service-manager/services/listen-service/RuleManager#combineRulesFromPaths
     */
    // Being kept for compatibility with third party code. No internal code uses this. -eaw
    public combineRulesFromPaths(rulePaths:string[], callback:Callback, ignoreErrors:boolean = false):void {
        this.getUriFromRulePaths(rulePaths, callback, {ignoreErrors});
    }

    /**
     * Given a set of rule paths get a single URI "handle" representing a grammar that is their union.
     *
     * First check to see if the grammar associated with those paths is cached to disk.
     * If it isn't, compile each rule file into a URI and then "union" those URIs to produce a
     * final URI for the entire set. Finally, cache the binary grammar behind the final URI to disk.
     *
     * When complete, call the callback with a URI "handle" to the unioned grammar.
     *
     * @param {Array<string>} rulePaths to combine
     * @param {Callback} callback once rules are combined.
     * @param {any} [options]
     * ignoreErrors: ignore errors from NLU Service,
     * desiredUri: handle to assign to final compiled grammar.
     * @method module:skills-service-manager/services/listen-service/RuleManager#getUriFromRulePaths
     */

    public getUriFromRulePaths(rulePaths:string[], callback:Callback, options:any = {}):void {
        this.cachePerformanceTimestamp = Date.now();
        if (this.foundInRulePathsCache(rulePaths, callback, options.desiredUri)) {
            return;
        }
        let uris:string[] = [];
        let tasks:Array<AsyncFunction<string>> = [];
        rulePaths.forEach((rulePath:string):void => {
            tasks.push((done:(error?:Error|string) => void):void => {
                this.getNluUri(rulePath, (error, uri:string) => {
                    if(error) {
                        if (options.ignoreErrors) {
                            console.error(`${rulePath} rule failed to compile: `, error);
                            return done();
                        }
                        return done(error);
                    }
                    uris.push(uri);
                    done();
                });
            });
        });
        async.parallel(tasks, (error) => {
            if((error && !options.ignoreErrors) || uris.length === 0) {
                return callback(error || 'No launch rules compiled successfully');
            }
            jibo.nlu.union(uris, (err, uri:string) => {
                if (err) {
                    console.error(`getUriFromRulePaths: Failed to unionize: ${rulePaths.join('\n')}`);
                    callback(err);

                } else {
                    let filename = this.addToRulePathsCache(rulePaths, uri, callback);
                    console.log(`Compiled from sources to ${filename} in ${(Date.now() - this.cachePerformanceTimestamp)/1000.0} seconds`);
                }
            }, options.desiredUri);
        });
    }

    /**
     * Save a URI to a given filepath on disk.
     * @param {String} uri of rule to save
     * @param {String} filepath to save uri to
     * @method module:skills-service-manager/services/listen-service/RuleManager#saveToDisk
     */
    public saveToDisk(uri:string, filePath:string, callback:Callback):void {
        jibo.nlu.saveFstOnDisk(uri, filePath, (error, result) => {
            if (error) {
                callback(error);
            }
            else {
                callback(null, result);
            }
        });
    }

    /**
     * Reset memory within NLU Service
     * @param {Function} Callback for once memory has been reset.
     * @method module:skills-service-manager/services/listen-service/RuleManager#resetMemory
     */
    public resetMemory(callback:Callback):void {
        jibo.nlu.resetMemory((error, result) => {
            if (error) {
                callback(error);
            }
            else {
                callback(null, result);
            }
        });
    }

    /**
     * Loads a rule file from path and returns promise with the URI
     * @param rulePath
     * @param callback
     * @method module:skills-service-manager/services/listen-service/RuleManager#_compileNLUFromPath
     * @private
     */
    private _compileNLUFromPath(rulePath:string, callback:Callback):void {
        fs.readFile(rulePath, 'utf8', (error, fileCont) => {
            if (error) {
                callback(error);
            }
            else {
                jibo.nlu.compile(fileCont, (error, result) => {
                    if (error) {
                        //replace default unhelpful paths with actual paths
                        if (typeof error === 'string') {
                            error = error.replace(/\\\/dummypath\\\/dummyfile\.rule/g, rulePath);
                        }
                        callback(error);
                    }
                    else {
                        this._uriCache.set(rulePath, result);
                        callback(null, result);
                    }
                });
            }
        });
    }
}

export default RuleManager;