import {EventEmitter} from 'events';
import ASRService from './ASRService';
import { UrlInterface } from './ASRService';
import AudioAction from './AudioAction';
import {PronunciationOptions} from 'jibo-common-types';
let uuid = require('uuid');

/**
 * This constructs a listener specific to pronunciation.
 *
 * @param options {Object} Listen options
 * @returns {module:jibo.services.asr.NameListener} Listener with given recognition options
 *
 * @class NameListener
 * @extends {EventEmitter}
 * @memberof module:jibo.services.asr
 */

class NameListener extends EventEmitter {

    /**
     * ID to be mapped with GL listener
     * @name NameListener#listenerId
     * @type {String}
     */
    public listenerId:string = uuid.v4();

    public word: string;
    private verbose: boolean;
    /**
     * Audio source ID to send with old ASR listener task
     * @name NameListener~audioSourceId
     * @type {String}
     * @private
     */
    private audioSourceId: string;
    /**
     * Action which generates the grapheme2phoneme model with cloud request
     * @name NameListener~g2pAction
     * @type {AudioAction}
     * @private
     */
    private g2pAction:AudioAction;
    /**
     * Action which calls for acoustic example with cloud request
     * @name NameListener~nameLearningAction
     * @type {AudioAction}
     * @private
     */
    private nameLearningAction: AudioAction;

    constructor(options:PronunciationOptions){
        super();
        /**
         * Word that will be sent to get g2p and acoustic example
         * @name NameListener#word
         * @type {String}
         * @pubic
         */
        this.word = options.word;
        /**
         * Verbose to provide useful debug information through SSM console
         * @name NameListener~verbose
         * @type {Boolean}
         * @private
         */
        this.verbose = options.verbose || false;
    }

    /**
     * link listener to audio source
     * @method module:jibo.services.asr.NameListener#onFinished
     * @private
     */
    setAudioSourceId(id:string) {
        this.audioSourceId = id;
    }

    /**
     * immediately stop the recognition task
     * @method module:jibo.services.asr.NameListener#onFinished
     * @private
     */
    onFinished() {
        // If we've only done g2p, we won't have a name learning action to stop.
        if(this.nameLearningAction) {
            this.nameLearningAction.stopOldTask(() => {
                this.nameLearningAction.clearOldTask(() => {
                    this.emit('finished');
                });
            });
        }
        /**
         * This is the last event to be fired.
         * @event module:jibo.services.asr.NameListener#finished
         */
        // ASRService.instance.pronunAction = null;
    }

    /**
     * Begins recognition task of listener.
     * @method module:jibo.services.asr.NameListener#start
     * @returns {Boolean} true if start was successful, false otherwise
     * @public
     */
    start() {
        // Alaways send task ID of 0 here to address bug in g2p // ASR Service
        // TODO: take this out and send regular task ID when bug is fixed in plat.
        this.g2pAction = ASRService.instance.createAudioAction(UrlInterface.PRONUN, "0");
        this.g2pAction.on('error', (message) => {
            this.emit('error', message);
        });
        this.g2pAction.on('got-pronunciations', (pronunciations) => {
            if(this.verbose) {
                console.log("generated pronunciations g2p in name listener ", pronunciations);
            }
            this.emit('generated-pronun', pronunciations);
            // Don't worry about stopping or anything here.
            // Separate ASR interface.
        });
        this.g2pAction.on('pronun-error', (pronun) => {
            this.emit('pronun-error', pronun);
            // Don't worry about stopping or anything here.
        });

        this.g2pAction.generateGraphemeToPhoneme(this);

        return true;
    }

    /**
     * Starts collecting the acoustic example with old ASR service
     * @method module:jibo.services.asr.NameListener#collectExample
     * @void
     * @public
     */
    collectExample() {
        let nameReco = new ASRService.instance.NameRecognizer(this.word);
        let task = nameReco.pack();

        this.nameLearningAction = ASRService.instance.createAudioAction(UrlInterface.OLD);
        this.nameLearningAction.on('got-pronunciations', (pronunciations) => {
            if(this.verbose) {
                console.log("got pronunciations in name listener ", pronunciations);
            }
            if(pronunciations.success) {
                this.emit('heard-pronun', pronunciations);
            }
        });
        this.nameLearningAction.on('pronun-error', (pronun) => {
            this.emit('pronun-error', pronun);
            // Error means we'll need to make a new one.
            this.onFinished();
        });
        this.nameLearningAction.on('finished', () => {
            this.onFinished();
        });

        this.nameLearningAction.startOldTask(task);
    }

    /**
     * explicit call to stop the listener and recognition task.
     * NameListener can still be restarted, but regardless of where
     * listener was in task, no more events will be emitted.
     * Listeners are no longer subscribed.
     * @method module:jibo.services.asr.NameListener#stop
     * @public
     */
    stop() {
        this.onFinished();
    }
}

export default NameListener;