class BackgroundUtilsManager {
    private initFunctions:{[id:string]:(robotMode?:string)=>void} = {};
    private initialized:Boolean = false;
    
    public register(callback:(robotMode?:string)=>void, id:string) {
        if (this.initialized) {
            console.warn(`BackgroundUtilsManager is registering ${id} after initialization. Please consider how/when code is being included.`);
            callback();
        }
        if (this.initFunctions.hasOwnProperty(id)) {
            console.error(`BackgroundUtilsManager is registering ${id} when that id has already been used. This callback will not be called.`);
            return;
        }
        this.initFunctions[id] = callback;
    }
    
    public initAll(mode:string) {
        const ids = Object.keys(this.initFunctions);
        for(let i = 0; i < ids.length; ++i) {
            const id = ids[i];
            const callback = this.initFunctions[id];
            try {
                callback(mode);
            } catch (e) {
                console.error(`Error when initializing ${id}:`);
                //log error in red, but without adding the stack trace from console.error
                console.log('%c', 'color:red', e);
            }
        }
    }
}

export default new BackgroundUtilsManager();