import WifiService from '../../services/wifi-service/WifiService';
import querystring = require('querystring');

//keys are currently free level keys set up by Andrew Start for testing purposes, and should be
//replaced by Jibo owned ones
const GEOCODE_API = 'AIzaSyAq77uInf4VPUr2Kw1rDdPXe_giV_Tyhp8';
const GEOLOCATION_API = 'AIzaSyABiyOf9g4j-p7PzZXOFJmsDF6ox6qFC3A';

export interface LocationData {
    city?:string;
    state?:string;
    stateAbbr?:string;
    country?:string;
    lat:number;
    lng:number;
}

export function getLocation():Promise<LocationData> {
    return getNetworks()
        .then((networkList) => {
            return getLocationFromGoogle(networkList);
        });
}

function getLocationFromGoogle(networkList:string[]):Promise<LocationData> {
    return new Promise((resolve, reject) => {
        const wifiAccessPoints = [];
        for (let i = 0; i < networkList.length; ++i) {
            if (!networkList[i]) {
                continue;
            }
            const scan = networkList[i].split(/\s+/);
            wifiAccessPoints.push({
                macAddress: scan[0],
                signalStrength: parseInt(scan[2])
            });
        }
        //considerIp defaults to true, but just to be safe
        const body = {wifiAccessPoints, considerIp:true};
        const query = querystring.stringify({key:GEOLOCATION_API});
        const url = `https://www.googleapis.com/geolocation/v1/geolocate?${query}`;
        const request:XMLHttpRequest = new XMLHttpRequest();
        request.responseType = 'json';
        request.timeout = 10000;
        request.addEventListener('timeout', () => { reject('XHR Timeout'); }, false);
        request.addEventListener('error', () => { reject('XHR Error'); }, false);
        request.addEventListener('abort', () => { reject('XHR Aborted'); }, false);
        request.addEventListener('load', () => {
            if (request.status === 200) {
                const location = request.response.location;
                resolve(geocodeWithGoogle(location.lat, location.lng));
            } else {
                if (request.response && request.response.error) {
                    reject(request.response.error.message);
                } else {
                    reject('Invalid response');
                }
            }
        }, false);
        request.open('POST', url, true);
        request.setRequestHeader("Content-Type", "application/json;charset=UTF-8");
        request.send(JSON.stringify(body));
    });
}

function geocodeWithGoogle(lat:number, lng:number):Promise<LocationData> {
    return new Promise<LocationData>((resolve, reject) => {
        const query = querystring.stringify({
            key:GEOCODE_API,
            latlng: `${lat},${lng}`
        });
        const url = `https://maps.googleapis.com/maps/api/geocode/json?${query}`;
        const request:XMLHttpRequest = new XMLHttpRequest();
        request.responseType = 'json';
        request.timeout = 10000;
        request.addEventListener('timeout', () => { reject('XHR Timeout'); }, false);
        request.addEventListener('error', () => { reject('XHR Error'); }, false);
        request.addEventListener('abort', () => { reject('XHR Aborted'); }, false);
        request.addEventListener('load', () => {
            if (request.status === 200) {
                let finalLocation:LocationData = {
                    lat,
                    lng
                };
                const results = request.response.results;
                //go through the results to find the best one
                for (let i = 0; i < results.length; ++i) {
                    const locTypes:string[] = results[i].types;
                    if (locTypes.indexOf('street_address') === -1 &&
                        locTypes.indexOf('political') === -1) {
                        //if the location is not a street address or town, we will ignore it
                        //in favor of another result, just for safety
                        continue;
                    }
                    //go through the list and find the location components we care about
                    const components = results[i].address_components;
                    for (let j = 0; j < components.length; ++j) {
                        const types = components[j].types;
                        if (types.indexOf('sublocality') !== -1) {
                            finalLocation.city = components[j].long_name;
                            continue;
                        }
                        if (types.indexOf('locality') !== -1) {
                            finalLocation.city = components[j].long_name;
                            continue;
                        }
                        if (types.indexOf('administrative_area_level_1') !== -1) {
                            finalLocation.state = components[j].long_name;
                            finalLocation.stateAbbr = components[j].short_name;
                            continue;
                        }
                        if (types.indexOf('country') !== -1) {
                            finalLocation.country = components[j].long_name;
                            //special case this one to match older code/NLU results
                            if (finalLocation.country === 'United States') {
                                finalLocation.country = 'usa';
                            }
                            continue;
                        }
                    }
                    //since we got a (presumably) good result, skip looking at the rest of the results
                    break;
                }
                resolve(finalLocation);
            } else {
                if (request.response && request.response.error) {
                    reject(request.response.error.message);
                } else {
                    reject('Invalid response');
                }
            }
        }, false);
        request.open('GET', url, true);
        request.send();
    });
}

function getNetworks():Promise<string[]> {
    return new Promise<string[]>((resolve, reject) => {
        WifiService.instance.getScanResults((error:Error, data:Array<string>) => {
            if(error) {
                reject(error);
            }
            else {
                resolve(data);
            }
        });
    });
}
