import {
    StateMachine,
    State,
} from 'jibo-state-machine';

import {
    _GlobalListen
} from '../GlobalListen';

import {ListenResults} from "jibo-common-types";


export default class InterruptNonHJListenersState extends State {

    constructor(sm: StateMachine, name: string, private nextState: State) {
        super(sm, name);
    }

    create(gl: _GlobalListen) {
        this.addDoneTransition(this.nextState);

        this.onEntry = (trans, result) => {
            const listenResult = result as ListenResults;
            gl._activeNonHJListeners.forEach((listener) => {
                // we remove dialog listeners here because they're interrupted.
                listener.events.interrupted.emit(listenResult);
                gl.removeDialogListener(listener);
            });
        };
    }
}
