import findRoot = require('find-root');
import path = require('path');
import fs = require('fs');

/**
 * @description
 * An instance of the NLU Parser specifically compiled for the simulated platform.
 * @module skills-service-manager/services/nlu-service/Parser
 */
class Parser {

    public nlu:NLU;

    constructor() {
        let root: string = path.join(findRoot(__dirname));
        let parserJiboPath: string = path.join(root, 'parser/build/Release/jsjibonlu.jibo');
        let parserNodePath: string = path.join(root, 'parser/build/Release/jsjibonlu.node');
        if (fs.existsSync(parserJiboPath)) {
            fs.renameSync(parserJiboPath, parserNodePath);
        }

        try {
            this.nlu = require(parserNodePath);
            let dataDirectory: string = path.join(root, 'parser', 'deps', 'data');
            this.nlu.set_data_dir(dataDirectory);
        }
        catch (e) {
            console.error(e);
            this.nlu = undefined;
        }
    }

}

export default Parser;