import * as uuid from 'uuid';
import ASRVariables from './ASRVariables';

class AudioSource {

    private id:string;
    private source:string;
    private wavFiles: Array<any>;
    private audioUrl: string;
    
    constructor(url, wavFiles?) {
        let source = 'alsa';
        if(Array.isArray(wavFiles) && wavFiles.length > 0) {
            source = 'wav';
        }
        else if(typeof(wavFiles) === 'string') {
            source = 'wav';
            wavFiles = [wavFiles];
        }
        this.id = 'source-' + uuid.v4();
        ASRVariables.idToAudioSource[this.id] = this;
        // source is 'alsa' | 'wav'
        this.source = source;
        this.wavFiles = wavFiles || [];
        this.audioUrl = url;
    }

    init(cb) {
        let body:any = {
            action: 'start',
            audio_source_id: this.id,
            audio_source: this.source,
            wav_files: this.wavFiles
        };
        body = JSON.stringify(body);
        let request = new XMLHttpRequest();
        request.open("POST", this.audioUrl, true);
        request.onreadystatechange = () => {
            if(request.readyState === 4 && (request.status === 204 || request.status === 200)) {
                cb();
            }
            else if(request.readyState === 4 && request.status === 0) {
                cb('Could not create audio channel');
            }

        };
        request.send(body);
    }

    destroy(cb) {
        let body:any = {
            action: 'stop',
            audio_source_id: this.id,
            audio_source: this.source,
            wav_files: []
        };
        body = JSON.stringify(body);
        let request = new XMLHttpRequest();
        request.open("POST", this.audioUrl, true);
        request.onreadystatechange = () => {
            if(request.readyState === 4 && (request.status === 204 || request.status === 200)) {
                cb();
            }
            else if(request.readyState === 4 && request.status === 0) {
                cb('Could not destroy audio channel');
            }

        };
        request.send(body);        
    }

    link(action) {
        action.setAudioSourceId(this.id);
    }
}

export default AudioSource;