import {ServiceOptions, HTTPWSService, JiboServerRequest, JiboServerResponse} from 'jibo-service-framework';
import Router = require('router');
import WebSocket = require('ws-without-native');

interface IPerformanceService {
    log(time:number, type:string, description?:string):void;
    init(callback:(error?:Error) => void):void;
}

//we want to stub out this service if the configuration does not call for it.
class PerformanceServiceSim implements IPerformanceService {
    private static _instance:PerformanceServiceSim;

    public static get instance():IPerformanceService {
        if(!PerformanceServiceSim._instance) {
            PerformanceServiceSim._instance = new PerformanceServiceSim();
        }
        return PerformanceServiceSim._instance;
    }

    init(callback:(error?:Error) => void):void {
        callback();
    }

    log(time:number, type:string, description?:string):void {
        return;
    }
}

class PerformanceService extends HTTPWSService implements IPerformanceService {

    private static _instance:PerformanceService;

    public static createInstance(options:ServiceOptions, rootDir:string):PerformanceService {
        return new PerformanceService(options, rootDir);
    }

    public static get instance():IPerformanceService {
        if(PerformanceService._instance) {
            return PerformanceService._instance;
        }
        return PerformanceServiceSim.instance;
    }

    constructor(public options:ServiceOptions, rootDir:string) {
        super('performance', options, rootDir);
        if(PerformanceService._instance) {
            throw new Error('PerformanceService is a singleton');
        }
        PerformanceService._instance = this;
    }

    public init(callback:(error?:Error) => void):void {
        super.init((error:Error) => {
            if(error) {
                return callback(error);
            }
            callback();
        });
    }

    public routes(url:Router):void {
        super.routes(url);

         url.post('/log', (req:JiboServerRequest, res:JiboServerResponse) => {
             let chunk = "";
             req.on('data', data => chunk += data);
             req.on('end', () => {
                let data;
                try {
                    data = JSON.parse(chunk);
                    this.log(data.time, data.type, data.description);
                    this.sendJson(res, {status: 'OK'});
                }
                catch(e) {
                    console.warn('Performance service cannot parse ', chunk);
                    this.sendJson(res, {status: 'error', message: 'could not parse json', json: chunk}, 400);
                }
             });
         });
    }

    public log(time:number, type:string, description?:string):void {
        this.connections.forEach((client:WebSocket) => {
            this.sendWsJson(client, {
                time,
                type,
                description: description ? description : ''});
        });
    }

    /*
     * Get the high precision time in milliseconds since the epoch
     */
    public now(){
        return performance.timing.navigationStart + performance.now();
    }

    protected onMessage(message:any, client:WebSocket):void {
        console.log("PerformanceService.onMessage", message);

        // Listen for time pings and respond with a local time stamp
        // This is used for basic time synchronization between the devices
        // of client's of the performance service and it's own device
        // This should be used by clients to implement Christian's clock synchronization Algorithm:
        // https://en.m.wikipedia.org/wiki/Cristian%27s_algorithm
        if(message.type === "time-ping"){
            // We respond using the log call so that you see time sync pings in the performance service
            // and connected clients get the time-pong response
            this.sendWsJson(client, {
                time: this.now(),
                type: "time-pong",
                // Send it's description back as it should include a unique ping id
                description: message.description
            });
        }
    }
}

export default PerformanceService;
