import {EventEmitter} from 'events';
import AudioAction from './AudioAction';
import { ActionStatus } from './AudioAction';
import {SpeakerId, ListenResults, ASRRequestOptions} from 'jibo-common-types';
import ASRService from "./ASRService";
import {ASRData} from "./ASRService";


/**
 * This constructs a listenr. 
 * 
 * @param options {Object} Listen options
 * @param options.heyJibo {Boolean} true if listen for "Hey, Jibo"
 * @param options.speech_to_text {Boolean} true if listen for cloud STT results
 * @param options.incremental {Boolean} true if listen for incremental results
 * @param options.authenticateSpeaker {String} name of speaker, if applicable
 * @param options.precompiledHandle {String} handle id of a precompiled rule file
 *                          through nlu service. Bypasses all rule compilation. 
 * @param options.parseIncremental {Boolean} false to bypass parsing incremental results
 * @param options.parseFinal {Boolean} false to bypass parsing final STT results
 * @param options.metadata {any} metadata for ASR service to process.
 * @returns {module:jibo.services.asr.Listener} Listener with given recognition options
 * 
 * ```
 * this.listener = asr.createListener(options, rule);
 * this.listener.start();
 * ```
 * Listener will start emitting events. Possible events are: 
 * ```
 * this.listener.on('cloud', (result) => {
 *      // Use the final recognition jibo hears
 * });
 * ```
 * Where result is the {asrResult} with Input and NLParse fields if a rule
 * file was supplied to the listener.
 * 
 * ```
 * this.listener.on('incremental', (result) => {
 *      // use incremental speech results
 * });
 * ```
 * Where result is the {asrResult} with Input and incremental NLParses. 
 * 
 * ```
 * this.listener.on('embedded', (result) => {
 *      // use embedded recognition event
 * });            
 * this.listener.on('speech-end', () => {
 *      // use the end of speech event
 * });            
 * this.listener.on('speech-start', () => {
 *      // use the end of speech event
 * });            
 * this.listener.on('error', (error) => {
 *      // do things
 * });     
 * this.listener.on('finished', () => {
 *      // do things
 *      this.listener.removeAllListeners();
 *      this.listener.stop();
 * }); 
 * ```
 * @class Listener
 * @extends {EventEmitter}
 * @memberof module:jibo.services.asr
 */
class Listener extends EventEmitter {

    /**
     * Audio Action to send requests through to ASR Service
     * @name module:skills-service-manager/listen-service/Listener#action
     * @type {AudioAction}
     * @private
     */
    private action:AudioAction;
    /**
     * ID of listener
     * @name module:skills-service-manager/listen-service/Listener#id
     * @type {string}
     * @private
     */
    private id:string;
    /**
     * Indicates we have received a hotphrase response from ASR for this listener.
     * @name module:skills-service-manager/listen-service/Listener#_hasHotphrase
     * @type {boolean}
     * @private
     */
    private _hasHotphrase:boolean;
    /**
     * Indicates we have received a speaker_id response from ASR for this listener.
     * @name module:skills-service-manager/listen-service/Listener#_hasSpeakerId
     * @type {boolean}
     * @private
     */
    private _hasSpeakerId:boolean;
    private options:ASRRequestOptions;
    private stopCallbacks: Array<Function>;
    private status:string;
    /**
     * Options for making the ASR request
     * @name module:skills-service-manager/listen-service/Listener#rule
     * @type {string}
     * @private
     */
    private task:ASRRequestOptions = new ASRRequestOptions({});

    constructor(options:ASRRequestOptions){
        super();
        /**
         * Options to listen for in ASR Request.
         * @name module:skills-service-manager/listen-service/Listener#options
         * @type {ASRRequestOptions}
         * @private
         */
        this.options = options;
        /**
         * Status of listener
         * @name module:skills-service-manager/listen-service/Listener#status
         * @type {string}
         * @private
         */
        this.status = "INVALID";
        /**
         * Callbacks subscribed waiting for listener to stop
         * @name module:module:skills-service-manager/clients/asr.Listener#stopCallbacks
         * @type {Array<Funcion>}
         * @private
         */
        this.stopCallbacks = [];
    }

    /**
     * Begins recognition task of listener. 
     * Once started, the listener will emit events such as:
     * cloud, incremental, end, error (depending on constructor options)
     * returns true if listen successfully started,
     * emits error and returns false if task is already in progress.
     * @method module:jibo.services.asr.Listener#start
     * @returns {Boolean} true if start was successful, false otherwise
     * @public
     */
    start() {
        let options:ASRRequestOptions = this.options;
        if(this.status === "IN_PROGRESS") {
            this.emit('error', 'cannot restart; listener is currently in progress.');
            return false;
        }

        this.status = 'IN_PROGRESS';
        this.action = ASRService.instance.createAudioAction();
        this.id = this.action.getId();

        // speech_to_text and incremental should never be emitted by 
        // ASR service if don't send speech_to_text
        this.action.on("speech_to_text_final", (data:ASRData) => {
            let speakerId = new SpeakerId(data.speaker_id);
            let listenResult = new ListenResults(data.utterances[0], null, data.utterances);
            // Clear, clean logging in the console, by popular demand.
            if(!listenResult.result.Input) {
                console.log("No utterances in ASR Response");
            }
            else {
                console.log("ASR returned", listenResult.result.Input);
            }
            this.action.stop(() => {
                this.emit('cloud', listenResult, speakerId);
                this.stop();
            });
        });

        this.action.on("speech_to_text_incremental", (data:ASRData) => {
            let incrementalResult:ListenResults = new ListenResults(data.utterances[0]);
            this.emit('incremental', incrementalResult);
        });

        this.action.on("hotphrase", (data:ASRData) => {
            this._hasHotphrase = true;
            this.emit('embedded',
                       data.utterances, 
                       data.speaker_id
                     );
            // emit the result, and if we've already gotten speaker ID we should stop the action
            // if we are not listening for stt.
            this._consolidateResults(options.speech_to_text === false);
        });

        this.action.on("speaker_id", (data:ASRData) => {
            this._hasSpeakerId = true;
            let speakerIdToEmit = data.speaker_id_record || data.speaker_id;
            this.emit('speaker-id',
                       speakerIdToEmit
                     );
            this._consolidateResults(options.speech_to_text === false);
        });
        this.action.on("end_of_speech", () => {
            this.emit('end');
        });
        this.action.on("start_of_speech", () => {
            this.emit('speech-start');
        });
        this.action.on('error', (message:string) => {
            this.emit('error', message);
        });

        let task:ASRRequestOptions = new ASRRequestOptions({});
        task.bargein = options.bargein;
        task.hotphrase = (options.heyJibo || options.hotphrase === "hey_jibo") ? "hey_jibo" : "";
        task.expectedDuration = options.expectedDuration;
        task.incremental = options.incremental === undefined ? false : options.incremental;
        task.known_speaker_id = options.authenticateSpeaker;
        task.language = options.language;
        task.metadata = options.metadata;
        task.nbest = options.nbest || 3;
        task.speech_to_text = options.speech_to_text;

        this.task = task;

        this.action.startAudioTask(task);    

        return true;
    }

    /**
     * explicit call to stop the listener and recognition task. 
     * Listener can still be restarted, but regardless of where
     * listener was in task, no more events will be emitted. 
     * Listeners are no longer subscribed.
     * @param {Function} [done] Callback when listener has stopped.
     * @method Listener#stop
     * @public
     */
    stop(done?) {
        if(!this.action || this.action.status === ActionStatus.STOPPED) {
            if(done) {
                done();
            }
            return;
        }
        this.stopCallbacks.push(done);
        if(this.action.status === ActionStatus.STOPPING) {
            // the action is stopping, and we will get the callback when it has
            // stopped by calling it through this.stopCallbacks.
            // Even though AudioAction.stop() can handle multiple asynchronous
            // calls to it, we want to only call it once.
            return;
        }
        this.action.stop(() => {
            this.stopCallbacks.forEach((callback) => {
                if(callback) {
                    callback();
                }
            });
            this.emit('finished');
            this.removeAllListeners();
            this.stopCallbacks = [];
        });
    }


    /**
     * Remove listeners, stop any live actions. 
     * @method Listener#destroy
     * @public
     */
    destroy() {
        this.removeAllListeners();
        if(this.action) {
            this.action.stop();
        }
    }

    /**
     * Stop the action if we've gotten speaker ID and hotphrase, and
     * we should be stopping the action.
     * @method Listener#_consolidateResults
     * @private
     */
    private _consolidateResults(shouldStop) {
        if(this._hasHotphrase && this._hasSpeakerId) {
            this._hasHotphrase = false;
            this._hasSpeakerId = false;
            if(shouldStop) {
                this.stop();
            }
        }
    }
}

export default Listener;