/*
Status Handler runs as an event which wil be polled every X amount of time.
This essentially controls all the events that will happen.
*/

import SystemManagerClient from "../../../clients/SystemManagerClient";

class StatusHandler{
    private listener;
    
    constructor(){
        this.listener = null;
    }
    
    public status(callback){
        SystemManagerClient.instance.wifiStatus(callback);
    }
    
    public listen(interval, callback) {
        if(this.listener === null) {
            //this.systemManager.wifiStatus(callback)
            this.listener = setInterval(() => {
                SystemManagerClient.instance.wifiStatus(callback);
            }, interval);
        }
        else{
            clearInterval(this.listener);
            //this.systemManager.wifiStatus(callback)
            this.listener = setInterval(() => {
                SystemManagerClient.instance.wifiStatus(callback);
            }, interval);
        }
    }
    
    public StopListener(){
        clearInterval(this.listener);
    }
}

export default StatusHandler;